  // Indexado por "classificacao" (o código hierárquico oficial, ex.: "1.01.01.01.01"), que é
  // o valor guardado no campo refRFB de cada conta do Plano de Contas do sistema. Uma
  // dúzia de classificações se repete na tabela oficial (mesma classificação usada por mais
  // de uma conta do referencial); nesses raríssimos casos fica valendo a primeira ocorrência.
  var RFB_REFERENCIAL_POR_CLASSIF = {};
  RFB_REFERENCIAL.forEach(function(r){
    if(!RFB_REFERENCIAL_POR_CLASSIF[r.classificacao]) RFB_REFERENCIAL_POR_CLASSIF[r.classificacao] = r;
  });
  // [{id, codigo, nome, tipo:"sintetica"|"analitica", natureza:"Débito"|"Crédito", grupo,
  //   refRFB:codigoRFB|null}] (ou, contas legadas — cadastradas antes da hierarquia:
  //   {id, nome, categoria}, sem código/tipo/natureza/grupo). A hierarquia (conta pai) não é
  //   armazenada à parte: é sempre derivada do prefixo do "codigo" (ver codigoPaiDe/
  //   planoContasFilhos) — uma conta legada, sem código, é tratada como uma conta raiz solta.
  var planoContas = []; // backed by listaConfig/planoContas -> {contas:[...]}
  var regrasContabeis = {}; // {tipoValue: {modo:"fixa"|"auto", contaDebito:id|null, contaCredito:id|null, contaContrapartida:id|null}}
  var contasBancos = {}; // {bancoNomeAtual: contaId} — conta contábil vinculada a cada banco cadastrado
  var contasDespesas = {}; // {itemPagamentoRecebimento: contaId} — conta contábil de cada item de Pagamento/Recebimento

  // ---- Plano de Contas: leitura uniforme (contas novas c/ hierarquia x contas legadas) ----
  function grupoDeConta(c){
    if(c.grupo) return c.grupo;
    var m = CATEGORIA_LEGADA_PARA_GRUPO_NATUREZA[c.categoria];
    return m ? m.grupo : "Outras";
  }
  function naturezaDeConta(c){
    if(c.natureza) return c.natureza;
    var m = CATEGORIA_LEGADA_PARA_GRUPO_NATUREZA[c.categoria];
    return m ? m.natureza : "Débito";
  }
  function categoriaDeConta(c){
    if(c.categoria) return c.categoria;
    var g = c.grupo, n = c.natureza;
    if(g === "Ativo") return "ativo";
    if(g === "Passivo") return "passivo";
    if(g === "Patrimônio Líquido") return "patrimonio";
    if(g === "Receita") return "receita";
    if(g === "Despesa") return "despesa";
    return n === "Crédito" ? "receita" : "despesa"; // "Outras" (contas de controle/apuração)
  }
  // ---- Disponibilidade do plano de contas e do referencial da Receita (bloqueada/oculta) ----
  // listaConfig/planoVisibilidade = { contas: {codigo: "bloqueada"|"oculta"}, rfb: {classificacao: ...} }.
  // Vale para o código marcado e tudo abaixo dele; "oculta" é mais forte que "bloqueada".
  var visPlano = { contas: {}, rfb: {} };
  function estadoVisCodigo(mapa, codigo){
    if(!codigo || !mapa) return "";
    var partes = String(codigo).split("."), est = "";
    for(var i = 1; i <= partes.length; i++){
      var v = mapa[partes.slice(0, i).join(".")];
      if(v === "oculta") return "oculta";
      if(v === "bloqueada") est = "bloqueada";
    }
    return est;
  }
  function estadoVisConta(c){ return c ? estadoVisCodigo(visPlano.contas, c.codigo) : ""; }
  function contaDisponivel(c){ return !estadoVisConta(c); }
  function estadoVisRfb(classif){ return estadoVisCodigo(visPlano.rfb, classif); }
  function contaEhAnalitica(c){ return c.tipo !== "sintetica"; } // contas legadas (sem tipo) contam como analítica
  function contaEhSintetica(c){ return c.tipo === "sintetica"; }
  function codigoPaiDe(codigo){
    if(!codigo) return null;
    var i = codigo.lastIndexOf(".");
    return i === -1 ? null : codigo.slice(0, i);
  }
  function planoContaPorCodigo(codigo){
    for(var i = 0; i < planoContas.length; i++){
      if(planoContas[i].codigo === codigo) return planoContas[i];
    }
    return null;
  }
  function planoContasFilhos(paiCodigo){
    return planoContas.filter(function(c){ return codigoPaiDe(c.codigo || "") === paiCodigo; })
      .sort(function(a, b){
        var ca = (a.codigo || "").split(".").map(Number), cb = (b.codigo || "").split(".").map(Number);
        for(var i = 0; i < Math.max(ca.length, cb.length); i++){
          var va = ca[i], vb = cb[i];
          if(va === undefined) return -1;
          if(vb === undefined) return 1;
          if(va !== vb) return va - vb;
        }
        return (a.nome || "").localeCompare(b.nome || "");
      });
  }
  function proximoCodigoFilho(paiCodigo){
    var filhos = planoContas.filter(function(c){ return codigoPaiDe(c.codigo || "") === paiCodigo; });
    // Largura do número: a mesma das contas irmãs já cadastradas (ex.: 1.1.4, 1.1.1.03,
    // 1.1.1.02.005). Sem irmãs, segue o padrão do plano por nível: 1, 1, 1, 2 e 3 dígitos.
    var nivelNovo = String(paiCodigo).split(".").length + 1;
    var PADRAO_LARGURA = { 1: 1, 2: 1, 3: 1, 4: 2, 5: 3 };
    var maxN = 0, largura = 0;
    filhos.forEach(function(c){
      var ultimo = (c.codigo || "").split(".").pop();
      if(/^\d+$/.test(ultimo)){
        largura = Math.max(largura, ultimo.length);
        maxN = Math.max(maxN, parseInt(ultimo, 10));
      }
    });
    if(!largura) largura = PADRAO_LARGURA[nivelNovo] || 3;
    var n = maxN + 1;
    return paiCodigo + "." + String(n).padStart(largura, "0");
  }

  // ---- CPF/CNPJ: máscara progressiva + validação (dígito verificador) ----
  function onlyDigits(s){ return String(s || "").replace(/\D/g, ""); }
  function validaCPF(cpf){
    cpf = onlyDigits(cpf);
    if(cpf.length !== 11 || /^(\d)\1{10}$/.test(cpf)) return false;
    var soma = 0, i, resto;
    for(i = 0; i < 9; i++){ soma += parseInt(cpf.charAt(i), 10) * (10 - i); }
    resto = (soma * 10) % 11; if(resto === 10 || resto === 11) resto = 0;
    if(resto !== parseInt(cpf.charAt(9), 10)) return false;
    soma = 0;
    for(i = 0; i < 10; i++){ soma += parseInt(cpf.charAt(i), 10) * (11 - i); }
    resto = (soma * 10) % 11; if(resto === 10 || resto === 11) resto = 0;
    if(resto !== parseInt(cpf.charAt(10), 10)) return false;
    return true;
  }
  function validaCNPJ(cnpj){
    cnpj = onlyDigits(cnpj);
    if(cnpj.length !== 14 || /^(\d)\1{13}$/.test(cnpj)) return false;
    var pesos1 = [5,4,3,2,9,8,7,6,5,4,3,2];
    var pesos2 = [6,5,4,3,2,9,8,7,6,5,4,3,2];
    function calc(base, pesos){
      var soma = 0;
      for(var i = 0; i < pesos.length; i++){ soma += parseInt(base.charAt(i), 10) * pesos[i]; }
      var resto = soma % 11;
      return resto < 2 ? 0 : 11 - resto;
    }
    if(calc(cnpj.substring(0,12), pesos1) !== parseInt(cnpj.charAt(12), 10)) return false;
    if(calc(cnpj.substring(0,13), pesos2) !== parseInt(cnpj.charAt(13), 10)) return false;
    return true;
  }
  // Detecta automaticamente Pessoa Física (CPF, até 11 dígitos) ou Jurídica (CNPJ, 12-14 dígitos)
  // conforme a quantidade de dígitos digitados, e aplica a máscara correspondente.
  function maskDocumento(raw){
    var digits = onlyDigits(raw).slice(0, 14);
    var tipoPessoa = digits.length > 11 ? "juridica" : "fisica";
    var masked = digits;
    if(tipoPessoa === "fisica"){
      if(digits.length > 9) masked = digits.replace(/^(\d{3})(\d{3})(\d{3})(\d{0,2}).*/, "$1.$2.$3-$4");
      else if(digits.length > 6) masked = digits.replace(/^(\d{3})(\d{3})(\d{0,3}).*/, "$1.$2.$3");
      else if(digits.length > 3) masked = digits.replace(/^(\d{3})(\d{0,3}).*/, "$1.$2");
    } else {
      if(digits.length > 12) masked = digits.replace(/^(\d{2})(\d{3})(\d{3})(\d{4})(\d{0,2}).*/, "$1.$2.$3/$4-$5");
      else if(digits.length > 8) masked = digits.replace(/^(\d{2})(\d{3})(\d{3})(\d{0,4}).*/, "$1.$2.$3/$4");
      else if(digits.length > 5) masked = digits.replace(/^(\d{2})(\d{3})(\d{0,3}).*/, "$1.$2.$3");
      else if(digits.length > 2) masked = digits.replace(/^(\d{2})(\d{0,3}).*/, "$1.$2");
    }
    return { digits: digits, masked: masked, tipoPessoa: tipoPessoa };
  }
  function documentoCompleto(info){
    return info.tipoPessoa === "fisica" ? info.digits.length === 11 : info.digits.length === 14;
  }
  function documentoValido(info){
    if(!documentoCompleto(info)) return false;
    return info.tipoPessoa === "fisica" ? validaCPF(info.digits) : validaCNPJ(info.digits);
  }

  function isFormaParcelada(nome){
    var lista = formasParceladas !== null ? formasParceladas : DEFAULT_FORMAS_PARCELADAS;
    return lista.indexOf(nome) !== -1;
  }

  function statusLancamento(d){
    if(!d.parcelado || !d.parcelas || !d.parcelas.length){
      return { label: "Pago", cls: "pago" };
    }
    var pagas = d.parcelas.filter(function(p){ return p.paga; }).length;
    if(pagas === d.parcelas.length){ return { label: "Pago", cls: "pago" }; }
    var base = (d.tipo === "receita" || d.tipo === "venda") ? "A Receber" : "A Pagar";
    if(d.competencia){
      var tot = 0, pg = 0;
      d.parcelas.forEach(function(p){ tot += valorParcela(d, p); pg += pagoParcela(d, p); });
      return { label: base + " — saldo " + brl(r2(tot - pg)) + (pg > 0 ? " (parcial)" : ""), cls: "pendente" };
    }
    return { label: base + " (" + pagas + "/" + d.parcelas.length + " pagas)", cls: "pendente" };
  }
  // Um lançamento normal tem 1 combinação de centro de custo/banco/forma de pagamento.
  // Um lançamento dividido (rateio) guarda várias em d.rateios. itensDe() normaliza os dois
  // formatos numa lista única, para que saldos, relatórios e status funcionem para ambos.
  function itensDe(d){
    if(d && d.rateios && d.rateios.length){ return d.rateios; }
    return [{ centroCusto: d && d.centroCusto, banco: d && d.banco, formaPagamento: d && d.formaPagamento, valor: d && d.valor, parcelado: d && d.parcelado, parcelas: d && d.parcelas }];
  }
  var LISTAS_BY_CAT = {
    empresas: EMPRESAS,
    despesas: DESPESAS,
    centrosCusto: CENTROS_CUSTO,
    historicos: HISTORICOS,
    fornecedores: FORNECEDORES,
    clientes: CLIENTES,
    bancos: BANCOS,
    formasPagamento: FORMAS_PAGAMENTO
  };
  var CAT_LABELS = {
    empresas: "Empresa",
    despesas: "Pagamento / Recebimento",
    centrosCusto: "Centro de Custo",
    historicos: "Histórico",
    fornecedores: "Fornecedor",
    clientes: "Cliente",
    bancos: "Banco",
    formasPagamento: "Forma de Pagamento"
  };
  var CAT_ORDER = ["empresas", "despesas", "centrosCusto", "historicos", "fornecedores", "clientes", "bancos", "formasPagamento"];
  // --------------------------------------------------------------------------

  function brl(n){
    return (n < 0 ? "-R$ " : "R$ ") + Math.abs(n).toLocaleString("pt-BR", {minimumFractionDigits:2, maximumFractionDigits:2});
  }
  function todayISO(){
    var d = new Date();
    var tz = d.getTimezoneOffset() * 60000;
    return new Date(d - tz).toISOString().slice(0,10);
  }
  function fmtDate(iso){
    if(!iso) return "";
    var p = iso.split("-");
    return p.length === 3 ? (p[2] + "/" + p[1] + "/" + p[0]) : iso;
  }
  function slugify(s){
    return String(s).normalize("NFD").replace(/[̀-ͯ]/g, "")
      .replace(/[^A-Za-z0-9]+/g, "_").replace(/^_+|_+$/g, "").toLowerCase();
  }
  function normalizarBusca(s){
    return String(s || "").normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase();
  }
  function contaId(empresa, banco){ return slugify(empresa) + "__" + slugify(banco); }

  // ---- Fechamento diário/mensal do caixa -----------------------------------
  var fechamentosDiarios = {}; // {"slugEmpresa__YYYY-MM-DD": {empresa,data,fechado,fechadoPor,fechadoEm,automatico}}
  var fechamentosMensais = {}; // {"slugEmpresa__YYYY-MM": {empresa,mes,fechado,fechadoPor,fechadoEm}}
  function dataISOFromDate(d){
    var tz = d.getTimezoneOffset() * 60000;
    return new Date(d - tz).toISOString().slice(0, 10);
  }
  function ehDiaUtil(d){ var dow = d.getDay(); return dow !== 0 && dow !== 6; }
  function proximoDiaUtil(dataISO){
    var d = new Date(dataISO + "T00:00:00");
    do{ d.setDate(d.getDate() + 1); } while(!ehDiaUtil(d));
    return d;
  }
  function prazoFechamentoAutomatico(dataISO){
    var prox = proximoDiaUtil(dataISO);
    prox.setHours(10, 0, 0, 0);
    return prox;
  }
  function chaveFechDia(empresa, data){ return slugify(empresa) + "__" + data; }
  function chaveFechMes(empresa, mes){ return slugify(empresa) + "__" + mes; }
  function mesDe(dataISO){ return dataISO ? dataISO.slice(0, 7) : ""; }
  function diaFechado(empresa, dataISO){
    if(!empresa || !dataISO) return false;
    var d = fechamentosDiarios[chaveFechDia(empresa, dataISO)];
    if(d && d.fechado) return true;
    var m = fechamentosMensais[chaveFechMes(empresa, mesDe(dataISO))];
    return !!(m && m.fechado);
  }
  function motivoFechado(empresa, dataISO){
    var m = fechamentosMensais[chaveFechMes(empresa, mesDe(dataISO))];
    if(m && m.fechado) return "mês " + mesDe(dataISO) + " fechado";
    var d = fechamentosDiarios[chaveFechDia(empresa, dataISO)];
    if(d && d.fechado) return "dia " + fmtDate(dataISO) + " fechado";
    return "";
  }

  function genRecoveryKey(){
    var chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"; // sem O/0, I/1 para evitar confusão
    function grupo(){
      var s = "";
      for(var i = 0; i < 4; i++){ s += chars.charAt(Math.floor(Math.random() * chars.length)); }
      return s;
    }
    return grupo() + "-" + grupo();
  }
  function normalizeKey(k){ return String(k || "").trim().toUpperCase(); }

  function fillSelect(sel, options, blankLabel){
    sel.innerHTML = "";
    if(blankLabel !== undefined){
      var b = document.createElement("option");
      b.value = ""; b.textContent = blankLabel;
      sel.appendChild(b);
    }
    options.forEach(function(o){
      var opt = document.createElement("option");
      opt.value = o; opt.textContent = o;
      sel.appendChild(opt);
    });
  }
  function fillDatalist(dl, options){
    dl.innerHTML = "";
    options.forEach(function(o){
      var opt = document.createElement("option");
      opt.value = o;
      dl.appendChild(opt);
    });
  }

  function genericToast(container, msg, isError){
    container.innerHTML = "";
    var d = document.createElement("div");
    d.className = "toast" + (isError ? " error" : "");
    d.textContent = msg;
    container.appendChild(d);
    setTimeout(function(){ if(container.contains(d)) container.removeChild(d); }, 4500);
  }

