  // ---- Filtro múltiplo com "Todos" (usado em "Filtrar por empresa" e "Banco", no Resumo) ----
  // "Todos" acompanha a lista ao vivo: se uma empresa/banco novo for cadastrado depois,
  // quem está em modo "Todos" passa a ver o novo item também, sem precisar reabrir nada.
  function criarFiltroMultiplo(rootId, btnId, panelId, optsId, cbTodosId){
    var root = document.getElementById(rootId);
    var btn = document.getElementById(btnId);
    var panel = document.getElementById(panelId);
    var optsWrap = document.getElementById(optsId);
    var cbTodos = document.getElementById(cbTodosId);
    if(!root || !btn || !panel || !optsWrap || !cbTodos) return null;

    var valoresDisponiveis = [];
    var modoTodos = true;
    var selecionados = []; // só é relevante quando modoTodos === false
    var onChangeCb = function(){};

    function atualizarBotao(){
      if(valoresDisponiveis.length === 0){ btn.textContent = "—"; return; }
      if(modoTodos){ btn.textContent = "Todos"; return; }
      if(selecionados.length === 0){ btn.textContent = "Nenhum selecionado"; return; }
      if(selecionados.length === 1){ btn.textContent = selecionados[0]; return; }
      btn.textContent = selecionados.length + " selecionadas";
    }

    function renderOpcoes(){
      optsWrap.innerHTML = "";
      valoresDisponiveis.forEach(function(v){
        var lbl = document.createElement("label");
        lbl.className = "ms-option";
        var cb = document.createElement("input");
        cb.type = "checkbox";
        cb.checked = modoTodos || selecionados.indexOf(v) !== -1;
        cb.addEventListener("change", function(){
          if(modoTodos){
            selecionados = valoresDisponiveis.filter(function(x){ return x !== v; });
            modoTodos = false;
          } else if(cb.checked){
            if(selecionados.indexOf(v) === -1){ selecionados.push(v); }
            if(selecionados.length === valoresDisponiveis.length){ modoTodos = true; selecionados = []; }
          } else {
            if(selecionados.length === 1 && selecionados[0] === v){
              cb.checked = true; // mantém sempre ao menos um selecionado
              return;
            }
            selecionados = selecionados.filter(function(x){ return x !== v; });
          }
          renderOpcoes();
          atualizarBotao();
          onChangeCb();
        });
        var span = document.createElement("span"); span.textContent = v;
        lbl.appendChild(cb); lbl.appendChild(span);
        optsWrap.appendChild(lbl);
      });
      cbTodos.checked = modoTodos;
    }

    cbTodos.addEventListener("change", function(){
      modoTodos = cbTodos.checked;
      if(!modoTodos){ selecionados = valoresDisponiveis.slice(); }
      renderOpcoes();
      atualizarBotao();
      onChangeCb();
    });

    btn.addEventListener("click", function(ev){
      ev.stopPropagation();
      var abrir = panel.hidden;
      document.querySelectorAll(".ms-select-panel").forEach(function(p){ p.hidden = true; });
      panel.hidden = !abrir;
    });
    panel.addEventListener("click", function(ev){ ev.stopPropagation(); });

    return {
      setValores: function(valores){
        valoresDisponiveis = valores.slice();
        if(!modoTodos){
          selecionados = selecionados.filter(function(v){ return valoresDisponiveis.indexOf(v) !== -1; });
          if(selecionados.length === 0){ modoTodos = true; }
        }
        renderOpcoes();
        atualizarBotao();
      },
      getSelecionados: function(){ return modoTodos ? valoresDisponiveis.slice() : selecionados.slice(); },
      getTodasSelecionadas: function(){ return modoTodos; },
      onChange: function(fn){ onChangeCb = fn; }
    };
  }
