      a.addEventListener("click", function(ev){ ev.preventDefault(); document.getElementById("rz-cat").value = cat; document.getElementById("rz-nome").value = x.nome; relAtual = "razao"; renderRelatorios(); renderRazao(); });
      tdN.appendChild(a); tdN.dataset.txt = x.nome; tr.appendChild(tdN);
      var cFx = td(faixaTxt); cFx.style.whiteSpace = "nowrap"; tr.appendChild(cFx);
