      var cC = td(cobr); if(x.protestado) cC.style.fontWeight = "700"; tr.appendChild(cC);
      var lim = limites[x.nome]; var cL = td(lim ? brl(lim) + (x.total > lim ? " ⚠" : "") : "—", "num"); if(lim) cL.dataset.v = lim; if(lim && x.total > lim) cL.title = "Em aberto acima do limite"; tr.appendChild(cL);
