      sel.value = o.tipo; tdT.appendChild(sel); tr.appendChild(tdT);
      var tdP = document.createElement("td"), inp = document.createElement("input"), selB = document.createElement("select");
      inp.type = "text"; inp.style.minWidth = "200px"; inp.value = o.parceiro || "";
      fillSelect(selB, activeList("bancos").filter(function(b){ return b !== document.getElementById("ofx-banco").value; }), "— outro banco —"); selB.value = o.outroBanco || "";
      tdP.appendChild(inp); tdP.appendChild(selB);
      var conf = document.createElement("div"); conf.className = "hint"; tdP.appendChild(conf);
      tr.appendChild(tdP);
      var tdTit = document.createElement("td"); tr.appendChild(tdTit);
      var tdX = document.createElement("td"), bx = document.createElement("button");
      bx.type = "button"; bx.className = "link-btn"; bx.textContent = "✕"; bx.title = "Remover esta linha da leitura";
      bx.addEventListener("click", function(){
        var k = ofxLinhas.indexOf(o); if(k !== -1) ofxLinhas.splice(k, 1);
        tr.remove();
        if(o.baixa) delete usados[o.baixa.docId + "#" + o.baixa.idx];
        if(!ofxLinhas.length) limparOfx(true);
      });
      tdX.appendChild(bx); tr.appendChild(tdX);
      function atualizarLinha(){
        var ehPart = o.tipo === "receita" || o.tipo === "despesa" || ((o.tipo === "despesa_financeira" || o.tipo === "receita_financeira" || o.tipo === "deposito_nao_identificado") && !!o.parceiro);
        inp.style.display = (o.tipo === "transferencia" || o.tipo === "ignorar") ? "none" : "";
        inp.placeholder = o.tipo === "receita" ? "Cliente" : (o.tipo === "despesa" ? "Fornecedor" : "(opcional)");
        inp.setAttribute("list", o.tipo === "receita" || o.tipo === "receita_financeira" || o.tipo === "deposito_nao_identificado" ? "ofx-dl-clientes" : "ofx-dl-fornecedores");
        selB.style.display = o.tipo === "transferencia" ? "" : "none";
        conf.textContent = o.confirmar && o.parceiro ? (o.parecido ? "confira: nome parecido (sugestão)" : "confira: achado pelo começo do nome") : (o.regra ? "escolha memorizada" : "");
        conf.style.color = o.confirmar && o.parceiro ? "#b54708" : "";
        tdTit.textContent = o.baixa ? (o.baixa.desc + (o.juros ? " · juros " + brl(o.juros) : "") + (o.desconto ? " · desconto " + brl(o.desconto) : "")) : ((o.tipo === "receita" || o.tipo === "despesa") && o.parceiro ? "sem título em aberto: " + (o.tipo === "receita" ? "recebimento" : "pagamento") + " direto" : "");
        tr.className = (o.tipo === "receita" || o.tipo === "despesa") && !o.parceiro ? "prev-vencido" : "";
      }
