  async function adicionarOfxRemessa(msg){
    var banco = document.getElementById("ofx-banco").value, centro = document.getElementById("ofx-centro").value;
    if(!banco){ genericToast(msg, "Escolha o banco do extrato.", true); return; }
    if(!centro){ genericToast(msg, "Escolha o centro de custo.", true); return; }
    var erros = [], itens = [], novasRegras = {};
    var temBoletoNaLeitura = ofxLinhas.some(function(o){ return !!o.boleto; });
    ofxLinhas.forEach(function(o, i){
      if(!o.incluir || o.jaImportado || o.tipo === "ignorar") return;
      var n = "Linha " + (i + 1) + " (" + brl(o.valor) + "): ";
      var forma = resolverValorLista("formasPagamento", o.forma || "") || resolverValorLista("formasPagamento", o.credito ? "DEPOSITO" : "PIX") || activeList("formasPagamento")[0];
      var base = { despesa: null, centroCusto: centro, historico: o.historico, fornecedor: null, banco: banco, formaPagamento: forma, valor: o.valor,
        arquivos: (o.boleto || !temBoletoNaLeitura) ? ofxDocs.slice() : [], parcelado: false, parcelas: [], rateios: [], direcaoDevolucao: null, dataPropria: o.data, ofxId: o.ofxId };
      if(o.tipo === "transferencia"){
        if(!o.outroBanco){ erros.push(n + "escolha o outro banco da transferência."); return; }
        var ori = o.credito ? o.outroBanco : banco, des = o.credito ? banco : o.outroBanco;
        var ct = resolverContabilParaImport("transferencia", null, null, null, ori, des, null);
        itens.push(Object.assign(base, { tipo: "transferencia", centroCusto: null, banco: null, formaPagamento: null, bancoOrigem: ori, bancoDestino: des, contaDebito: ct.contaDebito, contaCredito: ct.contaCredito }));
        novasRegras[chaveRegraOfx(o)] = { tipo: "transferencia", outroBanco: o.outroBanco };
        return;
      }
      var parceiro = null;
      if(o.parceiro){
        parceiro = resolverParticipanteImport(o.tipo === "despesa" || o.tipo === "despesa_financeira" ? "despesa" : "receita", null, o.parceiro);
        if(!parceiro){ erros.push(n + "\"" + o.parceiro + "\" não está cadastrado."); return; }
      }
      if((o.tipo === "receita" || o.tipo === "despesa") && !parceiro){ erros.push(n + "informe o " + (o.tipo === "receita" ? "cliente" : "fornecedor") + " ou mude o tipo."); return; }
      if(o.tipo === "receita" && !o.credito || o.tipo === "despesa" && o.credito){ erros.push(n + "o tipo não combina com a direção do valor no extrato."); return; }
      var item = TIPOS_FINANCEIROS[o.tipo] ? (o.item || itemFinanceiroPadrao(o.tipo)) : null;
      var ctb = resolverContabilParaImport(o.tipo, null, parceiro, banco, null, null, item);
      var it = Object.assign(base, { tipo: o.tipo, despesa: item, fornecedor: parceiro, contaDebito: ctb.contaDebito, contaCredito: ctb.contaCredito });
      if(o.baixa){
        it.baixas = [{ docId: o.baixa.docId, idx: o.baixa.idx, principal: o.baixa.principal }];
        it.juros = o.juros || 0; it.desconto = o.desconto || 0;
        it.valor = r2(o.baixa.principal - it.desconto);
        it.valorBanco = r2(o.baixa.principal + it.juros - it.desconto);
        if(Math.abs(it.valorBanco - o.valor) > 0.01){ erros.push(n + "principal + juros − desconto (" + brl(it.valorBanco) + ") não bate com o valor do extrato."); return; }
      }
      itens.push(it);
      if(!o.boleto) novasRegras[chaveRegraOfx(o)] = { tipo: o.tipo, parceiro: parceiro || "", item: item || null };
      else if(parceiro) novasRegras["BOLETO|" + normalizeTexto(o.boleto.sacado).replace(/\s+/g, " ").trim()] = { tipo: "receita", parceiro: parceiro };
    });
    if(erros.length){ genericToast(msg, erros.join(" | "), true); return; }
    if(!itens.length){ genericToast(msg, "Nenhuma linha marcada para adicionar.", true); return; }
    itens.forEach(function(x){ pending.push(x); });
    renderPending();
    ofxLinhas.forEach(function(o){ if(o.incluir && o.tipo !== "ignorar") o.jaImportado = true; });
    var comDoc = itens.filter(function(x){ return x.arquivos && x.arquivos.length; }).length;
    genericToast(msg, itens.length + " lançamento(s) adicionados à remessa" + (comDoc ? " (" + comDoc + " com o documento anexado)" : "") + ". Use \"Conferir remessa\" e depois \"Enviar lançamentos\". Depois pode usar \"Limpar\" para tirar a leitura da tela.", false);
    try{ Object.assign(ofxRegras, novasRegras); await db.doc("listaConfig/ofxRegras").set({ regras: ofxRegras }); }catch(e){}
  }
  function limparOfx(soLeitura){
    ofxLinhas = []; ofxInfo = null;
    document.getElementById("ofx-revisao").innerHTML = "";
    document.getElementById("ofx-toast").innerHTML = "";
    if(!soLeitura){ ofxArq = null; ofxBoletosArq = null; ofxDocs = []; }
    if(window.__ofxLista) window.__ofxLista();
  }
  (function ligarOfx(){
    var inO = document.getElementById("f-ofx"), inB = document.getElementById("f-ofx-boletos");
    if(!inO) return;
    var inD = document.getElementById("f-ofx-docs");
    function lista(){
      var box = document.getElementById("ofx-arquivos"); box.innerHTML = "";
      function item(rot, nome, remover){
        var sp = document.createElement("span"); sp.style.marginRight = "14px"; sp.textContent = rot + nome + " ";
        var b = document.createElement("button"); b.type = "button"; b.className = "link-btn"; b.textContent = "✕"; b.title = "Remover este arquivo";
        b.addEventListener("click", function(){ remover(); lista(); });
        sp.appendChild(b); box.appendChild(sp);
      }
      if(ofxArq) item("Extrato: ", ofxArq.name, function(){ ofxArq = null; });
      if(ofxBoletosArq) item("Boletos: ", ofxBoletosArq.name, function(){ ofxBoletosArq = null; });
      ofxDocs.forEach(function(f){ item("📎 ", f.name, function(){ ofxDocs = ofxDocs.filter(function(x){ return x !== f; }); }); });
    }
    window.__ofxLista = lista;
    document.getElementById("btn-ofx-arquivo").addEventListener("click", function(){ inO.click(); });
    document.getElementById("btn-ofx-boletos").addEventListener("click", function(){ inB.click(); });
    document.getElementById("btn-ofx-docs").addEventListener("click", function(){ inD.click(); });
    inO.addEventListener("change", function(){ ofxArq = inO.files[0] || null; inO.value = ""; lista(); });
    inB.addEventListener("change", function(){ ofxBoletosArq = inB.files[0] || null; inB.value = ""; lista(); });
    inD.addEventListener("change", function(){ Array.prototype.forEach.call(inD.files, function(f){ ofxDocs.push(f); }); inD.value = ""; lista(); });
    document.getElementById("btn-ofx-limpar").addEventListener("click", function(){ limparOfx(false); });
    var sb = document.getElementById("ofx-banco"), sc = document.getElementById("ofx-centro");
    function preencher(){ var vb = sb.value, vc = sc.value; fillSelect(sb, activeList("bancos"), "— banco —"); fillSelect(sc, activeList("centrosCusto"), "— centro de custo —"); sb.value = vb; sc.value = vc; }
    preencher();
    sb.addEventListener("focus", preencher); sc.addEventListener("focus", preencher);
    sb.addEventListener("change", function(){ sb.dataset.escolhido = "1"; });
    document.getElementById("btn-ofx-ler").addEventListener("click", async function(){
      var toast = document.getElementById("ofx-toast");
      if(!db){ genericToast(toast, "Armazenamento indisponível nesta visualização.", true); return; }
      genericToast(toast, "Lendo arquivos…", false);
      try{ if(await montarLinhasOfx()) genericToast(toast, ofxLinhas.length + " linha(s) lidas. Confira abaixo (em vermelho: falta o cliente/fornecedor).", false); }
      catch(err){ console.error(err); genericToast(toast, "Não foi possível ler: " + ((err && err.message) || err), true); }
    });
  })();

  (function ligarFeriados(){
    var b = document.getElementById("btn-feriados-save");
    if(!b) return;
    b.addEventListener("click", async function(){
      var toast = document.getElementById("feriados-toast");
      if(!db){ genericToast(toast, "Armazenamento indisponível nesta visualização.", true); return; }
      var linhas = document.getElementById("opcoes-feriados").value.split(/\n+/).map(function(x){ return x.trim(); }).filter(Boolean);
      var lista = [], erros = [];
      linhas.forEach(function(l){
        var m = l.match(/^(\d{1,2})\/(\d{1,2})(?:\/(\d{4}))?$/);
        if(!m || +m[1] < 1 || +m[1] > 31 || +m[2] < 1 || +m[2] > 12){ erros.push(l); return; }
        var dd = String(m[1]).padStart(2, "0"), mm = String(m[2]).padStart(2, "0");
        lista.push(m[3] ? (m[3] + "-" + mm + "-" + dd) : (mm + "-" + dd));
      });
      if(erros.length){ genericToast(toast, "Datas inválidas: " + erros.join(", ") + ". Use dd/mm ou dd/mm/aaaa.", true); return; }
      try{ await db.doc("listaConfig/feriados").set({ lista: lista }); genericToast(toast, "Feriados salvos (" + lista.length + ").", false); }
      catch(e){ genericToast(toast, "Não foi possível salvar agora. Tente novamente.", true); }
    });
  })();

  (function ligarNovosEventos(){
    var cond = document.getElementById("f-condicao");
    if(cond) cond.addEventListener("change", function(){ aplicarVisibilidadeNovosCampos(); atualizarCamposContabeis(); });
    ["f-juros", "f-desconto"].forEach(function(id){ var e = document.getElementById(id); if(e) e.addEventListener("input", recalcularValorBaixa); });
    elFornecedor.addEventListener("change", atualizarPainelTitulos);
    elFornecedor.addEventListener("change", function(){ if(tipoEhContabil(elTipo.value)) aplicarVisibilidadeNovosCampos(); });
    elFornecedor.addEventListener("change", atualizarStatusParticipante);
    elTipo.addEventListener("change", atualizarStatusParticipante);
    elValor.addEventListener("input", atualizarStatusParticipante);
    elFornecedor.addEventListener("change", function(){ if(tipoEhAdiantamento(elTipo.value) && elFornecedor.value) garantirContaAdiantamento(elTipo.value, elFornecedor.value); });
    elEmpresa.addEventListener("change", atualizarPainelTitulos);
    var bN = document.getElementById("btn-importar-nfe");
    if(bN) bN.addEventListener("click", importarNFes);
    var inArq = document.getElementById("f-import-nfe"), inPasta = document.getElementById("f-import-nfe-pasta");
    document.getElementById("btn-nfe-arquivos").addEventListener("click", function(){ inArq.click(); });
    document.getElementById("btn-nfe-pasta").addEventListener("click", function(){ inPasta.click(); });
    inArq.addEventListener("change", function(){ adicionarArquivosNfe(inArq.files); inArq.value = ""; });
    inPasta.addEventListener("change", function(){ adicionarArquivosNfe(inPasta.files); inPasta.value = ""; });
    var drop = document.getElementById("nfe-drop");
    function lerEntrada(entry, acc){
      return new Promise(function(res){
        if(entry.isFile){ entry.file(function(f){ acc.push(f); res(); }, function(){ res(); }); }
        else if(entry.isDirectory){
          var r = entry.createReader(), todos = [];
          (function lote(){ r.readEntries(function(es){ if(!es.length){ Promise.all(todos.map(function(e){ return lerEntrada(e, acc); })).then(res); } else { todos = todos.concat(Array.prototype.slice.call(es)); lote(); } }, function(){ res(); }); })();
        } else res();
      });
    }
    ["dragenter", "dragover"].forEach(function(ev){ drop.addEventListener(ev, function(e){ e.preventDefault(); drop.style.background = "var(--surface-2, #f2f4f2)"; }); });
    drop.addEventListener("dragleave", function(){ drop.style.background = ""; });
    drop.addEventListener("drop", async function(e){
      e.preventDefault(); drop.style.background = "";
      var itens = e.dataTransfer.items, acc = [];
      if(itens && itens.length && itens[0].webkitGetAsEntry){
        var entradas = Array.prototype.map.call(itens, function(it){ return it.webkitGetAsEntry(); }).filter(Boolean);
        await Promise.all(entradas.map(function(en){ return lerEntrada(en, acc); }));
      } else acc = Array.prototype.slice.call(e.dataTransfer.files || []);
      adicionarArquivosNfe(acc);
    });
    ["prev-empresa", "prev-natureza"].forEach(function(id){ var e = document.getElementById(id); if(e) e.addEventListener("change", renderPrevisto); });
  })();

  // ---- Tabs ----------------------------------------------------------
  tabButtons.forEach(function(btn){
    btn.addEventListener("click", function(){
      tabButtons.forEach(function(b){ b.classList.remove("active"); b.setAttribute("aria-selected","false"); });
      btn.classList.add("active");
      btn.setAttribute("aria-selected","true");
      Object.keys(sections).forEach(function(k){ sections[k].hidden = (k !== btn.dataset.tab); });
      if(btn.dataset.tab === "saldos"){ carregarSaldosParticipantes(); }
      if(btn.dataset.tab === "previsto"){ renderPrevisto(); }
      if(btn.dataset.tab === "relatorios"){ renderRelatorios(); Promise.all([garantirIndice("fornecedores"), garantirIndice("clientes")]).then(renderRelatorios); }
      if(btn.dataset.tab === "cadastro"){ renderAvisoIndice(); }
      if(btn.dataset.tab !== "preencher") splitDireita = btn.dataset.tab;
      ajustarSplit();
    });
  });

  // ---- Tela dividida ----
  var splitAtivo = false, splitDireita = "cadastro";
  try{ splitAtivo = localStorage.getItem("fluxo_split") === "1"; splitDireita = localStorage.getItem("fluxo_split_dir") || "cadastro"; }catch(e){}
  var mqSplit = window.matchMedia ? window.matchMedia("(min-width: 1100px)") : null;
  function splitPossivel(){
    var bP = null; tabButtons.forEach(function(b){ if(b.dataset.tab === "preencher") bP = b; });
    return splitAtivo && (!mqSplit || mqSplit.matches) && bP && !bP.hidden;
  }
  function botaoDaAba(k){ var r = null; tabButtons.forEach(function(b){ if(b.dataset.tab === k) r = b; }); return r; }
  function ajustarSplit(){
    var wrap = document.getElementById("app-screen");
    var btnS = document.getElementById("btn-split");
    if(btnS) btnS.setAttribute("aria-pressed", splitAtivo ? "true" : "false");
    Object.keys(sections).forEach(function(k){ sections[k].classList.remove("split-dir"); });
    if(!splitPossivel()){
      wrap.classList.remove("split");
      // ao sair da divisão, fica só a aba marcada
      var at = null; tabButtons.forEach(function(b){ if(b.classList.contains("active")) at = b.dataset.tab; });
      if(at) Object.keys(sections).forEach(function(k){ sections[k].hidden = (k !== at); });
      return;
    }
    var bDir = botaoDaAba(splitDireita);
    if(!bDir || bDir.hidden || splitDireita === "preencher"){
      splitDireita = null;
      tabButtons.forEach(function(b){ if(!splitDireita && b.dataset.tab !== "preencher" && !b.hidden) splitDireita = b.dataset.tab; });
      bDir = botaoDaAba(splitDireita);
    }
    try{ localStorage.setItem("fluxo_split_dir", splitDireita || ""); }catch(e){}
    wrap.classList.add("split");
    Object.keys(sections).forEach(function(k){ sections[k].hidden = !(k === "preencher" || k === splitDireita); });
    if(sections[splitDireita]){
      sections[splitDireita].classList.add("split-dir");
      sections[splitDireita].setAttribute("data-split-titulo", bDir ? bDir.textContent : "");
    }
    tabButtons.forEach(function(b){
      var on = b.dataset.tab === "preencher" || b.dataset.tab === splitDireita;
      b.classList.toggle("active", on); b.setAttribute("aria-selected", on ? "true" : "false");
    });
    if(splitDireita === "saldos"){ carregarSaldosParticipantes(); }
    if(splitDireita === "previsto"){ renderPrevisto(); }
    if(splitDireita === "relatorios"){ renderRelatorios(); }
    if(splitDireita === "cadastro"){ renderAvisoIndice(); }
  }
  (function(){
    var btnS = document.getElementById("btn-split");
    if(btnS) btnS.addEventListener("click", function(){
      splitAtivo = !splitAtivo;
      try{ localStorage.setItem("fluxo_split", splitAtivo ? "1" : "0"); }catch(e){}
      if(!splitAtivo){
        // volta para a aba da direita (ou Preencher) como aba única
        var alvo = botaoDaAba(splitDireita) || botaoDaAba("preencher");
        tabButtons.forEach(function(b){ b.classList.toggle("active", b === alvo); b.setAttribute("aria-selected", b === alvo ? "true" : "false"); });
      }
      ajustarSplit();
    });
    if(mqSplit){ var f = function(){ ajustarSplit(); }; if(mqSplit.addEventListener) mqSplit.addEventListener("change", f); else if(mqSplit.addListener) mqSplit.addListener(f); }
  })();


  // ---- Visualizar / baixar anexos (comprovantes) dentro da página ----
  // Abrir "/_blob/<id>" numa nova aba não funciona no visualizador do claude.ai; por isso o arquivo é
  // buscado aqui dentro, mostrado numa janela (PDF desenhado com o pdf.js, imagem direto) e o
  // download passa pela capability downloads.
  var EXT_POR_TIPO = { "application/pdf": "pdf", "image/png": "png", "image/jpeg": "jpg", "image/webp": "webp", "image/gif": "gif" };
  async function abrirAnexo(id, titulo, nomeArquivo){
    var ov = document.createElement("div"); ov.className = "anexo-ov";
    var box = document.createElement("div"); box.className = "anexo-box";
    var bar = document.createElement("div"); bar.className = "anexo-bar";
    var tt = document.createElement("strong"); tt.textContent = titulo; bar.appendChild(tt);
    var bBaixar = document.createElement("button"); bBaixar.type = "button"; bBaixar.className = "primary"; bBaixar.textContent = "Baixar"; bBaixar.disabled = true;
    var bFechar = document.createElement("button"); bFechar.type = "button"; bFechar.className = "secondary"; bFechar.textContent = "Fechar";
    bar.appendChild(bBaixar); bar.appendChild(bFechar);
    var corpo = document.createElement("div"); corpo.className = "anexo-corpo"; corpo.textContent = "Carregando o anexo…";
    var aviso = document.createElement("div"); aviso.style.margin = "6px 0";
    box.appendChild(bar); box.appendChild(aviso); box.appendChild(corpo); ov.appendChild(box); document.body.appendChild(ov);
    function fechar(){ ov.remove(); document.removeEventListener("keydown", esc); }
    function esc(e){ if(e.key === "Escape") fechar(); }
    bFechar.addEventListener("click", fechar); ov.addEventListener("click", function(e){ if(e.target === ov) fechar(); });
    document.addEventListener("keydown", esc);
    var blob;
    try{
      var resp = await fetch(/^[0-9a-f]{32}$/i.test(String(id)) ? "/_blob/" + id : id);
      if(!resp.ok) throw new Error("HTTP " + resp.status);
      blob = await resp.blob();
    }catch(err){ corpo.textContent = "Não foi possível carregar o anexo (" + ((err && err.message) || err) + ")."; return; }
    var tipo = (blob.type || "").split(";")[0];
    var ext = EXT_POR_TIPO[tipo] || "pdf";
    var nome = nomeArquivo && /\.[A-Za-z0-9]{2,5}$/.test(nomeArquivo) ? nomeArquivo : (String(titulo).normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^A-Za-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 60) || "anexo") + "." + ext;
    bBaixar.disabled = !downloadsCap;
    if(!downloadsCap) bBaixar.title = "Download indisponível nesta visualização";
    bBaixar.addEventListener("click", async function(){
      try{ await downloadsCap.save({ filename: nome, data: blob }); genericToast(aviso, "Baixado: " + nome, false); }
      catch(e){ if(!(e && e.code === "declined")) genericToast(aviso, "Não foi possível baixar (" + ((e && (e.code || e.message)) || e) + ").", true); }
    });
    corpo.textContent = "";
    if(tipo.indexOf("image/") === 0){
      var img = document.createElement("img"); img.src = URL.createObjectURL(blob); img.style.maxWidth = "100%"; corpo.appendChild(img); return;
    }
    try{
      var lib = await carregarPdfJs();
      var pdf = await lib.getDocument({ data: new Uint8Array(await blob.arrayBuffer()) }).promise;
      var largura = Math.min(900, corpo.clientWidth || 800);
      for(var pg = 1; pg <= pdf.numPages; pg++){
        var page = await pdf.getPage(pg);
        var v0 = page.getViewport({ scale: 1 }), esc2 = largura / v0.width, vp = page.getViewport({ scale: esc2 * (window.devicePixelRatio || 1) });
        var cv = document.createElement("canvas"); cv.width = vp.width; cv.height = vp.height; cv.style.width = largura + "px"; cv.className = "anexo-pag";
        corpo.appendChild(cv);
        await page.render({ canvasContext: cv.getContext("2d"), viewport: vp }).promise;
      }
    }catch(err){ corpo.textContent = "Não consegui mostrar o arquivo aqui (" + ((err && err.message) || err) + "). Use o botão Baixar."; }
  }
  // ---- db / assets / downloads capabilities ----------------------------
  var db = null;
  var assets = null;
  var downloadsCap = null;
  var allDocs = [];
  var allSaldos = [];

  async function submitLancamentos(){
    if(!db){ showToast("Armazenamento indisponível nesta visualização.", true); return; }
    if(pending.length === 0){ showToast("Adicione ao menos um item antes de enviar.", true); return; }
    var empresaSelecionada = elEmpresa.value;
    var data = elData.value || todayISO();
    if(!empresaSelecionada){ showToast("Selecione a empresa.", true); return; }

    var paraTodas = empresaSelecionada === TODOS_EMPRESAS_VALUE;
    if(paraTodas && pending.some(function(r){ return r.tipo === "transferencia"; })){
      showToast("Não é possível lançar uma transferência entre contas para \"Todos\". Selecione uma empresa específica.", true);
      return;
    }
    var empresasAlvo;
    if(paraTodas){
      var allow = allowedEmpresasForUser(currentUser);
      empresasAlvo = activeList("empresas").filter(function(e){ return allow.indexOf(e) !== -1; });
      if(empresasAlvo.length === 0){ showToast("Nenhuma empresa disponível para lançar no momento.", true); return; }
    } else {
      empresasAlvo = [empresaSelecionada];
    }

    var datasEnvio = [data].concat(pending.map(function(r){ return r.dataPropria; }).filter(Boolean));
    var empresasFechadas = empresasAlvo.filter(function(e){ return datasEnvio.some(function(dt){ return diaFechado(e, dt); }); });
    if(empresasFechadas.length > 0 && !canEditLancamentos()){
      showToast("Não é possível lançar: " + fmtDate(data) + " já está fechado para " + empresasFechadas.join(", ") + ". Apenas administrador ou supervisor pode alterar datas retroativas de um período fechado.", true);
      return;
    }

    if(paraTodas && pending.some(function(r){ return (r.baixas && r.baixas.length) || r.competencia; })){
      showToast("Compras, Vendas e baixas de contas precisam de uma empresa específica (não \"Todos\").", true);
      return;
    }
    elSubmit.disabled = true;
    elSubmit.textContent = "Enviando…";
    try{
      var col = db.collection("lancamentos");
      var uploadsFeitos = new Map(); // mesmo arquivo anexado a vários lançamentos sobe uma vez só
      for(var i = 0; i < pending.length; i++){
        var r = pending[i];
        var comprovantes = [];
        if(assets && r.arquivos && r.arquivos.length){
          for(var j = 0; j < r.arquivos.length; j++){
            try{
              var idUp = uploadsFeitos.get(r.arquivos[j]);
              if(!idUp){ var uploaded = await assets.upload(r.arquivos[j]); idUp = uploaded.id; uploadsFeitos.set(r.arquivos[j], idUp); }
              comprovantes.push(idUp);
            }catch(upErr){ /* segue sem esse anexo específico */ }
          }
        }
        for(var k = 0; k < empresasAlvo.length; k++){
          await gravarLancamentoCompleto(col, r, empresasAlvo[k], r.dataPropria || data, comprovantes, paraTodas);
        }
      }
      var msg = paraTodas
        ? (pending.length + " lançamento(s) enviado(s) para todas as " + empresasAlvo.length + " empresas (" + fmtDate(data) + "). Valor lançado integralmente em cada uma, sem dividir.")
        : (pending.length + " lançamento(s) enviado(s) para " + empresaSelecionada + " (" + fmtDate(data) + ").");
      if(empresasFechadas.length > 0){
        msg += " Atenção: " + fmtDate(data) + " estava fechado para " + empresasFechadas.join(", ") + " — lançado mesmo assim por permissão de administrador/supervisor.";
      }
      showToast(msg, false);
      pending = [];
      renderPending();
    }catch(err){
      showToast("Não foi possível enviar agora. Tente novamente.", true);
    }finally{
      elSubmit.disabled = false;
      elSubmit.textContent = "Enviar lançamentos";
    }
  }
  elSubmit.addEventListener("click", submitLancamentos);

  // ---- Saldos: cálculo compartilhado --------------------------------------
  function saldosIniciaisMap(){
    var map = {};
    allSaldos.forEach(function(doc){
      var d = doc.data();
      if(!d || !d.empresa || !d.banco) return;
      map[contaId(d.empresa, d.banco)] = d.saldoInicial || 0;
    });
    return map;
  }
  // Data a partir da qual o saldo inicial de cada conta (empresa + banco) é válido —
  // ou seja, quando os lançamentos daquela conta começaram a ser feitos no sistema.
  // Guardada separadamente porque nem toda conta antiga tem essa data preenchida.
  function saldosIniciaisDatasMap(){
    var map = {};
    allSaldos.forEach(function(doc){
      var d = doc.data();
      if(!d || !d.empresa || !d.banco) return;
      map[contaId(d.empresa, d.banco)] = d.dataInicial || null;
    });
    return map;
  }
  function movimentadoPorConta(){
    var map = {};
    function addDelta(empresa, banco, delta){
      if(!banco) return;
      var key = contaId(empresa, banco);
      if(!map[key]) map[key] = { empresa: empresa, banco: banco, movimentado: 0 };
      map[key].movimentado += delta;
    }
    allDocs.forEach(function(doc){
      var d = doc.data();
      if(!d || !d.empresa) return;
      if(d.tipo === "transferencia"){
        if(typeof d.valor !== "number") return;
        addDelta(d.empresa, d.bancoOrigem, -d.valor);
        addDelta(d.empresa, d.bancoDestino, d.valor);
        return;
      }
      itensDe(d).forEach(function(item){
        if(!item || !item.banco || typeof item.valor !== "number") return;
        var delta = (direcaoEfetiva(d) === "receita") ? item.valor : -item.valor;
        addDelta(d.empresa, item.banco, delta);
      });
    });
    return map;
  }
  // Calcula, em ordem cronológica, o saldo de UMA conta (empresa + banco) logo após
  // cada lançamento que a afeta — como um extrato bancário. Usado para conferência:
  // a pessoa lança na mesma ordem do extrato do banco e compara o saldo aqui com o de lá.
  function calcularSaldosBanco(empresa, banco){
    var saldoInicial = saldosIniciaisMap()[contaId(empresa, banco)] || 0;
    var dataSaldoInicial = saldosIniciaisDatasMap()[contaId(empresa, banco)] || null;
    var relevantes = allDocs.filter(function(doc){
      var d = doc.data();
      if(!d || d.empresa !== empresa) return false;
      if(d.tipo === "transferencia"){
        return d.bancoOrigem === banco || d.bancoDestino === banco;
      }
      return itensDe(d).some(function(it){ return it && it.banco === banco; });
    }).sort(function(a, b){
      var da = a.data() || {}, dbb = b.data() || {};
      var cmp = (da.data || "").localeCompare(dbb.data || "");
      if(cmp !== 0) return cmp;
      return (da.createdAt || "").localeCompare(dbb.createdAt || "");
    });
    var saldoCorrente = saldoInicial;
    var porDoc = {};
    relevantes.forEach(function(doc){
      var d = doc.data();
      var delta = 0;
      if(d.tipo === "transferencia"){
        if(d.bancoOrigem === banco){ delta -= (typeof d.valor === "number" ? d.valor : 0); }
        if(d.bancoDestino === banco){ delta += (typeof d.valor === "number" ? d.valor : 0); }
      } else {
        var sinal = (direcaoEfetiva(d) === "receita") ? 1 : -1;
        itensDe(d).forEach(function(it){
          if(it && it.banco === banco && typeof it.valor === "number"){ delta += sinal * it.valor; }
        });
      }
      saldoCorrente += delta;
      porDoc[doc.id] = saldoCorrente;
    });
    return { porDoc: porDoc, ordenados: relevantes, saldoInicial: saldoInicial, dataSaldoInicial: dataSaldoInicial };
  }

  // ---- Capa de impressão: lista dos lançamentos de um dia, de uma empresa e de um banco
  // específicos, com o saldo anterior, o saldo após cada linha e os totais — para conferir
  // com o extrato do banco ou anexar como capa de um malote/depósito. ----
  function montarCapaImpressao(){
    var empresasCapaSel = filtroEmpresaResumo ? filtroEmpresaResumo.getSelecionados() : [];
    var empresa = empresasCapaSel.length === 1 ? empresasCapaSel[0] : null;
    var bancosCapaSel = filtroBancoResumo ? filtroBancoResumo.getSelecionados() : [];
    var banco = bancosCapaSel.length === 1 ? bancosCapaSel[0] : null;
    var data = elLogDataFiltro ? elLogDataFiltro.value : "";
    if(!empresa){
      genericToast(elResumoToast, "Selecione exatamente uma empresa no filtro do Resumo antes de imprimir a capa.", true);
      return false;
    }
    if(!data){
      genericToast(elResumoToast, "Selecione uma data em \"Buscar lançamentos por data\" antes de imprimir a capa.", true);
      return false;
    }
    // Sem um banco escolhido: capa dos lançamentos que não passam por banco (Compras, Vendas,
    // Lançamentos Contábeis, notas importadas). Com um banco: capa do extrato daquele banco.
    if(!banco){ return montarCapaSemBanco(empresa, data); }

    var info = calcularSaldosBanco(empresa, banco);
    var doDia = info.ordenados.filter(function(doc){ var d = doc.data(); return d && d.data === data; });

    var saldoAnterior = info.saldoInicial;
    info.ordenados.forEach(function(doc){
      var d = doc.data();
      if(d.data && d.data < data){ saldoAnterior = info.porDoc[doc.id]; }
    });

    var totalGeral = 0;
    var porForma = {};

    function el(tag, opts){
      var e = document.createElement(tag);
      if(opts){
        if(opts.cls){ e.className = opts.cls; }
        if(opts.text !== undefined){ e.textContent = opts.text; }
      }
      return e;
    }

    elCapaImpressao.innerHTML = "";

    var header = el("div", { cls: "capa-header" });
    var headerLeft = document.createElement("div");
    headerLeft.appendChild(el("h1", { text: "Fluxo Diário — Capa de lançamentos" }));
    var meta = el("div", { cls: "capa-meta" });
    meta.appendChild(document.createTextNode("Empresa: " + empresa)); meta.appendChild(document.createElement("br"));
    meta.appendChild(document.createTextNode("Banco: " + banco)); meta.appendChild(document.createElement("br"));
    meta.appendChild(document.createTextNode("Data: " + fmtDate(data)));
    headerLeft.appendChild(meta);
    header.appendChild(headerLeft);
    var headerRight = el("div", { cls: "capa-meta" });
    headerRight.style.textAlign = "right";
    headerRight.appendChild(document.createTextNode("Emitido em: " + fmtDate(todayISO()))); headerRight.appendChild(document.createElement("br"));
    headerRight.appendChild(document.createTextNode("Por: " + (currentUser ? currentUser.usuario : "—")));
    header.appendChild(headerRight);
    elCapaImpressao.appendChild(header);

    var saldoAnteriorLinha = el("div", { cls: "capa-saldo-linha" });
    var labelSaldoAnterior = "Saldo anterior a " + fmtDate(data);
    if(info.dataSaldoInicial){ labelSaldoAnterior += " (saldo inicial registrado em " + fmtDate(info.dataSaldoInicial) + ")"; }
    saldoAnteriorLinha.appendChild(el("span", { text: labelSaldoAnterior }));
    saldoAnteriorLinha.appendChild(el("span", { text: brl(saldoAnterior) }));
    elCapaImpressao.appendChild(saldoAnteriorLinha);

    var tabela = el("table", { cls: "capa-tabela" });
    var thead = document.createElement("thead");
    var trHead = document.createElement("tr");
    ["Histórico", "Fornecedor/Cliente", "Tipo", "Forma Pgto.", "Valor", "Saldo"].forEach(function(txt, i){
      var th = el("th", { text: txt });
      if(i >= 4){ th.className = "num"; }
      trHead.appendChild(th);
    });
    thead.appendChild(trHead);
    tabela.appendChild(thead);
    var tbody = document.createElement("tbody");

    if(doDia.length === 0){
      var trVazia = document.createElement("tr");
      var tdVazia = el("td", { text: "Nenhum lançamento nesta conta, nesta data." });
      tdVazia.colSpan = 6;
      trVazia.appendChild(tdVazia);
      tbody.appendChild(trVazia);
    }

    doDia.forEach(function(doc){
      var d = doc.data();
      var tipoLinha, formaLinha, historicoLinha, fornecedorLinha, valorLinha;
      if(d.tipo === "transferencia"){
        tipoLinha = "Transferência";
        formaLinha = "—";
        historicoLinha = "Transferência: " + (d.bancoOrigem || "—") + " → " + (d.bancoDestino || "—");
        fornecedorLinha = "—";
        var sinalT = (d.bancoDestino === banco) ? 1 : -1;
        valorLinha = sinalT * (typeof d.valor === "number" ? d.valor : 0);
      } else {
        tipoLinha = tipoLabelExibir(d);
        historicoLinha = d.historico || "—";
        fornecedorLinha = d.fornecedor || "—";
        var itensDoBanco = itensDe(d).filter(function(it){ return it && it.banco === banco; });
        var somaBanco = itensDoBanco.reduce(function(s, it){ return s + (typeof it.valor === "number" ? it.valor : 0); }, 0);
        formaLinha = itensDoBanco.length === 1 ? (itensDoBanco[0].formaPagamento || "—") : (itensDoBanco.length > 1 ? "Dividido" : "—");
        var sinal = (direcaoEfetiva(d) === "receita") ? 1 : -1;
        valorLinha = sinal * somaBanco;
      }
      totalGeral += valorLinha;
      var formaKey = formaLinha || "—";
      porForma[formaKey] = (porForma[formaKey] || 0) + valorLinha;

      var tr = document.createElement("tr");
      tr.appendChild(el("td", { text: historicoLinha }));
      tr.appendChild(el("td", { text: fornecedorLinha }));
      tr.appendChild(el("td", { text: tipoLinha }));
      tr.appendChild(el("td", { text: formaLinha }));
      tr.appendChild(el("td", { cls: "num", text: brl(valorLinha) }));
      tr.appendChild(el("td", { cls: "num", text: brl(info.porDoc[doc.id]) }));
      tbody.appendChild(tr);
    });
    tabela.appendChild(tbody);
    elCapaImpressao.appendChild(tabela);

    var subtotais = el("div", { cls: "capa-subtotais" });
    subtotais.appendChild(el("strong", { text: "Subtotais por forma de pagamento" }));
    var tabSub = document.createElement("table");
    Object.keys(porForma).sort().forEach(function(forma){
      var trSub = document.createElement("tr");
      trSub.appendChild(el("td", { text: forma }));
      trSub.appendChild(el("td", { text: brl(porForma[forma]) }));
      tabSub.appendChild(trSub);
    });
    subtotais.appendChild(tabSub);
    elCapaImpressao.appendChild(subtotais);

    var totalLinha = el("div", { cls: "capa-total-geral" });
    totalLinha.appendChild(el("span", { text: "Total do dia (" + doDia.length + " lançamento(s))" }));
    totalLinha.appendChild(el("span", { text: brl(totalGeral) }));
    elCapaImpressao.appendChild(totalLinha);

    var saldoFinalLinha = el("div", { cls: "capa-saldo-linha" });
    saldoFinalLinha.appendChild(el("span", { text: "Saldo final em " + fmtDate(data) }));
    saldoFinalLinha.appendChild(el("span", { text: brl(saldoAnterior + totalGeral) }));
    elCapaImpressao.appendChild(saldoFinalLinha);

    elCapaImpressao.appendChild(el("p", { cls: "capa-rodape", text: "Gerado pelo Fluxo Diário — conferir com o extrato bancário antes de arquivar." }));

    return true;
  }
  // ---- Conferência da remessa: o que vai ser gravado e como ficam os saldos ----
  function montarConferenciaRemessa(){
    var box = document.getElementById("conf-remessa");
    box.innerHTML = "";
    function el(tag, txt, cls){ var e = document.createElement(tag); if(txt !== undefined) e.textContent = txt; if(cls) e.className = cls; return e; }
    function tabela(cab, linhas, numCols){
      var t = el("table", undefined, "capa-tabela rel-tab"), th = document.createElement("thead"), tr = document.createElement("tr");
      cab.forEach(function(c, i){ var h = el("th", c); if(numCols.indexOf(i) !== -1) h.className = "num"; tr.appendChild(h); });
      th.appendChild(tr); t.appendChild(th);
      var tb = document.createElement("tbody");
      linhas.forEach(function(l){
        var r = document.createElement("tr"); if(l._cls) r.className = l._cls;
        l.forEach(function(c, i){ r.appendChild(el("td", c, numCols.indexOf(i) !== -1 ? "num" : "")); });
        tb.appendChild(r);
      });
      t.appendChild(tb);
      var w = el("div", undefined, "table-scroll"); w.appendChild(t); return w;
    }
    var empresa = elEmpresa.value, dataForm = elData.value || todayISO();
    var paraTodas = empresa === TODOS_EMPRESAS_VALUE;
    var cab = el("div", undefined, "capa-meta");
    cab.textContent = "Empresa: " + (paraTodas ? "Todas" : (empresa || "—")) + "  ·  Data do formulário: " + fmtDate(dataForm) + "  ·  " + pending.length + " item(ns)  ·  Conferido por " + (currentUser ? currentUser.usuario : "—") + " em " + fmtDate(todayISO());
    box.appendChild(cab);
    if(!pending.length){ box.appendChild(el("p", "Nenhum item na remessa.", "footnote")); return; }

    // 1) Itens
    var avisos = [], porTipo = {}, total = 0;
    var linhas = pending.map(function(r){
      var dataItem = r.dataPropria || dataForm;
      var tipo = tipoLabelExibir(r);
      var banco = r.tipo === "transferencia" ? ((r.bancoOrigem || "—") + " → " + (r.bancoDestino || "—")) : ((r.rateios && r.rateios.length > 1) ? r.rateios.map(function(x){ return x.banco + " " + brl(x.valor); }).join(" + ") : (r.banco || "—"));
      var venc = (r.parcelas || []).map(function(p){ return fmtDate(p.vencimento) + " " + brl(typeof p.valor === "number" ? p.valor : 0); }).join(" · ");
      if(r.baixas && r.baixas.length) venc = "baixa de " + r.baixas.length + " título(s)" + (r.juros ? ", juros " + brl(r.juros) : "") + (r.desconto ? ", desconto " + brl(r.desconto) : "");
      if(!r.contaDebito || !r.contaCredito) avisos.push("Sem Conta Débito/Crédito: " + tipo + " " + (r.fornecedor || r.historico || "") + " (" + brl(r.valor) + ").");
      if(!paraTodas && empresa && diaFechado(empresa, dataItem)){ var avF = "A data " + fmtDate(dataItem) + " está fechada para " + empresa + ": só administrador ou supervisor consegue lançar nela."; if(avisos.indexOf(avF) === -1) avisos.push(avF); }
      porTipo[tipo] = r2((porTipo[tipo] || 0) + (r.valor || 0)); total = r2(total + (r.valor || 0));
      return [fmtDate(dataItem), tipo, r.fornecedor || "—", r.historico || "—", r.despesa || "—", banco, venc || "—",
        (nomeContaContabil(r.contaDebito) || "—") + " / " + (nomeContaContabil(r.contaCredito) || "—"), brl(r.valor || 0)];
    });
    box.appendChild(el("h4", "Lançamentos que serão gravados"));
    box.appendChild(tabela(["Data", "Tipo", "Fornecedor/Cliente", "Histórico", "Conta (item)", "Banco", "Vencimentos / baixa", "Débito / Crédito", "Valor"], linhas, [8]));
    var tl = Object.keys(porTipo).sort().map(function(t){ return [t, brl(porTipo[t])]; });
    var tt = ["Total da remessa", brl(total)]; tt._cls = "rel-total"; tl.push(tt);
    box.appendChild(tabela(["Tipo", "Total"], tl, [1]));

    if(paraTodas){ box.appendChild(el("p", "Saldos: escolha uma empresa específica para ver os saldos antes e depois do envio.", "footnote")); }
    else {
      // 2) Bancos: saldo atual, movimento desta remessa e saldo depois do envio
      var mov = {};
      function addB(b, v){ if(!b) return; mov[b] = r2((mov[b] || 0) + v); }
      pending.forEach(function(r){
        if(r.tipo === "transferencia"){ addB(r.bancoOrigem, -(r.valor || 0)); addB(r.bancoDestino, r.valor || 0); return; }
        var sinal = direcaoEfetiva(r) === "receita" ? 1 : (direcaoEfetiva(r) === "despesa" ? -1 : 0);
        if(!sinal) return;
        if(r.rateios && r.rateios.length){ r.rateios.forEach(function(x){ addB(x.banco, sinal * (x.valor || 0)); }); return; }
        if(r.banco){
          var v = (r.baixas && r.baixas.length && typeof r.valorBanco === "number") ? r.valorBanco : (r.valor || 0);
          addB(r.banco, sinal * v);
        }
      });
      var bancos = Object.keys(mov).sort();
      box.appendChild(el("h4", "Saldos dos bancos"));
      if(!bancos.length) box.appendChild(el("p", "Nenhum item desta remessa movimenta banco (Compras, Vendas e Lançamentos Contábeis não mexem no saldo).", "footnote"));
      else {
        box.appendChild(tabela(["Banco", "Saldo atual", "Movimento da remessa", "Saldo após o envio"], bancos.map(function(b){
          var info = calcularSaldosBanco(empresa, b);
          var atual = info.ordenados.length ? info.porDoc[info.ordenados[info.ordenados.length - 1].id] : info.saldoInicial;
          atual = r2(atual || 0);
          var l = [b, brl(atual), (mov[b] > 0 ? "+" : "") + brl(mov[b]), brl(r2(atual + mov[b]))];
          if(atual + mov[b] < -0.004) l._cls = "prev-vencido";
          return l;
        }), [1, 2, 3]));
      }
      // 3) Fornecedores e clientes: saldo em aberto antes e depois
      var parc = {};
      function addP(nome, nat, v, desc){
        if(!nome) return;
        var k = nat + "|" + nome, x = parc[k] = parc[k] || { nome: nome, nat: nat, mov: 0, desc: [] };
        x.mov = r2(x.mov + v); if(desc && x.desc.indexOf(desc) === -1) x.desc.push(desc);
      }
      pending.forEach(function(r){
        if(docEhTitulo(r)) addP(r.fornecedor, naturezaDoc(r), r.valor || 0, (r.parcelas || []).length + " parcela(s)" + (tipoEhContabil(r.tipo) ? " (lanç. contábil)" : ""));
        if(r.baixas && r.baixas.length){
          var pr = r2(r.baixas.reduce(function(s2, b){ return s2 + (b.principal || 0); }, 0));
          addP(r.fornecedor, r.tipo === "despesa" ? "pagar" : "receber", -pr, "baixa");
        } else if((r.tipo === "despesa" || r.tipo === "receita") && r.fornecedor){
          addP(r.fornecedor, r.tipo === "despesa" ? "pagar" : "receber", 0, r.tipo === "despesa" ? "pagamento direto, sem título" : "recebimento direto, sem título");
        }
      });
      var chaves = Object.keys(parc).sort();
      box.appendChild(el("h4", "Saldos de fornecedores e clientes (contas em aberto)"));
      if(!chaves.length) box.appendChild(el("p", "Nenhum item desta remessa altera contas a pagar ou a receber.", "footnote"));
      else {
        var totAnt = { pagar: 0, receber: 0 }, totDep = { pagar: 0, receber: 0 };
        var lp = chaves.map(function(k){
          var x = parc[k];
          var antes = r2(listarTitulos({ fornecedor: x.nome, empresa: empresa, natureza: x.nat, abertos: true }).reduce(function(s2, t){ return s2 + t.saldo; }, 0));
          var depois = r2(antes + x.mov);
          totAnt[x.nat] = r2(totAnt[x.nat] + antes); totDep[x.nat] = r2(totDep[x.nat] + depois);
          if(depois < -0.004) avisos.push("Baixa maior que o saldo em aberto de " + x.nome + ".");
          return [x.nome, x.nat === "pagar" ? "A pagar" : "A receber", brl(antes), (x.mov > 0 ? "+" : "") + brl(x.mov) + (x.desc.length ? " (" + x.desc.join(", ") + ")" : ""), brl(depois)];
        });
        ["pagar", "receber"].forEach(function(n){
          if(!chaves.some(function(k){ return parc[k].nat === n; })) return;
          var l = ["Total " + (n === "pagar" ? "a pagar" : "a receber") + " destes parceiros", "", brl(totAnt[n]), brl(r2(totDep[n] - totAnt[n])), brl(totDep[n])]; l._cls = "rel-total"; lp.push(l);
        });
        box.appendChild(tabela(["Fornecedor/Cliente", "Natureza", "Em aberto hoje", "Movimento da remessa", "Em aberto após o envio"], lp, [2, 3, 4]));
      }
    }
    if(avisos.length){
      box.appendChild(el("h4", "Avisos"));
      var ul = document.createElement("ul"); avisos.forEach(function(a){ ul.appendChild(el("li", a, "rel-aviso")); }); box.appendChild(ul);
    } else box.appendChild(el("p", "Nenhum aviso: contas contábeis preenchidas e datas abertas.", "rel-ok"));
  }
  (function ligarConferencia(){
    var wrap = document.getElementById("conf-remessa-wrap");
    document.getElementById("btn-conferir").addEventListener("click", function(){
      if(!pending.length){ showToast("Adicione ao menos um item antes de conferir.", true); return; }
      montarConferenciaRemessa(); wrap.hidden = false; wrap.scrollIntoView({ behavior: "smooth", block: "start" });
    });
    document.getElementById("btn-conf-fechar").addEventListener("click", function(){ wrap.hidden = true; });
    document.getElementById("btn-conf-baixar").addEventListener("click", async function(){
      var toast = document.getElementById("conf-toast");
      montarConferenciaRemessa();
      if(!downloadsCap){ genericToast(toast, "Download indisponível nesta visualização.", true); return; }
      var css = CAPA_CSS_INLINE + "h4{margin:16px 0 6px; font-size:14px;} .rel-total td{font-weight:700;} .rel-aviso{color:#b42318;} .rel-ok{color:#2f6b3f;} .prev-vencido td{color:#b42318;} .footnote{font-size:12px;}";
      var html = "<!DOCTYPE html><html lang=\"pt-BR\"><head><meta charset=\"UTF-8\"><title>Conferência da remessa</title><style>" + css + "</style></head><body><h1 style=\"font-size:20px;\">Fluxo Diário — Conferência da remessa</h1>" + document.getElementById("conf-remessa").innerHTML + "</body></html>";
      var nome = "conferencia-remessa-" + (slugify(elEmpresa.value || "") || "empresa") + "-" + todayISO() + ".html";
      try{ await downloadsCap.save({ filename: nome, data: new Blob([html], { type: "text/html;charset=utf-8" }) }); genericToast(toast, "Baixado \"" + nome + "\". Abra o arquivo e use Ctrl+P para imprimir.", false); }
      catch(err){ if(!(err && err.code === "declined")) genericToast(toast, "Não foi possível baixar agora.", true); }
    });
  })();

  function montarCapaSemBanco(empresa, data){
    function el(tag, opts){
      var e = document.createElement(tag);
      if(opts){ if(opts.cls){ e.className = opts.cls; } if(opts.text !== undefined){ e.textContent = opts.text; } }
      return e;
    }
    var doDia = (allDocs || []).filter(function(doc){
      var d = doc.data() || {};
      if(d.empresa !== empresa || d.data !== data) return false;
      if(d.tipo === "transferencia") return false;
      return !itensDe(d).some(function(it){ return it && it.banco; });
    }).sort(function(a, b){
      var x = a.data() || {}, y = b.data() || {};
      return (tipoLabelExibir(x)).localeCompare(tipoLabelExibir(y)) || (x.fornecedor || "").localeCompare(y.fornecedor || "");
    });
    elCapaImpressao.innerHTML = "";
    var header = el("div", { cls: "capa-header" });
    var hl = document.createElement("div");
    hl.appendChild(el("h1", { text: "Fluxo Diário — Capa de lançamentos sem banco" }));
    var meta = el("div", { cls: "capa-meta" });
    meta.appendChild(document.createTextNode("Empresa: " + empresa)); meta.appendChild(document.createElement("br"));
    meta.appendChild(document.createTextNode("Compras, Vendas e Lançamentos Contábeis (não movimentam banco)")); meta.appendChild(document.createElement("br"));
    meta.appendChild(document.createTextNode("Data: " + fmtDate(data)));
    hl.appendChild(meta); header.appendChild(hl);
    var hr = el("div", { cls: "capa-meta" }); hr.style.textAlign = "right";
    hr.appendChild(document.createTextNode("Emitido em: " + fmtDate(todayISO()))); hr.appendChild(document.createElement("br"));
    hr.appendChild(document.createTextNode("Por: " + (currentUser ? currentUser.usuario : "—")));
    header.appendChild(hr);
    elCapaImpressao.appendChild(header);
    var tabela = el("table", { cls: "capa-tabela" });
    var thead = document.createElement("thead"), trH = document.createElement("tr");
    ["Histórico", "Fornecedor/Cliente", "Tipo", "Conta", "Vencimentos", "Valor"].forEach(function(t, i){ var th = el("th", { text: t }); if(i === 5) th.className = "num"; trH.appendChild(th); });
    thead.appendChild(trH); tabela.appendChild(thead);
    var tbody = document.createElement("tbody"), porTipo = {}, total = 0;
    if(!doDia.length){ var tr0 = document.createElement("tr"), td0 = el("td", { text: "Nenhum lançamento sem banco nesta data." }); td0.colSpan = 6; tr0.appendChild(td0); tbody.appendChild(tr0); }
    doDia.forEach(function(doc){
      var d = doc.data() || {}, tipo = tipoLabelExibir(d), v = typeof d.valor === "number" ? d.valor : 0;
      var vencs = (d.parcelas || []).map(function(p){ return fmtDate(p.vencimento) + " " + brl(typeof p.valor === "number" ? p.valor : v / ((d.parcelas || []).length || 1)); }).join(" · ");
      var tr = document.createElement("tr");
      tr.appendChild(el("td", { text: d.historico || "—" }));
      tr.appendChild(el("td", { text: d.fornecedor || "—" }));
      tr.appendChild(el("td", { text: tipo }));
      tr.appendChild(el("td", { text: d.despesa || "—" }));
      tr.appendChild(el("td", { text: vencs || "—" }));
      tr.appendChild(el("td", { cls: "num", text: brl(v) }));
      tbody.appendChild(tr);
      porTipo[tipo] = (porTipo[tipo] || 0) + v; total += v;
    });
    tabela.appendChild(tbody); elCapaImpressao.appendChild(tabela);
    var sub = el("div", { cls: "capa-subtotais" });
    sub.appendChild(el("strong", { text: "Subtotais por tipo" }));
    var tabSub = document.createElement("table");
    Object.keys(porTipo).sort().forEach(function(t){ var trS = document.createElement("tr"); trS.appendChild(el("td", { text: t })); trS.appendChild(el("td", { text: brl(porTipo[t]) })); tabSub.appendChild(trS); });
    sub.appendChild(tabSub); elCapaImpressao.appendChild(sub);
    var tl = el("div", { cls: "capa-total-geral" });
    tl.appendChild(el("span", { text: "Total do dia (" + doDia.length + " lançamento(s))" }));
    tl.appendChild(el("span", { text: brl(total) }));
    elCapaImpressao.appendChild(tl);
    elCapaImpressao.appendChild(el("p", { cls: "capa-rodape", text: "Gerado pelo Fluxo Diário — lançamentos por competência; o dinheiro entra/sai só no Pagamento/Recebimento. Para a capa de um banco, escolha um único banco no filtro." }));
    return true;
  }
  if(elBtnImprimirCapa){
    elBtnImprimirCapa.addEventListener("click", function(){
      if(montarCapaImpressao()){ window.print(); }
    });
  }

  // ---- Baixar capa como arquivo HTML autônomo (alternativa mais confiável que window.print(),
  // que pode ser bloqueado dependendo de onde a página está hospedada). O usuário abre o
  // arquivo baixado em qualquer aba normal do navegador e usa Ctrl+P/Cmd+P por lá. ----
  var CAPA_CSS_INLINE = ".capa-header{display:flex; justify-content:space-between; align-items:flex-start; gap:16px; margin-bottom:14px; border-bottom:2px solid #000; padding-bottom:10px;}" +
    ".capa-header h1{font-size:20px; margin:0 0 4px;}" +
    ".capa-header .capa-meta{font-size:13px; line-height:1.5;}" +
    ".capa-saldo-linha{display:flex; justify-content:space-between; font-size:13.5px; font-weight:700; margin:6px 0; padding:6px 0; border-top:1px dashed #000; border-bottom:1px dashed #000;}" +
    ".capa-tabela{width:100%; border-collapse:collapse; font-size:12px; margin-top:10px;}" +
    ".capa-tabela th, .capa-tabela td{border:1px solid #000; padding:5px 6px; text-align:left;}" +
    ".capa-tabela th{background:#eee;}" +
    ".capa-tabela td.num, .capa-tabela th.num{text-align:right; font-variant-numeric:tabular-nums;}" +
    ".capa-subtotais{margin-top:14px; font-size:12.5px;}" +
    ".capa-subtotais table{border-collapse:collapse; margin-top:4px;}" +
    ".capa-subtotais td{padding:2px 10px 2px 0;}" +
    ".capa-total-geral{display:flex; justify-content:space-between; font-size:14px; font-weight:700; margin-top:14px; padding-top:10px; border-top:2px solid #000;}" +
    ".capa-rodape{margin-top:24px; font-size:11px; color:#444;}" +
    "body{font-family:Arial, Helvetica, sans-serif; color:#000; background:#fff; margin:24px; max-width:820px;}";
  async function baixarCapaHtml(){
    if(!montarCapaImpressao()){ return; }
    var empresasSlugSel = filtroEmpresaResumo ? filtroEmpresaResumo.getSelecionados() : [];
    var empresaSlug = slugify((empresasSlugSel.length === 1 ? empresasSlugSel[0] : "capa")) || "capa";
    var dataSlug = (elLogDataFiltro && elLogDataFiltro.value) ? elLogDataFiltro.value : todayISO();
    var nomeArquivo = "capa-" + empresaSlug + "-" + dataSlug + ".html";
    var htmlDoc = "<!DOCTYPE html><html lang=\"pt-BR\"><head><meta charset=\"UTF-8\">" +
      "<title>Capa de lançamentos</title><style>" + CAPA_CSS_INLINE + "</style></head><body>" +
      elCapaImpressao.innerHTML +
      "</body></html>";
    if(!downloadsCap){
      genericToast(elResumoToast, "O download de arquivos não está disponível aqui. Tente o botão \"Tentar imprimir direto\".", true);
      return;
    }
    var blob = new Blob([htmlDoc], { type: "text/html;charset=utf-8" });
    if(elBtnBaixarCapa){ elBtnBaixarCapa.disabled = true; }
    try{
      await downloadsCap.save({ filename: nomeArquivo, data: blob });
      genericToast(elResumoToast, "Capa baixada como \"" + nomeArquivo + "\". Abra o arquivo e use Ctrl+P (ou Cmd+P) para imprimir ou salvar como PDF.", false);
    }catch(err){
      var code = err && err.code;
      if(code === "declined"){
        // Usuário cancelou o download; não é um erro a reportar.
      } else if(code === "rate_limited"){
        genericToast(elResumoToast, "Já existe um download pendente de confirmação. Aguarde e tente novamente.", true);
      } else {
        genericToast(elResumoToast, "Não foi possível baixar a capa. Tente novamente ou use \"Tentar imprimir direto\".", true);
      }
    } finally {
      if(elBtnBaixarCapa){ elBtnBaixarCapa.disabled = false; }
    }
  }
  if(elBtnBaixarCapa){
    elBtnBaixarCapa.addEventListener("click", baixarCapaHtml);
  }

  function saldoAtualPorEmpresa(empresa){
    var iniciais = saldosIniciaisMap();
    var mov = movimentadoPorConta();
    var total = 0;
    fullList("bancos").forEach(function(b){
      var key = contaId(empresa, b);
      total += (iniciais[key] || 0) + (mov[key] ? mov[key].movimentado : 0);
    });
    return total;
  }

  function renderSaldos(){
    var iniciais = saldosIniciaisMap();
    var datas = saldosIniciaisDatasMap();
    var mov = movimentadoPorConta();
    var tbody = document.querySelector("#tbl-saldos tbody");
    tbody.innerHTML = "";
    var allow = allowedEmpresasForUser(currentUser);
    var rows = [];
    allow.forEach(function(empresa){
      fullList("bancos").forEach(function(banco){
        var key = contaId(empresa, banco);
        var inicial = iniciais.hasOwnProperty(key) ? iniciais[key] : null;
        var movimentado = mov[key] ? mov[key].movimentado : 0;
        if(inicial === null && movimentado === 0) return;
        rows.push({ empresa: empresa, banco: banco, dataInicial: datas[key] || null, inicial: inicial || 0, movimentado: movimentado, atual: (inicial || 0) + movimentado });
      });
    });
    if(rows.length === 0){
      var tr = document.createElement("tr");
      var td = document.createElement("td");
      td.colSpan = 6; td.className = "empty"; td.textContent = "Nenhum saldo inicial definido ainda.";
      tr.appendChild(td); tbody.appendChild(tr);
      return;
    }
    rows.forEach(function(r){
      var tr = document.createElement("tr");
      var cells = [r.empresa, r.banco, fmtDataBR(r.dataInicial), brl(r.inicial), brl(r.movimentado), brl(r.atual)];
      cells.forEach(function(val, i){
        var td = document.createElement("td");
        if(i >= 3) td.className = "num";
        td.textContent = val;
        tr.appendChild(td);
      });
      tbody.appendChild(tr);
    });
  }

  function fmtDataBR(iso){
    if(!iso) return "—";
    var parts = iso.split("-");
    if(parts.length !== 3) return iso;
    return parts[2] + "/" + parts[1] + "/" + parts[0];
  }

  function renderSaldosClientes(){
    var tbody = document.querySelector("#tbl-saldos-clientes tbody");
    if(!tbody) return;
    tbody.innerHTML = "";
    var canEdit = canEditLancamentos();
    var NUM_COLS = 9;
    function saldoBoleto(b){ var v = Number(b.valor) || 0; var pg = (typeof b.valorPago === "number") ? b.valorPago : (b.paga ? v : 0); return r2(v - pg); }

    // saldoInicial agora é { [empresa]: [ {valor, vencimento, paga}, ... ] } | null, um boleto por
    // linha (participante x empresa x boleto). "tipo" não é mais armazenado por boleto: é derivado
    // da coleção (clientesCadastro -> "receber", fornecedoresCadastro -> "pagar").
    function expandir(col, cadastro, tipo){
      var linhas = [];
      Object.keys(cadastro).forEach(function(slug){
        var d = cadastro[slug];
        if(!d || !d.saldoInicial) return;
        EMPRESAS.forEach(function(empresa){
          var lista = d.saldoInicial[empresa];
          if(!lista || !lista.length) return;
          lista.forEach(function(boleto, idx){
            linhas.push({ slug: slug, col: col, d: d, tipo: tipo, empresa: empresa, idx: idx, boleto: boleto });
          });
        });
      });
      linhas.sort(function(a, b){
        var byNome = (a.d.nome || "").localeCompare(b.d.nome || "");
        if(byNome !== 0) return byNome;
        return (a.empresa || "").localeCompare(b.empresa || "");
      });
      return linhas;
    }

    var linhasClientes = expandir("clientesCadastro", clientesCadastro, "receber");
    var linhasFornecedores = expandir("fornecedoresCadastro", fornecedoresCadastro, "pagar");

    var totalReceber = 0, totalPagar = 0;
    linhasClientes.concat(linhasFornecedores).forEach(function(row){
      var sb = saldoBoleto(row.boleto);
      if(sb <= 0.004) return;
      if(row.tipo === "receber") totalReceber += sb; else totalPagar += sb;
    });
    var elTotais = document.getElementById("saldos-clientes-totais");
    if(elTotais){
      elTotais.innerHTML = "";
      var sReceber = document.createElement("span"); sReceber.className = "receber"; sReceber.textContent = "Pendente a receber: " + brl(totalReceber);
      var sPagar = document.createElement("span"); sPagar.className = "pagar"; sPagar.textContent = "Pendente a pagar: " + brl(totalPagar);
      elTotais.appendChild(sReceber); elTotais.appendChild(sPagar);
    }

    if(linhasClientes.length === 0 && linhasFornecedores.length === 0){
      var tr0 = document.createElement("tr");
      var td0 = document.createElement("td");
      td0.colSpan = NUM_COLS; td0.className = "empty"; td0.textContent = "Nenhum saldo inicial de cliente/fornecedor cadastrado ainda.";
      tr0.appendChild(td0); tbody.appendChild(tr0);
      return;
    }

    function renderGrupo(titulo, linhas){
      var trGrupo = document.createElement("tr");
      var tdGrupo = document.createElement("td");
      tdGrupo.colSpan = NUM_COLS; tdGrupo.className = "group-title"; tdGrupo.textContent = titulo;
      tdGrupo.style.margin = "0"; tdGrupo.style.padding = "12px 8px 4px";
      trGrupo.appendChild(tdGrupo); tbody.appendChild(trGrupo);

      if(!linhas.length){
        var trVazio = document.createElement("tr");
        var tdVazio = document.createElement("td");
        tdVazio.colSpan = NUM_COLS; tdVazio.className = "empty"; tdVazio.textContent = "Nenhum saldo inicial cadastrado.";
        trVazio.appendChild(tdVazio); tbody.appendChild(trVazio);
        return;
      }

      linhas.forEach(function(row){
        var boleto = row.boleto;
        var tr = document.createElement("tr");

        var tdNome = document.createElement("td"); tdNome.textContent = row.d.nome; tr.appendChild(tdNome);
        var tdDoc = document.createElement("td"); tdDoc.textContent = row.d.documento || "—"; tr.appendChild(tdDoc);
        var tdEmpresa = document.createElement("td"); tdEmpresa.textContent = row.empresa; tr.appendChild(tdEmpresa);
        var tdTipo = document.createElement("td");
        var tagTipo = document.createElement("span");
        tagTipo.className = "tag " + (row.tipo === "receber" ? "receita" : "despesa");
        tagTipo.textContent = row.tipo === "receber" ? "A Receber" : "A Pagar";
        tdTipo.appendChild(tagTipo); tr.appendChild(tdTipo);
        var tdNDoc = document.createElement("td"); tdNDoc.textContent = boleto.documento || "—"; tr.appendChild(tdNDoc);
        var tdValor = document.createElement("td"); tdValor.className = "num"; tdValor.textContent = brl(boleto.valor); tr.appendChild(tdValor);
        var tdSaldoB = document.createElement("td"); tdSaldoB.className = "num"; tdSaldoB.textContent = brl(saldoBoleto(boleto)); tr.appendChild(tdSaldoB);
        var tdVenc = document.createElement("td"); tdVenc.textContent = fmtDataBR(boleto.vencimento); tr.appendChild(tdVenc);

        var tdStatus = document.createElement("td");
        if(canEdit){
          var lbl = document.createElement("label");
          lbl.className = "saldo-cli-status";
          var cb = document.createElement("input");
          cb.type = "checkbox"; cb.checked = !!boleto.paga;
          cb.addEventListener("change", async function(){
            cb.disabled = true;
            var valorAnterior = !boleto.paga; // estado antes deste clique (cb.checked já mudou)
            var saldoAtual = row.d.saldoInicial || {};
            var novaLista = (saldoAtual[row.empresa] || []).map(function(b, i){
              return i === row.idx ? Object.assign({}, b, { paga: cb.checked }) : b;
            });
            var novoSaldo = Object.assign({}, saldoAtual);
            novoSaldo[row.empresa] = novaLista;
            try{
              if(db){
                await db.doc(row.col + "/" + row.slug).update({ saldoInicial: novoSaldo });
                var cacheSaldo = row.col === "clientesCadastro" ? clientesCadastro : fornecedoresCadastro;
                cacheSaldo[row.slug] = Object.assign({}, cacheSaldo[row.slug] || row.d, { saldoInicial: novoSaldo });
                lbl.lastChild.textContent = cb.checked ? "Pago" : "Pendente";
                renderSaldosClientes();
              }
            }catch(err){
              cb.checked = valorAnterior;
            }finally{
              cb.disabled = false;
            }
          });
          lbl.appendChild(cb);
          lbl.appendChild(document.createTextNode(boleto.paga ? "Pago" : ((boleto.valorPago || 0) > 0 ? "Parcial" : "Pendente")));
          tdStatus.appendChild(lbl);
        } else {
          var tag = document.createElement("span");
          tag.className = "tag " + (boleto.paga ? "pago" : "pendente");
          tag.textContent = boleto.paga ? "Pago" : "Pendente";
          tdStatus.appendChild(tag);
        }
        tr.appendChild(tdStatus);
        tbody.appendChild(tr);
      });
    }

    renderGrupo("Clientes", linhasClientes);
    renderGrupo("Fornecedores", linhasFornecedores);
  }

  function loadSaldoIntoForm(){
    var empresa = elSaldoEmpresa.value, banco = elSaldoBanco.value;
    if(!empresa || !banco){ elSaldoInput.value = ""; if(elSaldoData){ elSaldoData.value = ""; } return; }
    var iniciais = saldosIniciaisMap();
    var datas = saldosIniciaisDatasMap();
    var key = contaId(empresa, banco);
    elSaldoInput.value = iniciais.hasOwnProperty(key) ? iniciais[key] : "";
    if(elSaldoData){ elSaldoData.value = datas.hasOwnProperty(key) && datas[key] ? datas[key] : ""; }
  }
  elSaldoEmpresa.addEventListener("change", loadSaldoIntoForm);
  elSaldoBanco.addEventListener("change", loadSaldoIntoForm);

  function showSaldoToast(msg, isError){ genericToast(elSaldoToast, msg, isError); }

  elSaldoSave.addEventListener("click", async function(){
    if(!db){ showSaldoToast("Armazenamento indisponível nesta visualização.", true); return; }
    var empresa = elSaldoEmpresa.value, banco = elSaldoBanco.value;
    var valor = parseFloat(elSaldoInput.value);
    var dataInicial = elSaldoData ? elSaldoData.value : "";
    if(!empresa || !banco){ showSaldoToast("Selecione empresa e banco.", true); return; }
    if(isNaN(valor)){ showSaldoToast("Informe um valor de saldo válido.", true); return; }
    if(!dataInicial){ showSaldoToast("Informe a data do saldo inicial (a partir de quando os lançamentos desta conta começaram).", true); return; }
    elSaldoSave.disabled = true;
    try{
      await db.doc("saldosIniciais/" + contaId(empresa, banco)).set({
        empresa: empresa, banco: banco, saldoInicial: valor, dataInicial: dataInicial, updatedAt: new Date().toISOString()
      });
      showSaldoToast("Saldo inicial de " + empresa + " / " + banco + " salvo.", false);
    }catch(err){
      showSaldoToast("Não foi possível salvar agora. Tente novamente.", true);
    }finally{
      elSaldoSave.disabled = false;
    }
  });

  // ---- Cadastro de Empresas (dados, quadro societário, documentos) ----------------
  function gerarIdCadastro(prefixo){
    return prefixo + "_" + Date.now().toString(36) + "_" + Math.random().toString(36).slice(2, 8);
  }
  function empresaCadastroVazio(){
    return { cnpj: "", razaoSocial: "", ie: "", nire: "", endereco: "", telefone: "", email: "", regimeTributario: "", documentos: [], socios: [] };
  }
  function getCadastroEmpresa(slug){
    return empresasCadastro[slug] || empresaCadastroVazio();
  }
  function erroAmigavel(msg){ var e = new Error(msg); e.friendlyMessage = msg; return e; }

  // Seção reutilizável de documentos por categoria (usada tanto no cadastro da empresa quanto
  // no cadastro de cada sócio). Cada categoria pode ter vários anexos ao longo do tempo — nunca
  // substitui um anterior sozinha, fica tudo com data de envio (e competência, se informada)
  // para consulta/histórico depois.
  function criarSecaoDocumentos(titulo, categorias, documentos, onAdd, onRemove){
    var box = document.createElement("div");
    box.style.marginTop = "8px";
    var titleEl = document.createElement("div");
    titleEl.className = "group-title";
    titleEl.textContent = titulo;
    box.appendChild(titleEl);

    categorias.forEach(function(categoria){
      var catBox = document.createElement("div");
      catBox.className = "doc-categoria";
      var catTitulo = document.createElement("div");
      catTitulo.className = "doc-categoria-titulo";
      catTitulo.textContent = categoria;
      catBox.appendChild(catTitulo);

      var entradas = documentos.filter(function(d){ return d.categoria === categoria; })
        .sort(function(a, b){ return (b.enviadoEm || "").localeCompare(a.enviadoEm || ""); });

      if(!entradas.length){
        var vazio = document.createElement("div");
        vazio.className = "empty";
        vazio.style.padding = "0 0 6px";
        vazio.textContent = "Nenhum documento anexado.";
        catBox.appendChild(vazio);
      } else {
        entradas.forEach(function(doc){
          var row = document.createElement("div");
          row.className = "doc-entry";
          var info = document.createElement("div");
          info.className = "doc-entry-info";
          var nome = document.createElement("a");
          nome.className = "doc-entry-nome";
          nome.href = doc.url || ("/_blob/" + doc.assetId);
          nome.addEventListener("click", function(ev){ ev.preventDefault(); abrirAnexo(doc.assetId || doc.url, doc.nomeArquivo || categoria, doc.nomeArquivo); });
          nome.textContent = doc.nomeArquivo || categoria;
          info.appendChild(nome);
          var meta = document.createElement("div");
          meta.className = "doc-entry-meta";
          var metaTexto = "Enviado em " + fmtDataBR((doc.enviadoEm || "").slice(0, 10));
          if(doc.competencia){ metaTexto += " · Competência: " + doc.competencia; }
          meta.textContent = metaTexto;
          info.appendChild(meta);
          row.appendChild(info);

          var btnRemover = document.createElement("button");
          btnRemover.type = "button"; btnRemover.className = "rm-btn"; btnRemover.title = "Remover documento";
          btnRemover.textContent = "✕";
          btnRemover.addEventListener("click", function(){ onRemove(doc); });
          row.appendChild(btnRemover);

          catBox.appendChild(row);
        });
      }

      var addRow = document.createElement("div");
      addRow.className = "doc-add-row";
      var inputCompetencia = document.createElement("input");
      inputCompetencia.type = "text"; inputCompetencia.placeholder = "Competência (ex.: 09/2026) — opcional";
      var inputFile = document.createElement("input");
      inputFile.type = "file";
      var btnAnexar = document.createElement("button");
      btnAnexar.type = "button"; btnAnexar.className = "secondary"; btnAnexar.textContent = "Anexar";
      var toastCat = document.createElement("div"); toastCat.style.width = "100%"; toastCat.style.marginTop = "4px";
      btnAnexar.addEventListener("click", async function(){
        var arquivo = inputFile.files && inputFile.files[0];
        if(!arquivo){ genericToast(toastCat, "Escolha um arquivo antes de anexar.", true); return; }
        btnAnexar.disabled = true;
        try{
          await onAdd(categoria, arquivo, inputCompetencia.value.trim());
          inputFile.value = ""; inputCompetencia.value = "";
        }catch(err){
          genericToast(toastCat, (err && err.friendlyMessage) || "Não foi possível anexar agora. Tente novamente.", true);
        }finally{
          btnAnexar.disabled = false;
        }
      });
      addRow.appendChild(inputCompetencia);
      addRow.appendChild(inputFile);
      addRow.appendChild(btnAnexar);
      catBox.appendChild(addRow);
      catBox.appendChild(toastCat);

      box.appendChild(catBox);
    });

    return box;
  }

  function criarFormularioDadosEmpresa(slug, cad){
    var box = document.createElement("div");
    box.style.marginBottom = "18px";

    var grid = document.createElement("div");
    grid.className = "add-line-grid";
    var campos = [
      { key: "razaoSocial", label: "Razão social" },
      { key: "cnpj", label: "CNPJ" },
      { key: "ie", label: "Inscrição estadual" },
      { key: "nire", label: "NIRE" },
      { key: "telefone", label: "Telefone" },
      { key: "email", label: "E-mail" }
    ];
    var inputs = {};
    campos.forEach(function(c){
      var field = document.createElement("div");
      field.className = "field";
      var label = document.createElement("label"); label.textContent = c.label;
      var input = document.createElement("input"); input.type = "text"; input.value = cad[c.key] || "";
      field.appendChild(label); field.appendChild(input);
      grid.appendChild(field);
      inputs[c.key] = input;
    });
    var fieldEndereco = document.createElement("div");
    fieldEndereco.className = "field";
    var labelEndereco = document.createElement("label"); labelEndereco.textContent = "Endereço";
    var inputEndereco = document.createElement("input"); inputEndereco.type = "text"; inputEndereco.value = cad.endereco || "";
    fieldEndereco.appendChild(labelEndereco); fieldEndereco.appendChild(inputEndereco);
    grid.appendChild(fieldEndereco);
    inputs.endereco = inputEndereco;
    var fieldRegime = document.createElement("div");
    fieldRegime.className = "field";
    var labelRegime = document.createElement("label"); labelRegime.textContent = "Regime tributário";
    var inputRegime = document.createElement("input"); inputRegime.type = "text"; inputRegime.value = cad.regimeTributario || "";
    inputRegime.setAttribute("list", "regimes-tributarios-datalist");
    fieldRegime.appendChild(labelRegime); fieldRegime.appendChild(inputRegime);
    grid.appendChild(fieldRegime);
    inputs.regimeTributario = inputRegime;
    box.appendChild(grid);

    var actions = document.createElement("div");
    actions.className = "actions"; actions.style.justifyContent = "flex-start"; actions.style.marginTop = "4px";
    var btnSalvar = document.createElement("button");
    btnSalvar.type = "button"; btnSalvar.className = "primary"; btnSalvar.textContent = "Salvar dados da empresa";
    var toastBox = document.createElement("div"); toastBox.style.marginTop = "8px";
    btnSalvar.addEventListener("click", async function(){
      if(!db){ genericToast(toastBox, "Armazenamento indisponível nesta visualização.", true); return; }
      btnSalvar.disabled = true;
      try{
        var patch = {};
        Object.keys(inputs).forEach(function(k){ patch[k] = inputs[k].value.trim(); });
        var atual = empresasCadastro[slug] || empresaCadastroVazio();
        await db.doc("empresasCadastro/" + slug).set(Object.assign({}, empresaCadastroVazio(), atual, patch));
        genericToast(toastBox, "Dados salvos.", false);
      }catch(err){
        genericToast(toastBox, "Não foi possível salvar agora. Tente novamente.", true);
      }finally{
        btnSalvar.disabled = false;
      }
    });
    actions.appendChild(btnSalvar);
    box.appendChild(actions);
    box.appendChild(toastBox);
    return box;
  }

  function criarCardSocio(slug, socio, idx){
    var card = document.createElement("div");
    card.className = "socio-card";

    var head = document.createElement("div");
    head.className = "socio-card-head";
    var strong = document.createElement("strong");
    strong.textContent = socio.nome ? socio.nome : "Sócio " + (idx + 1);
    head.appendChild(strong);
    var btnRemover = document.createElement("button");
    btnRemover.type = "button"; btnRemover.className = "rm-btn"; btnRemover.title = "Remover sócio";
    btnRemover.textContent = "✕ Remover";
    btnRemover.addEventListener("click", async function(){
      if(!db) return;
      var atual = empresasCadastro[slug] || empresaCadastroVazio();
      var novo = (atual.socios || []).filter(function(s){ return s.id !== socio.id; });
      await db.doc("empresasCadastro/" + slug).set(Object.assign({}, empresaCadastroVazio(), atual, { socios: novo }));
      if(assets){
        (socio.documentos || []).forEach(function(d){ if(d.assetId){ assets.delete(d.assetId).catch(function(){}); } });
      }
    });
    head.appendChild(btnRemover);
    card.appendChild(head);

    var grid = document.createElement("div");
    grid.className = "add-line-grid";
    var campos = [
      { key: "nome", label: "Nome" },
      { key: "cpf", label: "CPF" },
      { key: "rg", label: "RG" },
      { key: "telefone", label: "Telefone" },
      { key: "email", label: "E-mail" },
      { key: "capitalSocial", label: "Valor do capital social" },
      { key: "percentualQuotas", label: "% das quotas" }
    ];
    var inputs = {};
    campos.forEach(function(c){
      var field = document.createElement("div");
      field.className = "field";
      var label = document.createElement("label"); label.textContent = c.label;
      var input = document.createElement("input"); input.type = "text"; input.value = socio[c.key] || "";
      field.appendChild(label); field.appendChild(input);
      grid.appendChild(field);
      inputs[c.key] = input;
    });
    var fieldEndereco = document.createElement("div");
    fieldEndereco.className = "field";
    var labelEndereco = document.createElement("label"); labelEndereco.textContent = "Endereço";
    var inputEndereco = document.createElement("input"); inputEndereco.type = "text"; inputEndereco.value = socio.endereco || "";
    fieldEndereco.appendChild(labelEndereco); fieldEndereco.appendChild(inputEndereco);
    grid.appendChild(fieldEndereco);
    inputs.endereco = inputEndereco;
    card.appendChild(grid);

    var actions = document.createElement("div");
    actions.className = "actions"; actions.style.justifyContent = "flex-start"; actions.style.marginTop = "4px";
    var btnSalvar = document.createElement("button");
    btnSalvar.type = "button"; btnSalvar.className = "primary"; btnSalvar.textContent = "Salvar sócio";
    var toastBox = document.createElement("div"); toastBox.style.marginTop = "8px";
    btnSalvar.addEventListener("click", async function(){
      if(!db){ genericToast(toastBox, "Armazenamento indisponível nesta visualização.", true); return; }
      btnSalvar.disabled = true;
      try{
        var patch = {};
        Object.keys(inputs).forEach(function(k){ patch[k] = inputs[k].value.trim(); });
        var atual = empresasCadastro[slug] || empresaCadastroVazio();
        var novo = (atual.socios || []).map(function(s){ return s.id === socio.id ? Object.assign({}, s, patch) : s; });
        await db.doc("empresasCadastro/" + slug).set(Object.assign({}, empresaCadastroVazio(), atual, { socios: novo }));
        genericToast(toastBox, "Sócio salvo.", false);
      }catch(err){
        genericToast(toastBox, "Não foi possível salvar agora. Tente novamente.", true);
      }finally{
        btnSalvar.disabled = false;
      }
    });
    actions.appendChild(btnSalvar);
    card.appendChild(actions);
    card.appendChild(toastBox);

    card.appendChild(criarSecaoDocumentos("Documentos do sócio", SOCIO_DOC_CATEGORIAS, socio.documentos || [],
      async function(categoria, arquivo, competencia){
        if(!db){ throw erroAmigavel("Armazenamento indisponível nesta visualização."); }
        if(!assets){ throw erroAmigavel("Anexos não estão disponíveis nesta visualização."); }
        var uploaded = await assets.upload(arquivo);
        var atual = empresasCadastro[slug] || empresaCadastroVazio();
        var novoDoc = { id: gerarIdCadastro("doc"), categoria: categoria, competencia: competencia || null, nomeArquivo: arquivo.name, assetId: uploaded.id, url: uploaded.url, contentType: uploaded.contentType, sizeBytes: uploaded.sizeBytes, enviadoEm: new Date().toISOString() };
        var novoSocios = (atual.socios || []).map(function(s){
          if(s.id !== socio.id) return s;
          return Object.assign({}, s, { documentos: (s.documentos || []).concat([novoDoc]) });
        });
        await db.doc("empresasCadastro/" + slug).set(Object.assign({}, empresaCadastroVazio(), atual, { socios: novoSocios }));
      },
      async function(doc){
        if(!db) return;
        var atual = empresasCadastro[slug] || empresaCadastroVazio();
        var novoSocios = (atual.socios || []).map(function(s){
          if(s.id !== socio.id) return s;
          return Object.assign({}, s, { documentos: (s.documentos || []).filter(function(d){ return d.id !== doc.id; }) });
        });
        await db.doc("empresasCadastro/" + slug).set(Object.assign({}, empresaCadastroVazio(), atual, { socios: novoSocios }));
        if(assets && doc.assetId){ try{ await assets.delete(doc.assetId); }catch(e){} }
      }
    ));

    return card;
  }

  function criarPainelSocios(slug, cad){
    var wrap = document.createElement("div");
    var socios = cad.socios || [];

    if(!socios.length){
      var vazio = document.createElement("div");
      vazio.className = "empty";
      vazio.textContent = "Nenhum sócio cadastrado ainda.";
      wrap.appendChild(vazio);
    } else {
      socios.forEach(function(socio, idx){
        wrap.appendChild(criarCardSocio(slug, socio, idx));
      });
    }

    var actions = document.createElement("div");
    actions.className = "actions"; actions.style.justifyContent = "flex-start";
    var btnAdd = document.createElement("button");
    btnAdd.type = "button"; btnAdd.className = "secondary"; btnAdd.textContent = "+ Adicionar sócio";
    btnAdd.addEventListener("click", async function(){
      if(!db) return;
      btnAdd.disabled = true;
      try{
        var atual = empresasCadastro[slug] || empresaCadastroVazio();
        var novoSocio = { id: gerarIdCadastro("socio"), nome: "", cpf: "", rg: "", endereco: "", telefone: "", email: "", capitalSocial: "", percentualQuotas: "", documentos: [] };
        var novo = (atual.socios || []).concat([novoSocio]);
        await db.doc("empresasCadastro/" + slug).set(Object.assign({}, empresaCadastroVazio(), atual, { socios: novo }));
      }finally{
        btnAdd.disabled = false;
      }
    });
    actions.appendChild(btnAdd);
    wrap.appendChild(actions);

    return wrap;
  }

  function criarPainelCadastroEmpresa(slug, nomeEmpresa, cad){
    var wrap = document.createElement("div");

    var subtabs = document.createElement("div");
    subtabs.className = "cad-subtabs";
    var abaAtiva = cadastroSubabaAtiva[slug] || "dados";
    var btnDados = document.createElement("button");
    btnDados.type = "button"; btnDados.className = "cad-subtab-btn" + (abaAtiva === "dados" ? " active" : "");
    btnDados.textContent = "Dados e Documentos";
    var btnSocios = document.createElement("button");
    btnSocios.type = "button"; btnSocios.className = "cad-subtab-btn" + (abaAtiva === "socios" ? " active" : "");
    btnSocios.textContent = "Quadro Societário (" + (cad.socios || []).length + ")";
    btnDados.addEventListener("click", function(){ cadastroSubabaAtiva[slug] = "dados"; renderCadastroEmpresas(); });
    btnSocios.addEventListener("click", function(){ cadastroSubabaAtiva[slug] = "socios"; renderCadastroEmpresas(); });
    subtabs.appendChild(btnDados); subtabs.appendChild(btnSocios);
    wrap.appendChild(subtabs);

    var painelDados = document.createElement("div");
    painelDados.className = "cad-subpanel";
    painelDados.hidden = abaAtiva !== "dados";
    painelDados.appendChild(criarFormularioDadosEmpresa(slug, cad));
    painelDados.appendChild(criarSecaoDocumentos("Documentos da empresa", EMPRESA_DOC_CATEGORIAS, cad.documentos || [],
      async function(categoria, arquivo, competencia){
        if(!db){ throw erroAmigavel("Armazenamento indisponível nesta visualização."); }
        if(!assets){ throw erroAmigavel("Anexos não estão disponíveis nesta visualização."); }
        var uploaded = await assets.upload(arquivo);
        var atual = empresasCadastro[slug] || empresaCadastroVazio();
        var novoDoc = { id: gerarIdCadastro("doc"), categoria: categoria, competencia: competencia || null, nomeArquivo: arquivo.name, assetId: uploaded.id, url: uploaded.url, contentType: uploaded.contentType, sizeBytes: uploaded.sizeBytes, enviadoEm: new Date().toISOString() };
        var novo = (atual.documentos || []).concat([novoDoc]);
        await db.doc("empresasCadastro/" + slug).set(Object.assign({}, empresaCadastroVazio(), atual, { documentos: novo }));
      },
      async function(doc){
        if(!db) return;
        var atual = empresasCadastro[slug] || empresaCadastroVazio();
        var novo = (atual.documentos || []).filter(function(d){ return d.id !== doc.id; });
        await db.doc("empresasCadastro/" + slug).set(Object.assign({}, empresaCadastroVazio(), atual, { documentos: novo }));
        if(assets && doc.assetId){ try{ await assets.delete(doc.assetId); }catch(e){} }
      }
    ));
    wrap.appendChild(painelDados);

    var painelSocios = document.createElement("div");
    painelSocios.className = "cad-subpanel";
    painelSocios.hidden = abaAtiva !== "socios";
    painelSocios.appendChild(criarPainelSocios(slug, cad));
    wrap.appendChild(painelSocios);

    return wrap;
  }

  function renderCadastroEmpresas(){
    var container = document.getElementById("cadastro-empresas-lista");
    if(!container) return;
    container.innerHTML = "";
    var nomes = fullList("empresas").slice().sort(function(a, b){ return a.localeCompare(b); });
    if(!nomes.length){
      var vazio = document.createElement("div");
      vazio.className = "empty";
      vazio.textContent = "Nenhuma empresa cadastrada ainda (cadastre em Opções).";
      container.appendChild(vazio);
      return;
    }
    nomes.forEach(function(nomeEmpresa){
      var slug = slugify(nomeEmpresa);
      var cad = getCadastroEmpresa(slug);
      var aberto = cadastroEmpresaExpandida === slug;

      var card = document.createElement("div");
      card.className = "empresa-card";

      var header = document.createElement("div");
      header.className = "empresa-card-header";
      var titleWrap = document.createElement("div");
      var h3 = document.createElement("h3"); h3.textContent = nomeEmpresa;
      titleWrap.appendChild(h3);
      var sub = document.createElement("div");
      sub.className = "empresa-card-sub";
      sub.textContent = (cad.razaoSocial || cad.cnpj) ? [cad.razaoSocial, cad.cnpj].filter(Boolean).join(" · ") : "Cadastro não preenchido";
      titleWrap.appendChild(sub);
      header.appendChild(titleWrap);
      var toggle = document.createElement("span");
      toggle.className = "empresa-card-toggle";
      toggle.textContent = aberto ? "▲ Fechar" : "▼ Abrir cadastro";
      header.appendChild(toggle);
      header.addEventListener("click", function(){
        cadastroEmpresaExpandida = aberto ? null : slug;
        renderCadastroEmpresas();
      });
      card.appendChild(header);

      var body = document.createElement("div");
      body.className = "empresa-card-body";
      body.hidden = !aberto;
      if(aberto){
        body.appendChild(criarPainelCadastroEmpresa(slug, nomeEmpresa, cad));
      }
      card.appendChild(body);

      container.appendChild(card);
    });
  }

  // ---- Cadastro de Clientes e Fornecedores (dados cadastrais completos) ---------------
  var PARTICIPANTE_CAT_LABEL = { fornecedores: "fornecedor", clientes: "cliente" };
  function participanteCadastroVazio(){
    return {
      nome: "", tipoPessoa: null, documento: "", saldoInicial: null, contaContabilId: null,
      nomeFantasia: "", ie: "", telefone: "", email: "",
      enderecoLogradouro: "", enderecoNumero: "", enderecoComplemento: "", enderecoBairro: "", enderecoCep: "",
      municipioCodigo: "", municipioNome: "", uf: ""
    };
  }
  function cadastroDaCategoriaParticipante(categoria){
    return categoria === "clientes" ? clientesCadastro : fornecedoresCadastro;
  }
  function docPathParticipante(categoria, slug){
    return (categoria === "clientes" ? "clientesCadastro/" : "fornecedoresCadastro/") + slug;
  }
  function getCadastroParticipante(categoria, slug){
    return cadastroDaCategoriaParticipante(categoria)[slug] || participanteCadastroVazio();
  }

  function criarFormularioParticipante(categoria, slug, nomeParticipante, cad){
    var box = document.createElement("div");

    // CPF/CNPJ (com validação e detecção PF/PJ) + Nome fantasia + Inscrição Estadual + contato.
    // O mesmo CPF/CNPJ também pode ser editado na aba Opções para fornecedores (dado
    // compartilhado, mesmo cadastro) — aqui é o lugar único para clientes.
    var linha1 = document.createElement("div");
    linha1.className = "add-line-grid";

    var fieldDoc = document.createElement("div");
    fieldDoc.className = "field";
    fieldDoc.style.gridColumn = "span 2";
    var labelDoc = document.createElement("label"); labelDoc.textContent = "CPF/CNPJ";
    fieldDoc.appendChild(labelDoc);
    var rowDocInput = document.createElement("div");
    rowDocInput.style.display = "flex"; rowDocInput.style.alignItems = "center"; rowDocInput.style.gap = "8px";
    var inputDoc = document.createElement("input");
    inputDoc.type = "text"; inputDoc.placeholder = "CPF ou CNPJ (só números)"; inputDoc.value = cad.documento || "";
    inputDoc.style.flex = "1 1 auto"; inputDoc.style.minWidth = "0";
    rowDocInput.appendChild(inputDoc);
    var badgePfPj = document.createElement("span");
    badgePfPj.className = "pf-pj-badge";
    var infoInicialDoc = inputDoc.value ? maskDocumento(inputDoc.value) : null;
    badgePfPj.textContent = infoInicialDoc ? (infoInicialDoc.tipoPessoa === "fisica" ? "Pessoa Física" : "Pessoa Jurídica") : "—";
    rowDocInput.appendChild(badgePfPj);
    fieldDoc.appendChild(rowDocInput);
    var erroDoc = document.createElement("div"); erroDoc.className = "cad-doc-error"; erroDoc.hidden = true;
    fieldDoc.appendChild(erroDoc);
    inputDoc.addEventListener("input", function(){
      var info = maskDocumento(inputDoc.value);
      inputDoc.value = info.masked;
      if(info.digits.length === 0){
        badgePfPj.textContent = "—"; erroDoc.hidden = true;
      } else {
        badgePfPj.textContent = info.tipoPessoa === "fisica" ? "Pessoa Física" : "Pessoa Jurídica";
        erroDoc.hidden = !(documentoCompleto(info) && !documentoValido(info));
        erroDoc.textContent = info.tipoPessoa === "fisica" ? "CPF inválido." : "CNPJ inválido.";
      }
    });
    linha1.appendChild(fieldDoc);

    function campoTexto(label, valorAtual){
      var field = document.createElement("div"); field.className = "field";
      var lbl = document.createElement("label"); lbl.textContent = label;
      var input = document.createElement("input"); input.type = "text"; input.value = valorAtual || "";
      field.appendChild(lbl); field.appendChild(input);
      linha1.appendChild(field);
      return input;
    }
    var inputNomeFantasia = campoTexto("Nome fantasia", cad.nomeFantasia);
    var inputIe = campoTexto("Inscrição estadual", cad.ie);
    var inputTelefone = campoTexto("Telefone", cad.telefone);
    var inputEmail = campoTexto("E-mail", cad.email);
    var inputLimite = campoTexto(categoria === "clientes" ? "Limite de venda a prazo (R$)" : "Limite de crédito com o fornecedor (R$)", (typeof cad.limiteCredito === "number" && cad.limiteCredito > 0) ? cad.limiteCredito.toFixed(2) : "");
    inputLimite.type = "number"; inputLimite.step = "0.01"; inputLimite.min = "0"; inputLimite.placeholder = "Sem limite";
    inputLimite.title = categoria === "clientes" ? "Soma dos títulos a receber em aberto + a nova venda. Acima disso, o sistema avisa e pede confirmação." : "Soma dos títulos a pagar em aberto + a nova compra. Acima disso, o sistema avisa e pede confirmação.";
    box.appendChild(linha1);

    // Conta contábil vinculada — a mesma usada na contabilização automática dos lançamentos.
    // O "Código" deste cliente/fornecedor não é mais digitado: é o código desta conta.
    var linhaConta = document.createElement("div");
    linhaConta.className = "add-line-grid";
    var fieldConta = document.createElement("div"); fieldConta.className = "field";
    var labelConta = document.createElement("label"); labelConta.textContent = "Conta contábil (define o Código)";
    fieldConta.appendChild(labelConta);
    var selectConta = criarSelectContaContabil("cad-part-conta-contabil", cad.contaContabilId);
    if(catDaContaParticipante(cad.contaContabilId) === categoria){
      garantirOpcaoConta(selectConta, cad.contaContabilId);
      selectConta.value = cad.contaContabilId;
      selectConta.disabled = true;
      labelConta.textContent = "Conta contábil própria do " + PARTICIPANTE_CAT_LABEL[categoria] + " (define o Código)";
    }
    fieldConta.appendChild(selectConta);
    var codigoBadge = document.createElement("span"); codigoBadge.className = "footnote"; codigoBadge.style.display = "block"; codigoBadge.style.marginTop = "4px";
    function atualizarCodigoBadge(){
      var conta = contaContabilById(selectConta.value);
      codigoBadge.textContent = "Código: " + (conta && conta.codigo ? conta.codigo : "— vincule uma conta contábil para gerar o código —");
    }
    atualizarCodigoBadge();
    selectConta.addEventListener("change", atualizarCodigoBadge);
    fieldConta.appendChild(codigoBadge);
    linhaConta.appendChild(fieldConta);
    box.appendChild(linhaConta);

    // Endereço completo
    var enderecoTitle = document.createElement("div");
    enderecoTitle.className = "group-title"; enderecoTitle.style.margin = "10px 0 4px";
    enderecoTitle.textContent = "Endereço";
    box.appendChild(enderecoTitle);

    var linhaEndereco = document.createElement("div");
    linhaEndereco.className = "add-line-grid";
    function campoEndereco(label, valorAtual){
      var field = document.createElement("div"); field.className = "field";
      var lbl = document.createElement("label"); lbl.textContent = label;
      var input = document.createElement("input"); input.type = "text"; input.value = valorAtual || "";
      field.appendChild(lbl); field.appendChild(input);
      linhaEndereco.appendChild(field);
      return input;
    }
    var inputLogradouro = campoEndereco("Logradouro", cad.enderecoLogradouro);
    var inputNumero = campoEndereco("Número", cad.enderecoNumero);
    var inputComplemento = campoEndereco("Complemento", cad.enderecoComplemento);
    var inputBairro = campoEndereco("Bairro", cad.enderecoBairro);
    var inputCep = campoEndereco("CEP", cad.enderecoCep);
    box.appendChild(linhaEndereco);

    // Município (busca na tabela do IBGE — preenche Código do Município e UF sozinho)
    var linhaMunicipio = document.createElement("div");
    linhaMunicipio.className = "add-line-grid";
    var fieldMunicipio = document.createElement("div"); fieldMunicipio.className = "field";
    var labelMunicipio = document.createElement("label"); labelMunicipio.textContent = "Município";
    fieldMunicipio.appendChild(labelMunicipio);
    var wrapMunicipio = document.createElement("div"); wrapMunicipio.className = "select-wrap combo-wrap";
    var inputMunicipio = document.createElement("input");
    inputMunicipio.type = "text"; inputMunicipio.autocomplete = "off"; inputMunicipio.placeholder = "Buscar município...";
    var municipioSelecionado = { codigo: cad.municipioCodigo || "", nome: cad.municipioNome || "", uf: cad.uf || "" };
    inputMunicipio.value = municipioSelecionado.nome ? (municipioSelecionado.nome + " — " + municipioSelecionado.uf) : "";
    var dropdownMunicipio = document.createElement("div"); dropdownMunicipio.className = "combo-dropdown"; dropdownMunicipio.hidden = true;
    wrapMunicipio.appendChild(inputMunicipio); wrapMunicipio.appendChild(dropdownMunicipio);
    fieldMunicipio.appendChild(wrapMunicipio);
    var badgeMunicipio = document.createElement("div");
    badgeMunicipio.className = "footnote"; badgeMunicipio.style.margin = "4px 0 0";
    function atualizarBadgeMunicipio(){
      badgeMunicipio.textContent = municipioSelecionado.codigo
        ? ("Código do Município (IBGE): " + municipioSelecionado.codigo + " · UF: " + municipioSelecionado.uf)
        : "Nenhum município selecionado.";
    }
    atualizarBadgeMunicipio();
    fieldMunicipio.appendChild(badgeMunicipio);
    inputMunicipio.addEventListener("input", function(){
      var termo = inputMunicipio.value;
      var termoCorresponde = municipioSelecionado.nome && termo === (municipioSelecionado.nome + " — " + municipioSelecionado.uf);
      if(municipioSelecionado.codigo && !termoCorresponde){
        municipioSelecionado = { codigo: "", nome: "", uf: "" };
        atualizarBadgeMunicipio();
      }
      dropdownMunicipio.innerHTML = "";
      if(!termo.trim()){ dropdownMunicipio.hidden = true; return; }
      var resultados = buscarMunicipios(termo);
      if(!resultados.length){
        var empty = document.createElement("div"); empty.className = "combo-empty"; empty.textContent = "Nenhum resultado.";
        dropdownMunicipio.appendChild(empty);
      } else {
        resultados.forEach(function(m){
          var opt = document.createElement("div"); opt.className = "combo-option";
          opt.textContent = m[1] + " — " + m[2];
          opt.addEventListener("mousedown", function(ev){
            ev.preventDefault();
            municipioSelecionado = { codigo: m[0], nome: m[1], uf: m[2] };
            inputMunicipio.value = m[1] + " — " + m[2];
            dropdownMunicipio.hidden = true;
            atualizarBadgeMunicipio();
          });
          dropdownMunicipio.appendChild(opt);
        });
      }
      dropdownMunicipio.hidden = false;
    });
    inputMunicipio.addEventListener("blur", function(){ setTimeout(function(){ dropdownMunicipio.hidden = true; }, 150); });
    inputMunicipio.addEventListener("focus", function(){ if(inputMunicipio.value.trim()){ inputMunicipio.dispatchEvent(new Event("input")); } });
    linhaMunicipio.appendChild(fieldMunicipio);
    box.appendChild(linhaMunicipio);

    // Saldo inicial (antes deste sistema) — composto por empresa: cada uma das empresas pode
    // ter vários boletos em aberto, que juntos formam o saldo daquela empresa com este
    // cliente/fornecedor. O tipo (a pagar/a receber) já é definido pela categoria.
    var saldoCheckWrap = document.createElement("label");
    saldoCheckWrap.className = "opt-check"; saldoCheckWrap.style.marginTop = "10px";
    var cbSaldo = document.createElement("input");
    cbSaldo.type = "checkbox"; cbSaldo.checked = !!(cad.saldoInicial && Object.keys(cad.saldoInicial).length);
    saldoCheckWrap.appendChild(cbSaldo);
    saldoCheckWrap.appendChild(document.createTextNode("Possui saldo inicial (antes deste sistema) — " + (categoria === "clientes" ? "a receber" : "a pagar")));
    box.appendChild(saldoCheckWrap);

    var saldoFields = document.createElement("div");
    saldoFields.className = "cad-saldo-fields cad-saldo-fields-empresas";
    saldoFields.hidden = !(cad.saldoInicial && Object.keys(cad.saldoInicial).length);

    var empresaBlocosListas = {}; // empresa -> elemento com a lista de linhas de boleto

    function alertaBoleto(linha, txt){
      var a = linha.querySelector(".boleto-alerta");
      if(!a){ a = document.createElement("div"); a.className = "boleto-alerta"; a.style.cssText = "color:#b42318; font-size:12px; width:100%;"; linha.appendChild(a); }
      a.textContent = txt;
    }
    function criarLinhaBoleto(boleto){
      var linha = document.createElement("div");
      linha.className = "saldo-boleto-row";
      linha.style.cssText = "display:flex; gap:8px; align-items:center; margin-top:6px; flex-wrap:wrap;";
      var vInput = document.createElement("input");
      vInput.type = "number"; vInput.step = "0.01"; vInput.placeholder = "Valor"; vInput.style.width = "120px";
      vInput.value = (boleto && typeof boleto.valor === "number") ? boleto.valor : "";
      var dInput = document.createElement("input");
      dInput.type = "date"; dInput.style.width = "150px"; dInput.title = "Vencimento (obrigatório)";
      dInput.value = (boleto && boleto.vencimento) || "";
      var nInput = document.createElement("input");
      nInput.type = "text"; nInput.placeholder = "Nº documento"; nInput.style.width = "130px";
      nInput.value = (boleto && boleto.documento) || "";
      var pagoInfo = document.createElement("span");
      pagoInfo.className = "hint";
      var jaPago = (boleto && typeof boleto.valorPago === "number") ? boleto.valorPago : 0;
      if(jaPago > 0) pagoInfo.textContent = "baixado " + brl(jaPago);
      var pagaLbl = document.createElement("label");
      pagaLbl.className = "opt-check"; pagaLbl.style.margin = "0";
      var pagaCb = document.createElement("input");
      pagaCb.type = "checkbox"; pagaCb.checked = !!(boleto && boleto.paga);
      pagaLbl.appendChild(pagaCb); pagaLbl.appendChild(document.createTextNode("Pago"));
      var btnRemover = document.createElement("button");
      btnRemover.type = "button"; btnRemover.textContent = "Remover";
      btnRemover.style.cssText = "background:none; border:none; color:#b91c1c; cursor:pointer; padding:0 4px; font-size:12px;";
      btnRemover.addEventListener("click", function(){
        if(jaPago > 0){ alertaBoleto(linha, "Este boleto já tem baixa por pagamento/recebimento. Estorne a baixa antes de remover."); return; }
        linha.remove();
      });
      linha.appendChild(vInput); linha.appendChild(dInput); linha.appendChild(nInput); linha.appendChild(pagaLbl); linha.appendChild(pagoInfo); linha.appendChild(btnRemover);
      linha._refs = { valorInput: vInput, vencInput: dInput, docInput: nInput, pagaCb: pagaCb, valorPago: jaPago, cobranca: (boleto && boleto.cobranca) || null };
      return linha;
    }

    EMPRESAS.forEach(function(empresa){
      var bloco = document.createElement("div");
      bloco.className = "saldo-empresa-bloco";
      bloco.style.cssText = "margin-top:10px; padding:8px 10px; border:1px solid #e2e2e2; border-radius:8px;";
      var titulo = document.createElement("div");
      titulo.style.cssText = "font-weight:600; margin-bottom:2px;";
      titulo.textContent = empresa;
      bloco.appendChild(titulo);
      var listaBoletos = document.createElement("div");
      listaBoletos.className = "saldo-boletos-lista";
      bloco.appendChild(listaBoletos);
      var boletosExistentes = (cad.saldoInicial && cad.saldoInicial[empresa]) || [];
      boletosExistentes.forEach(function(b){ listaBoletos.appendChild(criarLinhaBoleto(b)); });
      var btnAdd = document.createElement("button");
      btnAdd.type = "button"; btnAdd.textContent = "+ Adicionar boleto";
      btnAdd.style.cssText = "margin-top:6px; font-size:12px; padding:4px 10px;";
      btnAdd.addEventListener("click", function(){ listaBoletos.appendChild(criarLinhaBoleto(null)); });
      bloco.appendChild(btnAdd);
      saldoFields.appendChild(bloco);
      empresaBlocosListas[empresa] = listaBoletos;
    });

    box.appendChild(saldoFields);
    cbSaldo.addEventListener("change", function(){ saldoFields.hidden = !cbSaldo.checked; });

    var actions = document.createElement("div");
    actions.className = "actions"; actions.style.justifyContent = "flex-start"; actions.style.marginTop = "12px";
    var btnSalvar = document.createElement("button");
    btnSalvar.type = "button"; btnSalvar.className = "primary"; btnSalvar.textContent = "Salvar cadastro";
    var toastBox = document.createElement("div"); toastBox.style.marginTop = "8px";
    btnSalvar.addEventListener("click", async function(){
      if(!db){ genericToast(toastBox, "Armazenamento indisponível nesta visualização.", true); return; }
      var infoDoc = maskDocumento(inputDoc.value);
      if(infoDoc.digits.length > 0 && !documentoValido(infoDoc)){
        genericToast(toastBox, infoDoc.tipoPessoa === "fisica" ? "CPF inválido." : "CNPJ inválido.", true);
        return;
      }
      if(infoDoc.digits.length > 0){
        await garantirIndice(categoria);
        var duplicado = !!docDuplicadoNoIndice(categoria, infoDoc.digits, slug);
        if(duplicado){
          genericToast(toastBox, "Este CPF/CNPJ já está cadastrado para outro " + PARTICIPANTE_CAT_LABEL[categoria] + ".", true);
          return;
        }
      }
      var saldoInicialFinal = null;
      if(cbSaldo.checked){
        var saldoObj = {};
        var erroSaldo = null;
        EMPRESAS.forEach(function(empresa){
          var listaBoletos = empresaBlocosListas[empresa];
          var boletos = [];
          Array.prototype.forEach.call(listaBoletos.children, function(linha){
            var refs = linha._refs;
            if(!refs.valorInput.value && !refs.vencInput.value && !refs.docInput.value) return; // linha vazia, ignora
            var valor = parseFloat(refs.valorInput.value);
            if(isNaN(valor) || valor <= 0){ erroSaldo = "Informe um valor de boleto válido em " + empresa + "."; return; }
            if(!refs.vencInput.value){ erroSaldo = "Informe o vencimento de cada boleto em " + empresa + " (é ele que posiciona o título no fluxo)."; return; }
            if(refs.valorPago > valor + 0.004){ erroSaldo = "Em " + empresa + ", um boleto ficou com valor menor que o já baixado (" + brl(refs.valorPago) + ")."; return; }
            var bol = { valor: r2(valor), vencimento: refs.vencInput.value, documento: refs.docInput.value.trim(), valorPago: r2(refs.valorPago || 0) };
            bol.paga = !!refs.pagaCb.checked || bol.valorPago >= bol.valor - 0.004;
            if(refs.cobranca) bol.cobranca = refs.cobranca;
            boletos.push(bol);
          });
          if(boletos.length) saldoObj[empresa] = boletos;
        });
        if(erroSaldo){ genericToast(toastBox, erroSaldo, true); return; }
        if(Object.keys(saldoObj).length === 0){ genericToast(toastBox, "Adicione ao menos um boleto em alguma empresa, ou desmarque \"Possui saldo inicial\".", true); return; }
        saldoInicialFinal = saldoObj;
      }
      btnSalvar.disabled = true;
      try{
        var patch = {
          nome: nomeParticipante,
          documento: infoDoc.digits ? infoDoc.masked : "",
          tipoPessoa: infoDoc.digits ? infoDoc.tipoPessoa : (cad.tipoPessoa || null),
          nomeFantasia: inputNomeFantasia.value.trim(),
          ie: inputIe.value.trim(),
          telefone: inputTelefone.value.trim(),
          email: inputEmail.value.trim(),
          limiteCredito: (parseFloat(inputLimite.value) > 0) ? r2(parseFloat(inputLimite.value)) : null,
          contaContabilId: selectConta.value || null,
          enderecoLogradouro: inputLogradouro.value.trim(),
          enderecoNumero: inputNumero.value.trim(),
          enderecoComplemento: inputComplemento.value.trim(),
          enderecoBairro: inputBairro.value.trim(),
          enderecoCep: inputCep.value.trim(),
          municipioCodigo: municipioSelecionado.codigo,
          municipioNome: municipioSelecionado.nome,
          uf: municipioSelecionado.uf,
          saldoInicial: saldoInicialFinal
        };
        var atual = cadastroDaCategoriaParticipante(categoria)[slug] || participanteCadastroVazio();
        var salvo = Object.assign({}, participanteCadastroVazio(), atual, patch);
        await db.doc(docPathParticipante(categoria, slug)).set(salvo);
        cadastroDaCategoriaParticipante(categoria)[slug] = salvo;
        genericToast(toastBox, "Cadastro salvo.", false);
        indiceSalvar(categoria, slug, salvo, nomeParticipante).catch(function(){
          genericToast(toastBox, "Cadastro salvo, mas a busca não foi atualizada — salve de novo.", true);
        });
        renderSaldosClientes();
      }catch(err){
        genericToast(toastBox, "Não foi possível salvar agora. Tente novamente.", true);
      }finally{
        btnSalvar.disabled = false;
      }
    });
    actions.appendChild(btnSalvar);
    box.appendChild(actions);
    box.appendChild(toastBox);
    return box;
  }

  function renderCadastroParticipantes(categoria){
    var container = document.getElementById("cadastro-" + categoria + "-lista");
    if(!container) return;
    container.innerHTML = "";
    var st = indicePart[categoria];
    var termoBusca = cadastroBusca[categoria] || "";
    function aviso(texto, classe){
      var el = document.createElement("div");
      el.className = classe || "footnote";
      if(!classe){ el.style.cssText = "margin:0 0 12px; text-align:left;"; }
      el.textContent = texto;
      container.appendChild(el);
    }
    if(!termoBuscaValido(termoBusca)){
      aviso("Digite ao menos 2 letras do nome ou números do CPF/CNPJ para buscar" + (st.carregado ? (" (" + st.total + " cadastrados)") : "") + ". A base completa não é carregada ao abrir o Fluxo — só os resultados da busca.");
      return;
    }
    if(!st.carregado){
      aviso("Carregando a base de busca...");
      garantirIndice(categoria).then(function(){ renderCadastroParticipantes(categoria); });
      return;
    }
    var LIMITE = 30;
    var r = buscarNoIndice(categoria, termoBusca, LIMITE, true);
    if(!r.itens.length){
      aviso("Nenhum resultado para \"" + termoBusca + "\".", "empty");
      return;
    }
    aviso(r.total > LIMITE
      ? ("Mostrando os primeiros " + LIMITE + " de " + r.total + " resultados para \"" + termoBusca + "\". Digite mais para refinar.")
      : (r.total + " resultado" + (r.total === 1 ? "" : "s") + " para \"" + termoBusca + "\"."));
    var bloqueadosSet = new Set(bloqueios[categoria] || []);
    r.itens.forEach(function(it){
      var aberto = cadastroParticipanteExpandido[categoria] === it.id;
      var bloqueado = bloqueadosSet.has(it.nome);

      var card = document.createElement("div");
      card.className = "empresa-card";
      var header = document.createElement("div");
      header.className = "empresa-card-header";
      var titleWrap = document.createElement("div");
      var h3 = document.createElement("h3"); h3.textContent = it.nome;
      titleWrap.appendChild(h3);
      var sub = document.createElement("div");
      sub.className = "empresa-card-sub";
      var conta = contaContabilById(it.conta);
      var subPartes = [];
      if(conta && conta.codigo){ subPartes.push("Código " + conta.codigo); }
      if(it.doc){ subPartes.push(documentoFormatado(it.doc)); }
      if(bloqueado){ subPartes.push("BLOQUEADO para lançamentos"); }
      sub.textContent = subPartes.length ? subPartes.join(" · ") : "Cadastro não preenchido";
      titleWrap.appendChild(sub);
      header.appendChild(titleWrap);
      var toggle = document.createElement("span");
      toggle.className = "empresa-card-toggle";
      toggle.textContent = aberto ? "▲ Fechar" : "▼ Abrir cadastro";
      header.appendChild(toggle);
      header.addEventListener("click", function(){
        cadastroParticipanteExpandido[categoria] = aberto ? null : it.id;
        renderCadastroParticipantes(categoria);
      });
      card.appendChild(header);

      var body = document.createElement("div");
      body.className = "empresa-card-body";
      body.hidden = !aberto;
      if(aberto){
        body.appendChild(criarAcoesParticipante(categoria, it, bloqueado));
        var carregando = document.createElement("div");
        carregando.className = "footnote"; carregando.style.textAlign = "left";
        carregando.textContent = "Carregando cadastro...";
        body.appendChild(carregando);
        carregarParticipante(categoria, it.id).then(function(cad){
          if(cadastroParticipanteExpandido[categoria] !== it.id) return;
          carregando.remove();
          body.appendChild(criarFormularioParticipante(categoria, it.id, cad.nome || it.nome, cad));
        }).catch(function(){
          carregando.textContent = "Não foi possível carregar este cadastro agora. Feche e abra de novo.";
        });
      }
      card.appendChild(body);
      container.appendChild(card);
    });
  }

  var cadastroToasts = {};
  // Renomear / bloquear / excluir um cliente ou fornecedor (antes ficava na aba Opções).
  function criarAcoesParticipante(categoria, it, bloqueado){
    var wrap = document.createElement("div");
    wrap.style.cssText = "display:flex; gap:8px; flex-wrap:wrap; align-items:center; margin:4px 0 12px;";
    var toast = document.createElement("div"); toast.style.cssText = "flex-basis:100%;";
    var podeEditar = canEditLancamentos();
    if(!podeEditar){ return wrap; }

    var btnRenomear = document.createElement("button");
    btnRenomear.type = "button"; btnRenomear.className = "secondary"; btnRenomear.textContent = "Renomear";
    var btnBloq = document.createElement("button");
    btnBloq.type = "button"; btnBloq.className = "secondary";
    btnBloq.textContent = bloqueado ? "Desbloquear (liberar para lançamentos)" : "Bloquear para lançamentos";
    var btnExcluir = document.createElement("button");
    btnExcluir.type = "button"; btnExcluir.className = "secondary"; btnExcluir.style.color = "#b91c1c";
    btnExcluir.textContent = "Excluir";

    var painelRenomear = document.createElement("div");
    painelRenomear.hidden = true;
    painelRenomear.style.cssText = "flex-basis:100%; display:flex; gap:8px; flex-wrap:wrap;";
    var inpNome = document.createElement("input"); inpNome.type = "text"; inpNome.value = it.nome; inpNome.style.flex = "1 1 240px";
    var btnOkNome = document.createElement("button"); btnOkNome.type = "button"; btnOkNome.className = "primary"; btnOkNome.textContent = "Salvar nome";
    var btnCancNome = document.createElement("button"); btnCancNome.type = "button"; btnCancNome.className = "link-btn"; btnCancNome.textContent = "Cancelar";
    painelRenomear.appendChild(inpNome); painelRenomear.appendChild(btnOkNome); painelRenomear.appendChild(btnCancNome);

    var painelExcluir = document.createElement("div");
    painelExcluir.hidden = true;
    painelExcluir.style.cssText = "flex-basis:100%; display:flex; gap:8px; align-items:center; flex-wrap:wrap;";
    var txtExcluir = document.createElement("span"); txtExcluir.textContent = "Excluir \"" + it.nome + "\"? Se já foi usado em lançamentos ou tem saldo inicial, ele será apenas bloqueado.";
    var btnSimExcluir = document.createElement("button"); btnSimExcluir.type = "button"; btnSimExcluir.className = "primary"; btnSimExcluir.textContent = "Confirmar";
    var btnNaoExcluir = document.createElement("button"); btnNaoExcluir.type = "button"; btnNaoExcluir.className = "link-btn"; btnNaoExcluir.textContent = "Cancelar";
    painelExcluir.appendChild(txtExcluir); painelExcluir.appendChild(btnSimExcluir); painelExcluir.appendChild(btnNaoExcluir);

    btnRenomear.addEventListener("click", function(){ painelRenomear.hidden = !painelRenomear.hidden; painelExcluir.hidden = true; if(!painelRenomear.hidden) inpNome.focus(); });
    btnCancNome.addEventListener("click", function(){ painelRenomear.hidden = true; inpNome.value = it.nome; });
    btnOkNome.addEventListener("click", async function(){
      btnOkNome.disabled = true;
      try{
        var res = await renomearParticipante(categoria, it.id, it.nome, inpNome.value);
        var novoNome = inpNome.value.trim();
        cadastroBusca[categoria] = novoNome;
        var inputBusca = document.getElementById("cadastro-" + categoria + "-busca");
        if(inputBusca) inputBusca.value = novoNome;
        renderCadastroParticipantes(categoria);
        genericToast(cadastroToasts[categoria] || toast, "Renomeado para \"" + novoNome + "\"" + (res.lancamentosAtualizados ? (" (" + res.lancamentosAtualizados + " lançamento(s) atualizado(s))") : "") + ".", false);
      }catch(err){
        genericToast(toast, (err && err.friendlyMessage) || "Não foi possível renomear agora. Tente novamente.", true);
      }finally{ btnOkNome.disabled = false; }
    });
    btnBloq.addEventListener("click", async function(){
      btnBloq.disabled = true;
      try{
        await alternarBloqueioParticipante(categoria, it.nome, !bloqueado);
        renderCadastroParticipantes(categoria);
      }catch(err){
        genericToast(toast, "Não foi possível salvar agora. Tente novamente.", true);
        btnBloq.disabled = false;
      }
    });
    btnExcluir.addEventListener("click", function(){ painelExcluir.hidden = !painelExcluir.hidden; painelRenomear.hidden = true; });
    btnNaoExcluir.addEventListener("click", function(){ painelExcluir.hidden = true; });
    btnSimExcluir.addEventListener("click", async function(){
      btnSimExcluir.disabled = true;
      try{
        var res = await excluirParticipante(categoria, it.id, it.nome);
        cadastroParticipanteExpandido[categoria] = null;
        renderCadastroParticipantes(categoria);
        genericToast(cadastroToasts[categoria] || toast, res.apenasBloqueado ? ("\"" + it.nome + "\" já foi usado (ou tem saldo inicial) — foi bloqueado em vez de excluído.") : ("\"" + it.nome + "\" excluído."), false);
      }catch(err){
        genericToast(toast, "Não foi possível excluir agora. Tente novamente.", true);
        btnSimExcluir.disabled = false;
      }
    });

    wrap.appendChild(btnRenomear); wrap.appendChild(btnBloq); wrap.appendChild(btnExcluir);
    wrap.appendChild(painelRenomear); wrap.appendChild(painelExcluir); wrap.appendChild(toast);
    return wrap;
  }

  // Barra "Novo cliente / Novo fornecedor" no topo de cada lista da aba Cadastro.
  ["fornecedores", "clientes"].forEach(function(categoria){
    var lista = document.getElementById("cadastro-" + categoria + "-lista");
    var busca = document.getElementById("cadastro-" + categoria + "-busca");
    if(!lista || !busca) return;
    var bar = document.createElement("div");
    bar.style.cssText = "display:flex; gap:8px; flex-wrap:wrap; margin:0 0 12px;";
    var inp = document.createElement("input");
    inp.type = "text"; inp.placeholder = categoria === "clientes" ? "Nome do novo cliente" : "Nome do novo fornecedor"; inp.style.flex = "1 1 240px";
    var btn = document.createElement("button");
    btn.type = "button"; btn.className = "secondary"; btn.textContent = categoria === "clientes" ? "+ Novo cliente" : "+ Novo fornecedor";
    var toast = document.createElement("div"); toast.style.flexBasis = "100%";
    bar.appendChild(inp); bar.appendChild(btn); bar.appendChild(toast);
    cadastroToasts[categoria] = toast;
    busca.parentNode.insertBefore(bar, busca);
    inp.addEventListener("keydown", function(ev){ if(ev.key === "Enter"){ ev.preventDefault(); btn.click(); } });
    btn.addEventListener("click", async function(){
      btn.disabled = true;
      try{
        var novo = await criarParticipante(categoria, inp.value);
        inp.value = "";
        cadastroBusca[categoria] = novo.nome;
        busca.value = novo.nome;
        cadastroParticipanteExpandido[categoria] = novo.id;
        renderCadastroParticipantes(categoria);
        genericToast(toast, "\"" + novo.nome + "\" cadastrado. Preencha os dados abaixo.", false);
      }catch(err){
        genericToast(toast, (err && err.friendlyMessage) || "Não foi possível cadastrar agora. Tente novamente.", true);
      }finally{ btn.disabled = false; }
    });
  });

  // ---- Opções (bloqueio de itens das listas) --------------------------
  // Nome do item + ícones de lápis (renomear) e lixeira (excluir), usados em toda linha
  // de opção da aba Opções. Alterna entre "ver", "editar" e "confirmar exclusão" trocando
  // só o conteúdo deste <span> — o resto da tela é redesenhado sozinho quando o Firestore
  // confirmar a mudança (pelos onSnapshot de bloqueios/extras/removidos/renomeadosBase).
  function criarNomeComAcoes(cat, item){
    var wrap = document.createElement("span");
    wrap.className = "opt-name-wrap";
    wrap.dataset.cat = cat;
    wrap.dataset.opcaoNome = item;

    function renderView(){
      wrap.innerHTML = "";
      var nome = document.createElement("span");
      nome.className = "opt-name"; nome.textContent = item;
      wrap.appendChild(nome);
      var btnEditar = document.createElement("button");
      btnEditar.type = "button"; btnEditar.className = "opt-icon-btn"; btnEditar.title = "Renomear \"" + item + "\"";
      btnEditar.textContent = "✏️";
      btnEditar.addEventListener("click", function(ev){ ev.preventDefault(); ev.stopPropagation(); renderEdicao(); });
      wrap.appendChild(btnEditar);
      var btnExcluir = document.createElement("button");
      btnExcluir.type = "button"; btnExcluir.className = "opt-icon-btn opt-icon-excluir"; btnExcluir.title = "Excluir \"" + item + "\"";
      btnExcluir.textContent = "🗑️";
      btnExcluir.addEventListener("click", function(ev){ ev.preventDefault(); ev.stopPropagation(); renderConfirmExclusao(); });
      wrap.appendChild(btnExcluir);
    }

    function renderEdicao(){
      wrap.innerHTML = "";
      var input = document.createElement("input");
      input.type = "text"; input.className = "opt-rename-input"; input.value = item;
      wrap.appendChild(input);
      var btnOk = document.createElement("button");
      btnOk.type = "button"; btnOk.className = "opt-icon-btn"; btnOk.title = "Salvar novo nome"; btnOk.textContent = "✔️";
      var btnCancelar = document.createElement("button");
      btnCancelar.type = "button"; btnCancelar.className = "opt-icon-btn"; btnCancelar.title = "Cancelar"; btnCancelar.textContent = "✖️";
      var erro = document.createElement("div");
      erro.className = "opt-inline-erro"; erro.hidden = true;
      btnOk.addEventListener("click", async function(ev){
        ev.preventDefault(); ev.stopPropagation();
        input.disabled = true; btnOk.disabled = true; btnCancelar.disabled = true;
        var res = await renomearOpcao(cat, item, input.value);
        if(!res.ok){
          erro.textContent = res.motivo || "Não foi possível renomear.";
          erro.hidden = false;
          input.disabled = false; btnOk.disabled = false; btnCancelar.disabled = false;
          return;
        }
        genericToast(elOpcoesToast, res.semMudanca ? "Nada para alterar." : ("\"" + item + "\" renomeada para \"" + input.value.trim() + "\"."), false);
      });
      btnCancelar.addEventListener("click", function(ev){ ev.preventDefault(); ev.stopPropagation(); renderView(); });
      input.addEventListener("keydown", function(ev){
        if(ev.key === "Enter"){ ev.preventDefault(); btnOk.click(); }
        if(ev.key === "Escape"){ ev.preventDefault(); renderView(); }
      });
      wrap.appendChild(btnOk);
      wrap.appendChild(btnCancelar);
      wrap.appendChild(erro);
      input.focus(); input.select();
    }

    function renderConfirmExclusao(){
      wrap.innerHTML = "";
      var aviso = document.createElement("span");
      aviso.className = "opt-name"; aviso.textContent = "Excluir \"" + item + "\"?";
      wrap.appendChild(aviso);
      var btnSim = document.createElement("button");
      btnSim.type = "button"; btnSim.className = "opt-icon-btn opt-icon-excluir"; btnSim.title = "Confirmar exclusão"; btnSim.textContent = "✔️";
      var btnNao = document.createElement("button");
      btnNao.type = "button"; btnNao.className = "opt-icon-btn"; btnNao.title = "Cancelar"; btnNao.textContent = "✖️";
      var erro = document.createElement("div");
      erro.className = "opt-inline-erro"; erro.hidden = true;
      btnSim.addEventListener("click", async function(ev){
        ev.preventDefault(); ev.stopPropagation();
        btnSim.disabled = true; btnNao.disabled = true;
        var res = await excluirOpcao(cat, item);
        if(!res.ok){
          erro.textContent = res.motivo || "Não foi possível excluir.";
          erro.hidden = false;
          btnSim.disabled = false; btnNao.disabled = false;
          return;
        }
        if(res.apenasBloqueado){
          genericToast(elOpcoesToast, "\"" + item + "\" já foi usada antes, então foi apenas bloqueada (some das opções novas, mas continua nos lançamentos antigos).", false);
        } else {
          genericToast(elOpcoesToast, "\"" + item + "\" excluída.", false);
        }
      });
      btnNao.addEventListener("click", function(ev){ ev.preventDefault(); ev.stopPropagation(); renderView(); });
      wrap.appendChild(btnSim);
      wrap.appendChild(btnNao);
      wrap.appendChild(erro);
    }

    renderView();
    return wrap;
  }

  // Select de "conta contábil vinculada", usado no cadastro de fornecedor/cliente e de banco
  // (aba Opções) e nas Contas por Tipo de lançamento. Lista só as contas Analíticas do Plano
  // de Contas (Sintéticas não recebem lançamento), agrupadas por Grupo.
  function criarSelectContaContabil(className, valorAtual){
    var sel = document.createElement("select");
    sel.className = className;
    var blank = document.createElement("option");
    blank.value = ""; blank.textContent = "— nenhuma —";
    sel.appendChild(blank);
    GRUPOS_PLANO_CONTAS.forEach(function(grupo){
      var contasGrupo = planoContas.filter(function(c){ return contaEhAnalitica(c) && grupoDeConta(c) === grupo && (contaDisponivel(c) || c.id === valorAtual); }).sort(compararContasPorCodigo);
      if(!contasGrupo.length) return;
      var grp = document.createElement("optgroup");
      grp.label = grupo;
      contasGrupo.forEach(function(c){
        var o = document.createElement("option");
        o.value = c.id; o.textContent = (c.codigo ? c.codigo + " — " : "") + c.nome;
        grp.appendChild(o);
      });
      sel.appendChild(grp);
    });
    sel.value = valorAtual || "";
    return sel;
  }

  var avisosBanco = {}; // banco -> "✓ Vínculo salvo" mostrado ao lado do vínculo contábil
  var avisosDespesa = {}; // item de Pagamento/Recebimento -> "✓ Vínculo salvo"
  function renderOpcoes(){
    // Mantém abertos os grupos que a pessoa tinha aberto (a tela é redesenhada a cada mudança).
    var gruposAbertos = {};
    elOpcoesGroups.querySelectorAll("details.opt-group").forEach(function(d){
      var l = d.querySelector(".check-list");
      if(d.open && l && l.dataset.cat) gruposAbertos[l.dataset.cat] = true;
    });
    elOpcoesGroups.innerHTML = "";
    CAT_ORDER.forEach(function(cat){
      if(cat === "fornecedores" || cat === "clientes"){
        if(cat === "fornecedores"){
          var notaPart = document.createElement("p");
          notaPart.className = "footnote"; notaPart.style.cssText = "margin:8px 0; text-align:left;";
          notaPart.textContent = "Fornecedores e Clientes: agora são gerenciados na aba Cadastro, pela busca (bloquear/liberar, renomear, excluir, CPF/CNPJ e conta contábil).";
          elOpcoesGroups.appendChild(notaPart);
        }
        return;
      }
      var full = fullList(cat);
      var blocked = bloqueios[cat] || [];
      var parceladasAtuais = formasParceladas !== null ? formasParceladas : DEFAULT_FORMAS_PARCELADAS;
      var ehFormaPagamento = cat === "formasPagamento";
      var ehFornecedor = cat === "fornecedores";
      var ehBanco = cat === "bancos";
      var ehDespesa = cat === "despesas";
      var det = document.createElement("details");
      det.className = "opt-group";
      if(gruposAbertos[cat]) det.open = true;
      var summary = document.createElement("summary");
      summary.textContent = CAT_LABELS[cat] + " (" + full.length + " opções" + (blocked.length ? ", " + blocked.length + " bloqueada(s)" : "") + ")";
      det.appendChild(summary);
      var btnMarcarTodos = document.createElement("button");
      btnMarcarTodos.type = "button";
      btnMarcarTodos.className = "link-btn";
      btnMarcarTodos.style.marginLeft = "10px";
      btnMarcarTodos.textContent = "Marcar todos";
      btnMarcarTodos.addEventListener("click", function(ev){
        ev.preventDefault();
        ev.stopPropagation();
        list.querySelectorAll("input.opt-ativo").forEach(function(cb){ cb.checked = true; });
      });
      summary.appendChild(btnMarcarTodos);
      var btnDesmarcarTodos = document.createElement("button");
      btnDesmarcarTodos.type = "button";
      btnDesmarcarTodos.className = "link-btn";
      btnDesmarcarTodos.style.marginLeft = "6px";
      btnDesmarcarTodos.textContent = "Desmarcar todos";
      btnDesmarcarTodos.addEventListener("click", function(ev){
        ev.preventDefault();
        ev.stopPropagation();
        list.querySelectorAll("input.opt-ativo").forEach(function(cb){ cb.checked = false; });
      });
      summary.appendChild(btnDesmarcarTodos);
      if((extras[cat] || []).length > 0){
        var btnLimparExtras = document.createElement("button");
        btnLimparExtras.type = "button";
        btnLimparExtras.className = "link-btn";
        btnLimparExtras.style.marginLeft = "10px";
        btnLimparExtras.textContent = "Remover todos os itens adicionados (" + extras[cat].length + ")";
        btnLimparExtras.addEventListener("click", async function(ev){
          ev.preventDefault();
          ev.stopPropagation();
          if(!db) return;
          btnLimparExtras.disabled = true;
          try{
            var novoExtras = Object.assign({}, extras);
            novoExtras[cat] = [];
            await db.doc("listaConfig/extras").set(novoExtras);
          }catch(err){ /* tenta de novo depois */ }
          btnLimparExtras.disabled = false;
        });
        summary.appendChild(btnLimparExtras);
      }
      if(ehFormaPagamento){
        var nota = document.createElement("p");
        nota.className = "footnote"; nota.style.textAlign = "left"; nota.style.margin = "8px 0";
        nota.textContent = "Marque \"Gera parcelas\" para formas de pagamento com pagamento futuro/parcelado (ex.: boleto, crediário). Isso habilita os campos de número de parcelas e vencimentos no lançamento, e o lançamento fica \"A Receber\"/\"A Pagar\" até todas as parcelas serem marcadas como pagas.";
        det.appendChild(nota);
      }
      if(ehFornecedor){
        var notaF = document.createElement("p");
        notaF.className = "footnote"; notaF.style.textAlign = "left"; notaF.style.margin = "8px 0";
        notaF.textContent = "Cadastre o CPF ou CNPJ de cada cliente/fornecedor — o tipo (Pessoa Física/Jurídica) é identificado automaticamente pela quantidade de dígitos digitados. Se já existir um valor a pagar ou a receber anterior a este sistema, marque \"Possui saldo inicial\" e informe o valor; ele aparecerá na aba Saldos. A \"Conta contábil\" é usada para preencher automaticamente a Conta Débito/Crédito dos lançamentos com este fornecedor/cliente (ver aba Opções, \"Contas por Tipo de lançamento\")." ;
        det.appendChild(notaF);
      }
      if(ehDespesa){
        var notaD = document.createElement("p");
        notaD.className = "footnote"; notaD.style.textAlign = "left"; notaD.style.margin = "8px 0";
        notaD.textContent = "A \"Conta contábil\" de cada item é usada como contrapartida do banco nos lançamentos automáticos (ex.: ENERGIA ELÉTRICA → Débito na conta de energia / Crédito no banco). Itens sem conta (ex.: FORNECEDOR) continuam usando a conta do fornecedor/cliente. Salva na hora em que você escolhe.";
        det.appendChild(notaD);
      }
      if(ehBanco){
        var notaB = document.createElement("p");
        notaB.className = "footnote"; notaB.style.textAlign = "left"; notaB.style.margin = "8px 0";
        notaB.textContent = "A \"Conta contábil\" de cada banco é usada para preencher automaticamente a Conta Débito/Crédito dos lançamentos feitos com esse banco (ver aba Opções, \"Contas por Tipo de lançamento\").";
        det.appendChild(notaB);
      }
      var list = document.createElement("div");
      list.className = "check-list";
      list.dataset.cat = cat;
      full.forEach(function(item){
        var row;
        if(ehFormaPagamento){
          row = document.createElement("div");
          row.className = "opt-row";
          row.appendChild(criarNomeComAcoes(cat, item));
          var lblAtivo = document.createElement("label");
          lblAtivo.className = "opt-check";
          var cbAtivo = document.createElement("input");
          cbAtivo.type = "checkbox"; cbAtivo.className = "opt-ativo"; cbAtivo.checked = blocked.indexOf(item) === -1; cbAtivo.value = item;
          lblAtivo.appendChild(cbAtivo); lblAtivo.appendChild(document.createTextNode("Disponível"));
          row.appendChild(lblAtivo);
          var lblParc = document.createElement("label");
          lblParc.className = "opt-check";
          var cbParc = document.createElement("input");
          cbParc.type = "checkbox"; cbParc.className = "opt-parcelado"; cbParc.checked = parceladasAtuais.indexOf(item) !== -1; cbParc.value = item;
          lblParc.appendChild(cbParc); lblParc.appendChild(document.createTextNode("Gera parcelas"));
          row.appendChild(lblParc);
        } else if(ehFornecedor){
          var slug = slugify(item);
          var cad = fornecedoresCadastro[slug] || null;
          row = document.createElement("div");
          row.className = "cad-row";
          var top = document.createElement("div");
          top.className = "cad-row-top";
          top.appendChild(criarNomeComAcoes(cat, item));
          var lblAtivo2 = document.createElement("label");
          lblAtivo2.className = "opt-check";
          var cbAtivo2 = document.createElement("input");
          cbAtivo2.type = "checkbox"; cbAtivo2.className = "opt-ativo"; cbAtivo2.checked = blocked.indexOf(item) === -1; cbAtivo2.value = item;
          lblAtivo2.appendChild(cbAtivo2); lblAtivo2.appendChild(document.createTextNode("Disponível"));
          top.appendChild(lblAtivo2);
          row.appendChild(top);

          var fields = document.createElement("div");
          fields.className = "cad-fields";
          fields.dataset.slug = slug;
          fields.dataset.nome = item;

          var docWrap = document.createElement("div");
          docWrap.className = "cad-field cad-field-doc";
          var docLabel = document.createElement("label"); docLabel.textContent = "CPF/CNPJ";
          docWrap.appendChild(docLabel);
          var docInput = document.createElement("input");
          docInput.type = "text"; docInput.className = "cad-documento"; docInput.placeholder = "CPF ou CNPJ (só números)";
          var docValorInicial = (cad && cad.documento) || "";
          docInput.value = docValorInicial;
          docWrap.appendChild(docInput);
          var pfPjBadge = document.createElement("span");
          pfPjBadge.className = "pf-pj-badge";
          var infoInicial = docValorInicial ? maskDocumento(docValorInicial) : null;
          pfPjBadge.textContent = infoInicial ? (infoInicial.tipoPessoa === "fisica" ? "Pessoa Física" : "Pessoa Jurídica") : "—";
          docWrap.appendChild(pfPjBadge);
          var docErr = document.createElement("div"); docErr.className = "cad-doc-error"; docErr.hidden = true;
          docWrap.appendChild(docErr);
          fields.appendChild(docWrap);

          // O saldo inicial (por empresa, com os boletos) é editado no cadastro completo do
          // fornecedor (aba Cadastro) — aqui, esta tela só cuida de disponibilidade, CPF/CNPJ
          // e conta contábil, e nunca toca no saldoInicial ao salvar.
          var contaWrap = document.createElement("div");
          contaWrap.className = "cad-field";
          var contaLabel = document.createElement("label"); contaLabel.textContent = "Conta contábil";
          contaWrap.appendChild(contaLabel);
          contaWrap.appendChild(criarSelectContaContabil("cad-conta-contabil", cad && cad.contaContabilId));
          fields.appendChild(contaWrap);
          row.appendChild(fields);
        } else if(ehDespesa){
          row = document.createElement("div");
          row.className = "cad-row";
          var topD = document.createElement("div");
          topD.className = "cad-row-top";
          topD.appendChild(criarNomeComAcoes(cat, item));
          var lblAtivoD = document.createElement("label");
          lblAtivoD.className = "opt-check";
          var cbAtivoD = document.createElement("input");
          cbAtivoD.type = "checkbox"; cbAtivoD.className = "opt-ativo"; cbAtivoD.checked = blocked.indexOf(item) === -1; cbAtivoD.value = item;
          lblAtivoD.appendChild(cbAtivoD); lblAtivoD.appendChild(document.createTextNode("Disponível"));
          topD.appendChild(lblAtivoD);
          row.appendChild(topD);
          var fieldsD = document.createElement("div");
          fieldsD.className = "cad-fields";
          fieldsD.dataset.despesa = item;
          var contaWrapD = document.createElement("div");
          contaWrapD.className = "cad-field";
          var contaLabelD = document.createElement("label"); contaLabelD.textContent = "Conta contábil";
          contaWrapD.appendChild(contaLabelD);
          contaWrapD.appendChild(criarSelectContaContabil("despesa-conta-contabil", contasDespesas[item]));
          fieldsD.appendChild(contaWrapD);
          if(avisosDespesa[item]){
            var avisoD = document.createElement("div");
            avisoD.className = "footnote despesa-conta-aviso"; avisoD.style.cssText = "margin:4px 0 0; text-align:left; color:var(--income, #15803d);";
            avisoD.textContent = avisosDespesa[item];
            fieldsD.appendChild(avisoD);
          }
          row.appendChild(fieldsD);
        } else if(ehBanco){
          row = document.createElement("div");
          row.className = "cad-row";
          var topB = document.createElement("div");
          topB.className = "cad-row-top";
          topB.appendChild(criarNomeComAcoes(cat, item));
          var lblAtivoB = document.createElement("label");
          lblAtivoB.className = "opt-check";
          var cbAtivoB = document.createElement("input");
          cbAtivoB.type = "checkbox"; cbAtivoB.className = "opt-ativo"; cbAtivoB.checked = blocked.indexOf(item) === -1; cbAtivoB.value = item;
          lblAtivoB.appendChild(cbAtivoB); lblAtivoB.appendChild(document.createTextNode("Disponível"));
          topB.appendChild(lblAtivoB);
          row.appendChild(topB);

          var fieldsB = document.createElement("div");
          fieldsB.className = "cad-fields";
          fieldsB.dataset.banco = item;
          var contaWrapB = document.createElement("div");
          contaWrapB.className = "cad-field";
          var contaLabelB = document.createElement("label"); contaLabelB.textContent = "Conta contábil";
          contaWrapB.appendChild(contaLabelB);
          contaWrapB.appendChild(criarSelectContaContabil("banco-conta-contabil", contasBancos[item]));
          fieldsB.appendChild(contaWrapB);
          if(avisosBanco[item]){
            var avisoB = document.createElement("div");
            avisoB.className = "footnote banco-conta-aviso"; avisoB.style.cssText = "margin:4px 0 0; text-align:left; color:var(--income, #15803d);";
            avisoB.textContent = avisosBanco[item];
            fieldsB.appendChild(avisoB);
          }
          row.appendChild(fieldsB);
        } else {
          row = document.createElement("div");
          row.className = "opt-row";
          row.appendChild(criarNomeComAcoes(cat, item));
          var lblAtivo3 = document.createElement("label");
          lblAtivo3.className = "opt-check";
          var cb = document.createElement("input");
          cb.type = "checkbox"; cb.className = "opt-ativo"; cb.checked = blocked.indexOf(item) === -1; cb.value = item;
          lblAtivo3.appendChild(cb); lblAtivo3.appendChild(document.createTextNode("Disponível"));
          row.appendChild(lblAtivo3);
        }
        list.appendChild(row);
      });
      det.appendChild(list);
      elOpcoesGroups.appendChild(det);
    });
  }

  // Delegação de eventos para os campos de cadastro (a lista é recriada a cada render)
  // Conta contábil do banco: salva na hora em que é escolhida (não depende do botão
  // "Salvar opções", que podia perder a escolha se a tela fosse redesenhada antes do clique).
  elOpcoesGroups.addEventListener("change", async function(ev){
    var sel = ev.target;
    if(!sel.classList || !sel.classList.contains("banco-conta-contabil")) return;
    var fieldsEl = sel.closest(".cad-fields[data-banco]");
    if(!fieldsEl || !db) return;
    var bancoNome = fieldsEl.dataset.banco;
    var aviso = fieldsEl.querySelector(".banco-conta-aviso");
    if(!aviso){
      aviso = document.createElement("div");
      aviso.className = "footnote banco-conta-aviso"; aviso.style.cssText = "margin:4px 0 0; text-align:left;";
      fieldsEl.appendChild(aviso);
    }
    var novoContasBancos = Object.assign({}, contasBancos);
    if(sel.value){ novoContasBancos[bancoNome] = sel.value; } else { delete novoContasBancos[bancoNome]; }
    sel.disabled = true;
    try{
      await db.doc("listaConfig/contasBancos").set(novoContasBancos);
      contasBancos = novoContasBancos;
      var conta = contaContabilById(sel.value);
      genericToast(elOpcoesToast, sel.value ? ("Banco \"" + bancoNome + "\" vinculado à conta " + (conta && conta.codigo ? conta.codigo + " — " : "") + (conta ? conta.nome : "") + ".") : ("Vínculo contábil do banco \"" + bancoNome + "\" removido."), false);
      avisosBanco[bancoNome] = sel.value ? "✓ Vínculo salvo" : "✓ Vínculo removido";
      aviso.textContent = avisosBanco[bancoNome];
    }catch(err){
      genericToast(elOpcoesToast, "Não foi possível salvar o vínculo do banco agora. Tente novamente.", true);
      aviso.textContent = "Não salvo — tente de novo.";
    }finally{
      sel.disabled = false;
    }
  });
  elOpcoesGroups.addEventListener("change", async function(ev){
    var sel = ev.target;
    if(!sel.classList || !sel.classList.contains("despesa-conta-contabil")) return;
    var fieldsEl = sel.closest(".cad-fields[data-despesa]");
    if(!fieldsEl || !db) return;
    var item = fieldsEl.dataset.despesa;
    var novo = Object.assign({}, contasDespesas);
    if(sel.value){ novo[item] = sel.value; } else { delete novo[item]; }
    sel.disabled = true;
    try{
      await db.doc("listaConfig/contasDespesas").set(novo);
      contasDespesas = novo;
      avisosDespesa[item] = sel.value ? "✓ Vínculo salvo" : "✓ Vínculo removido";
      var aviso = fieldsEl.querySelector(".despesa-conta-aviso");
      if(!aviso){
        aviso = document.createElement("div");
        aviso.className = "footnote despesa-conta-aviso"; aviso.style.cssText = "margin:4px 0 0; text-align:left; color:var(--income, #15803d);";
        fieldsEl.appendChild(aviso);
      }
      aviso.textContent = avisosDespesa[item];
    }catch(err){
      genericToast(elOpcoesToast, "Não foi possível salvar o vínculo de \"" + item + "\" agora. Tente novamente.", true);
    }finally{
      sel.disabled = false;
    }
  });
  elOpcoesGroups.addEventListener("input", function(ev){
    if(!ev.target.classList.contains("cad-documento")) return;
    var input = ev.target;
    var info = maskDocumento(input.value);
    input.value = info.masked;
    var wrap = input.closest(".cad-field-doc");
    if(!wrap) return;
    var badge = wrap.querySelector(".pf-pj-badge");
    var err = wrap.querySelector(".cad-doc-error");
    if(info.digits.length === 0){
      badge.textContent = "—";
      err.hidden = true;
    } else {
      badge.textContent = info.tipoPessoa === "fisica" ? "Pessoa Física" : "Pessoa Jurídica";
      if(documentoCompleto(info)){
        var valido = documentoValido(info);
        if(!valido){
          err.hidden = false;
          err.textContent = info.tipoPessoa === "fisica" ? "CPF inválido." : "CNPJ inválido.";
        } else {
          var currentFields = input.closest(".cad-fields");
          var dupNome = null;
          elOpcoesGroups.querySelectorAll(".cad-fields").forEach(function(fe){
            if(fe === currentFields || dupNome) return;
            var otherInput = fe.querySelector(".cad-documento");
            if(!otherInput) return;
            var otherInfo = maskDocumento(otherInput.value);
            if(otherInfo.digits.length > 0 && otherInfo.digits === info.digits){ dupNome = fe.dataset.nome; }
          });
          if(dupNome){
            err.hidden = false;
            err.textContent = "Este CPF/CNPJ já está cadastrado para \"" + dupNome + "\".";
          } else {
            err.hidden = true;
          }
        }
      } else {
        err.hidden = true;
      }
    }
  });
  elBtnOpcoesSave.addEventListener("click", async function(){
    if(!db){ genericToast(elOpcoesToast, "Armazenamento indisponível nesta visualização.", true); return; }
    var novo = { fornecedores: (bloqueios.fornecedores || []).slice(), clientes: (bloqueios.clientes || []).slice() };
    var novasParceladas = null;
    var lists = elOpcoesGroups.querySelectorAll(".check-list");
    lists.forEach(function(list){
      var cat = list.dataset.cat;
      var blockedNow = [];
      list.querySelectorAll("input.opt-ativo").forEach(function(cb){
        if(!cb.checked) blockedNow.push(cb.value);
      });
      novo[cat] = blockedNow;
      if(cat === "formasPagamento"){
        novasParceladas = [];
        list.querySelectorAll("input.opt-parcelado").forEach(function(cb){
          if(cb.checked) novasParceladas.push(cb.value);
        });
      }
    });

    var cadastroWrites = [];
    var docErrors = [];
    var seenDocs = {}; // dígitos do CPF/CNPJ -> nome já usado nesta tela (impede duplicidade)
    elOpcoesGroups.querySelectorAll(".cad-fields[data-slug]").forEach(function(fieldsEl){
      var slug = fieldsEl.dataset.slug;
      var nome = fieldsEl.dataset.nome;
      var existente = fornecedoresCadastro[slug] || null;
      var contaContabilSel = fieldsEl.querySelector(".cad-conta-contabil");
      var contaContabilId = (contaContabilSel && contaContabilSel.value) || null;
      var docInput = fieldsEl.querySelector(".cad-documento");
      var info = maskDocumento(docInput.value);
      var documentoFinal = "";
      var tipoPessoaFinal = existente ? existente.tipoPessoa : null;
      if(info.digits.length > 0){
        if(!documentoValido(info)){
          docErrors.push(nome + " (" + (info.tipoPessoa === "fisica" ? "CPF" : "CNPJ") + " incompleto ou inválido)");
          return;
        }
        if(seenDocs[info.digits]){
          docErrors.push(nome + " está com o mesmo CPF/CNPJ de \"" + seenDocs[info.digits] + "\"");
          return;
        }
        seenDocs[info.digits] = nome;
        documentoFinal = info.masked;
        tipoPessoaFinal = info.tipoPessoa;
      }
      if(!documentoFinal && !contaContabilId && !existente) return; // nada a salvar e nunca existiu
      cadastroWrites.push({
        slug: slug,
        data: { nome: nome, tipoPessoa: tipoPessoaFinal, documento: documentoFinal, contaContabilId: contaContabilId, updatedAt: new Date().toISOString() }
      });
    });
    if(docErrors.length){
      genericToast(elOpcoesToast, "Corrija antes de salvar: " + docErrors.join(", ") + ".", true);
      return;
    }

    var novoContasBancos = Object.assign({}, contasBancos);
    elOpcoesGroups.querySelectorAll(".cad-fields[data-banco]").forEach(function(fieldsEl){
      var bancoNome = fieldsEl.dataset.banco;
      var sel = fieldsEl.querySelector(".banco-conta-contabil");
      var val = sel && sel.value;
      if(val){ novoContasBancos[bancoNome] = val; }
      else { delete novoContasBancos[bancoNome]; }
    });

    elBtnOpcoesSave.disabled = true;
    try{
      await db.doc("listaConfig/bloqueios").set(novo);
      if(novasParceladas !== null){
        await db.doc("listaConfig/formasParceladas").set({ list: novasParceladas });
      }
      for(var i = 0; i < cadastroWrites.length; i++){
        var slugW = cadastroWrites[i].slug;
        var existenteW = fornecedoresCadastro[slugW] || {};
        var mergedW = Object.assign({}, participanteCadastroVazio(), existenteW, cadastroWrites[i].data);
        await db.doc("fornecedoresCadastro/" + slugW).set(mergedW);
      }
      await db.doc("listaConfig/contasBancos").set(novoContasBancos);
      genericToast(elOpcoesToast, "Opções atualizadas.", false);
    }catch(err){
      genericToast(elOpcoesToast, "Não foi possível salvar agora. Tente novamente.", true);
    }finally{
      elBtnOpcoesSave.disabled = false;
    }
  });

  // ---- Bloqueios por área (Opções) ---------------------------------------
  // Categorias configuráveis por área: "tipo" (os 9 Tipos fixos de lançamento), "centrosCusto"
  // e "bancos" (listas editáveis). Cada checkbox marca se aquela opção fica DISPONÍVEL para quem
  // tem aquela área (mesmo padrão visual/semântico da lista "Disponível" acima, só que por área).
  var AREA_BLOQ_CATS = [
    { cat: "tipo", label: "Tipo de lançamento", options: function(){ return TIPOS.map(function(t){ return { value: t.value, label: t.label }; }); } },
    { cat: "centrosCusto", label: "Centro de Custo", options: function(){ return fullList("centrosCusto").map(function(v){ return { value: v, label: v }; }); } },
    { cat: "bancos", label: "Banco", options: function(){ return fullList("bancos").map(function(v){ return { value: v, label: v }; }); } }
  ];

  function renderBloqueiosArea(){
    if(!elOpcoesAreaGroups) return;
    elOpcoesAreaGroups.innerHTML = "";
    AREAS_ORDER.forEach(function(area){
      var det = document.createElement("details");
      det.className = "opt-group";
      var summary = document.createElement("summary");
      summary.textContent = AREA_LABELS[area];
      det.appendChild(summary);
      AREA_BLOQ_CATS.forEach(function(def){
        var options = def.options();
        var blocked = (bloqueiosArea[area] && bloqueiosArea[area][def.cat]) || [];
        var subTitle = document.createElement("p");
        subTitle.className = "footnote";
        subTitle.style.cssText = "text-align:left; margin:10px 0 6px; font-weight:600; text-transform:none;";
        subTitle.textContent = def.label;
        det.appendChild(subTitle);
        var list = document.createElement("div");
        list.className = "check-list";
        list.dataset.area = area;
        list.dataset.cat = def.cat;
        options.forEach(function(opt){
          var label = document.createElement("label");
          var cb = document.createElement("input");
          cb.type = "checkbox"; cb.className = "opt-area-ativo"; cb.value = opt.value;
          cb.checked = blocked.indexOf(opt.value) === -1;
          label.appendChild(cb);
          label.appendChild(document.createTextNode(opt.label));
          list.appendChild(label);
        });
        det.appendChild(list);
      });
      elOpcoesAreaGroups.appendChild(det);
    });
  }

  elBtnOpcoesAreaSave.addEventListener("click", async function(){
    if(!db){ genericToast(elOpcoesAreaToast, "Armazenamento indisponível nesta visualização.", true); return; }
    var novo = {};
    elOpcoesAreaGroups.querySelectorAll(".check-list").forEach(function(list){
      var area = list.dataset.area, cat = list.dataset.cat;
      if(!novo[area]) novo[area] = {};
      var blockedNow = [];
      list.querySelectorAll("input.opt-area-ativo").forEach(function(cb){
        if(!cb.checked) blockedNow.push(cb.value);
      });
      novo[area][cat] = blockedNow;
    });
    elBtnOpcoesAreaSave.disabled = true;
    try{
      await db.doc("listaConfig/bloqueiosArea").set(novo);
      genericToast(elOpcoesAreaToast, "Bloqueios por área atualizados.", false);
    }catch(err){
      genericToast(elOpcoesAreaToast, "Não foi possível salvar agora. Tente novamente.", true);
    }finally{
      elBtnOpcoesAreaSave.disabled = false;
    }
  });

  // ---- Plano de Contas (Opções) ------------------------------------------
  function contaContabilEmUso(id){
    if(!id) return false;
    var emUsoPart = ["fornecedores", "clientes"].some(function(cat){
      var porId = indicePart[cat].porId;
      return Object.keys(porId).some(function(k){ return porId[k].conta === id; });
    });
    if(emUsoPart) return true;
    for(var b in contasBancos){ if(contasBancos[b] === id) return true; }
    for(var dsp in contasDespesas){ if(contasDespesas[dsp] === id) return true; }
    for(var t in regrasContabeis){
      var r = regrasContabeis[t];
      if(r && (r.contaDebito === id || r.contaCredito === id || r.contaContrapartida === id)) return true;
    }
    return allDocs.some(function(doc){
      var d = doc.data() || {};
      if(d.contaDebito === id || d.contaCredito === id) return true;
      if(d.rateios && d.rateios.length){
        return d.rateios.some(function(r){ return r && (r.contaDebito === id || r.contaCredito === id); });
      }
      return false;
    });
  }

  // Uma conta é "raiz de exibição" de um grupo quando pertence a esse grupo mas a sua conta
  // pai (pelo código) não existe ou é de outro grupo — é assim que, por exemplo, PATRIMÔNIO
  // LÍQUIDO (código 2.3, que fica "dentro" de PASSIVO pelo código) aparece como sua própria
  // seção em vez de aninhada dentro de Passivo.
  function raizesDeExibicaoDoGrupo(grupo){
    return planoContas.filter(function(c){
      if(grupoDeConta(c) !== grupo) return false;
      var paiCodigo = codigoPaiDe(c.codigo || "");
      if(!paiCodigo) return true;
      var pai = planoContaPorCodigo(paiCodigo);
      return !pai || grupoDeConta(pai) !== grupo;
    }).sort(compararContasPorCodigo);
  }
  function compararContasPorCodigo(a, b){
    var ca = (a.codigo || "").split(".").map(Number), cb = (b.codigo || "").split(".").map(Number);
    for(var i = 0; i < Math.max(ca.length, cb.length); i++){
      var va = ca[i], vb = cb[i];
      if(va === undefined) return -1;
      if(vb === undefined) return 1;
      if(va !== vb) return va - vb;
    }
    return (a.nome || "").localeCompare(b.nome || "");
  }
  function renderPlanoContaLinha(container, conta, profundidade, grupoAtual){
    var estVis = estadoVisConta(conta);
    var mostrarOcultas = !!(document.getElementById("plano-mostrar-ocultas") || {}).checked;
    if(estVis === "oculta" && !mostrarOcultas) return;
    var row = document.createElement("div");
    row.className = "opt-row plano-conta-row" + (contaEhSintetica(conta) ? " plano-conta-sintetica" : " plano-conta-analitica") + (estVis ? " vis-" + estVis : "");
    row.style.paddingLeft = (profundidade * 18) + "px";
    var badge = document.createElement("span");
    badge.className = "plano-conta-badge " + (contaEhSintetica(conta) ? "badge-sintetica" : "badge-analitica");
    badge.title = contaEhSintetica(conta) ? "Sintética — totalizador de grupo/subgrupo, não recebe lançamento" : "Analítica — recebe lançamento de Débito/Crédito";
    badge.textContent = contaEhSintetica(conta) ? "S" : "A";
    row.appendChild(badge);
    if(conta.codigo){
      var cod = document.createElement("span");
      cod.className = "plano-conta-codigo";
      cod.textContent = conta.codigo;
      row.appendChild(cod);
    }
    var nameWrap = document.createElement("div");
    nameWrap.className = "opt-name-wrap";
    var input = document.createElement("input");
    input.type = "text"; input.className = "opt-rename-input plano-conta-nome-input";
    input.value = conta.nome; input.dataset.id = conta.id;
    nameWrap.appendChild(input);
    row.appendChild(nameWrap);
    if(contaEhAnalitica(conta)){
      var refInput = document.createElement("input");
      refInput.type = "text"; refInput.className = "plano-conta-ref-rfb-input";
      refInput.placeholder = "Ref. Receita Federal (opcional)";
      refInput.autocomplete = "off";
      refInput.dataset.id = conta.id;
      refInput.value = conta.refRFB || "";
      var refAtual = conta.refRFB ? RFB_REFERENCIAL_POR_CLASSIF[conta.refRFB] : null;
      refInput.title = refAtual ? (refAtual.classificacao + " — " + refAtual.descricao) : "Clique para escolher a conta referencial da Receita Federal";
      row.appendChild(refInput);
    }
    if(conta.codigo){
      var proprio = visPlano.contas[conta.codigo] || "";
      var herdado = proprio ? "" : estVis;
      var selVis = document.createElement("select");
      selVis.className = "plano-conta-vis"; selVis.dataset.codigo = conta.codigo;
      [["", "Disponível"], ["bloqueada", "🔒 Bloqueada"], ["oculta", "🙈 Oculta"]].forEach(function(o){
        var op = document.createElement("option"); op.value = o[0]; op.textContent = o[1] + (herdado && o[0] === herdado ? " (pela conta acima)" : ""); selVis.appendChild(op);
      });
      selVis.value = proprio || herdado;
      if(herdado){ selVis.disabled = true; selVis.title = "Herdado de uma conta Sintética acima — altere lá."; }
      else selVis.title = "Disponibilidade desta conta" + (contaEhSintetica(conta) ? " e de todas abaixo dela" : "");
      row.appendChild(selVis);
    }
    var btnRm = document.createElement("button");
    btnRm.type = "button"; btnRm.className = "opt-icon-btn opt-icon-excluir plano-conta-remover";
    btnRm.title = "Excluir conta"; btnRm.textContent = "🗑"; btnRm.dataset.id = conta.id;
    row.appendChild(btnRm);
    container.appendChild(row);
    if(contaEhSintetica(conta) && conta.codigo){
      planoContasFilhos(conta.codigo).forEach(function(filho){
        if(grupoDeConta(filho) !== grupoAtual) return; // vira raiz de exibição em outra seção
        renderPlanoContaLinha(container, filho, profundidade + 1, grupoAtual);
      });
    }
    var catBloco = catPorPaiContas(conta.codigo);
    if(catBloco){ renderBlocoContasParticipantes(catBloco, container, profundidade + 1); }
  }
  function renderPlanoContas(){
    if(!elPlanoContasLista) return;
    elPlanoContasLista.innerHTML = "";
    if(!planoContas.length){
      var vazio = document.createElement("p");
      vazio.className = "empty";
      vazio.textContent = "Nenhuma conta cadastrada ainda. Baixe o modelo abaixo (já vem preenchido com um plano de contas padrão completo) e importe, ou adicione contas uma a uma.";
      elPlanoContasLista.appendChild(vazio);
      atualizarSelectPlanoContaPai();
      return;
    }
    GRUPOS_PLANO_CONTAS.forEach(function(grupo){
      var raizes = raizesDeExibicaoDoGrupo(grupo);
      if(!raizes.length) return;
      var secao = document.createElement("div");
      secao.style.marginBottom = "14px";
      var titulo = document.createElement("div");
      titulo.className = "group-title";
      titulo.textContent = grupo;
      secao.appendChild(titulo);
      raizes.forEach(function(raiz){ renderPlanoContaLinha(secao, raiz, 0, grupo); });
      elPlanoContasLista.appendChild(secao);
    });
    atualizarSelectPlanoContaPai();
  }

  // Select "Conta pai" do formulário de nova conta — lista só as Sintéticas (só elas podem
  // ter conta filha), agrupadas por Grupo e indentadas conforme a profundidade na hierarquia.
  function atualizarSelectPlanoContaPai(){
    if(!elPlanoContaPai) return;
    var valorAtual = elPlanoContaPai.value;
    elPlanoContaPai.innerHTML = "";
    var temSintetica = planoContas.some(contaEhSintetica);
    var blank = document.createElement("option");
    blank.value = "";
    blank.textContent = temSintetica ? "— selecione —" : "— nenhuma conta Sintética cadastrada ainda (importe um plano de contas) —";
    elPlanoContaPai.appendChild(blank);
    GRUPOS_PLANO_CONTAS.forEach(function(grupo){
      var sinteticas = planoContas.filter(function(c){ return contaEhSintetica(c) && c.codigo && grupoDeConta(c) === grupo && contaDisponivel(c); })
        .sort(compararContasPorCodigo);
      if(!sinteticas.length) return;
      var grp = document.createElement("optgroup");
      grp.label = grupo;
      sinteticas.forEach(function(c){
        var o = document.createElement("option");
        o.value = c.codigo;
        var profundidade = c.codigo.split(".").length - 1;
        o.textContent = "—".repeat(profundidade) + (profundidade ? " " : "") + c.codigo + "  " + c.nome;
        grp.appendChild(o);
      });
      elPlanoContaPai.appendChild(grp);
    });
    if(valorAtual && planoContaPorCodigo(valorAtual)){ elPlanoContaPai.value = valorAtual; }
    if(elBtnPlanoContaAdd){ elBtnPlanoContaAdd.disabled = !temSintetica; }
  }

  // ---- Lista da Referência Receita Federal (substitui o <datalist> nativo, que não rolava
  // com a roda do mouse). Uma lista própria, com busca por código ou descrição, rolagem
  // normal e navegação por setas/Enter. Ao escolher, dispara "change" e o salvamento segue
  // o mesmo caminho de antes.
  var rfbDropdown = null, rfbInputAtivo = null, rfbAtivoIdx = -1, rfbItensVisiveis = [];
  function rfbGarantirDropdown(){
    if(rfbDropdown) return rfbDropdown;
    rfbDropdown = document.createElement("div");
    rfbDropdown.className = "combo-dropdown rfb-dropdown";
    rfbDropdown.hidden = true;
    rfbDropdown.style.cssText = "position:fixed; right:auto; top:0; left:0; width:460px; max-width:calc(100vw - 32px); max-height:320px; z-index:1000;";
    rfbDropdown.addEventListener("mousedown", function(ev){ ev.preventDefault(); });
    document.body.appendChild(rfbDropdown);
    return rfbDropdown;
  }
  function rfbPosicionar(){
    if(!rfbDropdown || !rfbInputAtivo) return;
    var r = rfbInputAtivo.getBoundingClientRect();
    var largura = Math.min(460, window.innerWidth - 32);
    var left = Math.max(16, Math.min(r.left, window.innerWidth - largura - 16));
    var espacoAbaixo = window.innerHeight - r.bottom;
    rfbDropdown.style.left = left + "px";
    if(espacoAbaixo < 200 && r.top > espacoAbaixo){
      rfbDropdown.style.top = "auto";
      rfbDropdown.style.bottom = (window.innerHeight - r.top + 4) + "px";
      rfbDropdown.style.maxHeight = Math.min(320, r.top - 20) + "px";
    } else {
      rfbDropdown.style.bottom = "auto";
      rfbDropdown.style.top = (r.bottom + 4) + "px";
      rfbDropdown.style.maxHeight = Math.min(320, espacoAbaixo - 20) + "px";
    }
  }
  function rfbFechar(){
    if(rfbDropdown) rfbDropdown.hidden = true;
    rfbInputAtivo = null; rfbAtivoIdx = -1; rfbItensVisiveis = [];
  }
  function rfbEscolher(r){
    var inp = rfbInputAtivo;
    if(!inp) return;
    inp.value = r.classificacao;
    inp.title = r.classificacao + " — " + r.descricao;
    rfbFechar();
    inp.dispatchEvent(new Event("change", { bubbles: true }));
  }
  function rfbMarcarAtivo(idx){
    var opts = rfbDropdown.querySelectorAll(".combo-option");
    opts.forEach(function(o, i){ o.classList.toggle("active", i === idx); });
    rfbAtivoIdx = idx;
    if(opts[idx]) opts[idx].scrollIntoView({ block: "nearest" });
  }
  function rfbRender(){
    var dd = rfbGarantirDropdown();
    var termo = normalizeTexto(rfbInputAtivo.value).trim();
    dd.innerHTML = "";
    rfbItensVisiveis = [];
    var LIMITE = 300, total = 0;
    RFB_REFERENCIAL.forEach(function(r){
      var estR = estadoVisRfb(r.classificacao);
      if(estR === "oculta") return;
      if(termo){
        var alvo = normalizeTexto(r.classificacao + " " + r.descricao);
        if(alvo.indexOf(termo) === -1) return;
      }
      total++;
      if(total > LIMITE) return;
      var analitica = /^anal/i.test(r.tipo || "");
      if(analitica && estR === "bloqueada"){
        var elB = document.createElement("div");
        elB.className = "combo-empty";
        elB.style.cssText = "text-decoration:line-through; opacity:.6; text-align:left;";
        elB.title = "Bloqueada em Opções > Plano Referencial da Receita";
        elB.textContent = "🔒 " + r.classificacao + " " + r.descricao;
        dd.appendChild(elB);
        return;
      }
      var el = document.createElement("div");
      if(analitica){
        el.className = "combo-option";
        var nome = document.createElement("span"); nome.textContent = r.descricao;
        var cod = document.createElement("span"); cod.className = "combo-doc"; cod.textContent = r.classificacao;
        el.appendChild(cod); el.appendChild(nome);
        el.style.justifyContent = "flex-start";
        var idx = rfbItensVisiveis.length;
        rfbItensVisiveis.push(r);
        el.addEventListener("click", function(){ rfbEscolher(r); });
        el.addEventListener("mousemove", function(){ if(rfbAtivoIdx !== idx) rfbMarcarAtivo(idx); });
      } else {
        // Contas sintéticas do referencial: só título de grupo (não recebem vínculo).
        el.className = "combo-empty";
        el.style.cssText = "font-weight:600; color:var(--text); padding-top:10px;";
        el.textContent = r.classificacao + " — " + r.descricao;
      }
      dd.appendChild(el);
    });
    if(total === 0){
      var vazio = document.createElement("div"); vazio.className = "combo-empty"; vazio.textContent = "Nenhuma conta referencial encontrada.";
      dd.appendChild(vazio);
    } else if(total > LIMITE){
      var mais = document.createElement("div"); mais.className = "combo-empty";
      mais.textContent = "Mostrando " + LIMITE + " de " + total + " — digite parte do código ou da descrição para filtrar.";
      dd.appendChild(mais);
    }
    rfbAtivoIdx = -1;
    dd.hidden = false;
    rfbPosicionar();
  }
  function rfbAbrir(inp){
    rfbInputAtivo = inp;
    rfbRender();
    // Se já tem valor, rola até ele.
    var atual = inp.value.trim();
    if(atual){
      var achou = rfbItensVisiveis.findIndex(function(r){ return r.classificacao === atual; });
      if(achou >= 0) rfbMarcarAtivo(achou);
    }
  }
  window.addEventListener("resize", function(){ if(rfbInputAtivo) rfbPosicionar(); });
  document.addEventListener("scroll", function(ev){
    if(!rfbInputAtivo) return;
    if(rfbDropdown && (ev.target === rfbDropdown || rfbDropdown.contains(ev.target))) return;
    rfbPosicionar();
  }, true);

  if(elPlanoContasLista){
    elPlanoContasLista.addEventListener("focusin", function(ev){
      if(ev.target.classList && ev.target.classList.contains("plano-conta-ref-rfb-input")){
        ev.target.dataset.valorAntes = ev.target.value;
        ev.target.select();
        rfbAbrir(ev.target);
      }
    });
    elPlanoContasLista.addEventListener("input", function(ev){
      if(ev.target.classList && ev.target.classList.contains("plano-conta-ref-rfb-input")){
        rfbInputAtivo = ev.target;
        rfbRender();
      }
    });
    elPlanoContasLista.addEventListener("focusout", function(ev){
      if(ev.target.classList && ev.target.classList.contains("plano-conta-ref-rfb-input") && ev.target === rfbInputAtivo){
        setTimeout(function(){ if(document.activeElement !== ev.target) rfbFechar(); }, 150);
      }
    });
    elPlanoContasLista.addEventListener("keydown", function(ev){
      if(!(ev.target.classList && ev.target.classList.contains("plano-conta-ref-rfb-input"))) return;
      if(!rfbInputAtivo || !rfbDropdown || rfbDropdown.hidden){
        if(ev.key === "ArrowDown"){ ev.preventDefault(); rfbAbrir(ev.target); }
        return;
      }
      if(ev.key === "ArrowDown"){ ev.preventDefault(); rfbMarcarAtivo(Math.min(rfbItensVisiveis.length - 1, rfbAtivoIdx + 1)); }
      else if(ev.key === "ArrowUp"){ ev.preventDefault(); rfbMarcarAtivo(Math.max(0, rfbAtivoIdx - 1)); }
      else if(ev.key === "Enter"){
        ev.preventDefault();
        if(rfbAtivoIdx >= 0 && rfbItensVisiveis[rfbAtivoIdx]){ rfbEscolher(rfbItensVisiveis[rfbAtivoIdx]); }
        else if(rfbItensVisiveis.length === 1){ rfbEscolher(rfbItensVisiveis[0]); }
      }
      else if(ev.key === "Escape"){ ev.preventDefault(); ev.target.value = ev.target.dataset.valorAntes || ""; rfbFechar(); ev.target.blur(); }
    });
  }

  async function salvarVisPlano(parte, codigo, valor, toastEl){
    var novo = { contas: Object.assign({}, visPlano.contas), rfb: Object.assign({}, visPlano.rfb) };
    if(valor) novo[parte][codigo] = valor; else delete novo[parte][codigo];
    try{
      await db.doc("listaConfig/planoVisibilidade").set(novo);
      visPlano = novo;
      genericToast(toastEl, codigo + ": " + (valor === "oculta" ? "oculta" : valor === "bloqueada" ? "bloqueada" : "disponível") + ".", false);
    }catch(e){ genericToast(toastEl, "Não foi possível salvar agora. Tente novamente.", true); }
    aplicarVisPlano();
  }
  function aplicarVisPlano(){
    renderPlanoContas();
    renderRfbVis();
    renderRegrasContabeis();
    renderOpcoes();
    atualizarCamposContabeis();
  }
  function renderRfbVis(){
    var lista = document.getElementById("rfb-vis-lista");
    if(!lista) return;
    var termo = normalizeTexto((document.getElementById("rfb-vis-busca") || {}).value || "").trim();
    var comAnal = !!(document.getElementById("rfb-vis-analiticas") || {}).checked;
    var soMarc = !!(document.getElementById("rfb-vis-so-marcadas") || {}).checked;
    var frag = document.createDocumentFragment(), n = 0;
    RFB_REFERENCIAL.forEach(function(r){
      var anal = /^anal/i.test(r.tipo || "");
      if(anal && !comAnal && !termo) return;
      var est = estadoVisRfb(r.classificacao), proprio = visPlano.rfb[r.classificacao] || "";
      if(soMarc && !est) return;
      if(termo && normalizeTexto(r.classificacao + " " + r.descricao).indexOf(termo) === -1) return;
      if(++n > 600) return;
      var row = document.createElement("div");
      row.className = "rfb-vis-row" + (est ? " vis-" + est : "");
      row.style.paddingLeft = ((r.classificacao.split(".").length - 1) * 14) + "px";
      var cod = document.createElement("span"); cod.className = "rfb-cod"; cod.textContent = r.classificacao;
      var desc = document.createElement("span"); desc.className = "rfb-desc"; desc.textContent = r.descricao; if(!anal) desc.style.fontWeight = "600";
      var sel = document.createElement("select"); sel.className = "plano-conta-vis rfb-vis-sel"; sel.dataset.codigo = r.classificacao;
      var herdado = proprio ? "" : est;
      [["", "Disponível"], ["bloqueada", "🔒 Bloqueada"], ["oculta", "🙈 Oculta"]].forEach(function(o){
        var op = document.createElement("option"); op.value = o[0]; op.textContent = o[1] + (herdado && o[0] === herdado ? " (pelo grupo)" : ""); sel.appendChild(op);
      });
      sel.value = proprio || herdado;
      if(herdado){ sel.disabled = true; sel.title = "Herdado do grupo acima — altere lá."; }
      row.appendChild(cod); row.appendChild(desc); row.appendChild(sel);
      frag.appendChild(row);
    });
    lista.innerHTML = "";
    if(!n){ var p = document.createElement("p"); p.className = "empty"; p.textContent = "Nada encontrado."; lista.appendChild(p); }
    if(n > 600){ var p2 = document.createElement("p"); p2.className = "footnote"; p2.textContent = "Mostrando 600 de " + n + " — use a busca para refinar."; frag.appendChild(p2); }
    lista.appendChild(frag);
  }
  (function ligarVisPlano(){
    var lista = document.getElementById("rfb-vis-lista");
    if(lista) lista.addEventListener("change", function(ev){
      if(!ev.target.classList.contains("rfb-vis-sel") || !db) return;
      salvarVisPlano("rfb", ev.target.dataset.codigo, ev.target.value, document.getElementById("rfb-vis-toast"));
    });
    ["rfb-vis-busca"].forEach(function(id){ var e = document.getElementById(id); if(e) e.addEventListener("input", renderRfbVis); });
    ["rfb-vis-analiticas", "rfb-vis-so-marcadas"].forEach(function(id){ var e = document.getElementById(id); if(e) e.addEventListener("change", renderRfbVis); });
    var mo = document.getElementById("plano-mostrar-ocultas"); if(mo) mo.addEventListener("change", renderPlanoContas);
    if(elPlanoContasLista) elPlanoContasLista.addEventListener("change", function(ev){
      if(!ev.target.classList.contains("plano-conta-vis") || ev.target.classList.contains("rfb-vis-sel") || !db) return;
      salvarVisPlano("contas", ev.target.dataset.codigo, ev.target.value, elPlanoContasToast);
    });
  })();

  if(elPlanoContasLista){
    elPlanoContasLista.addEventListener("change", async function(ev){
      if(!db) return;
      var id = ev.target.dataset.id;
      if(!id) return;
      if(ev.target.classList.contains("plano-conta-nome-input")){
        var novoNome = ev.target.value.trim();
        if(!novoNome){
          genericToast(elPlanoContasToast, "O nome da conta não pode ficar em branco.", true);
          renderPlanoContas();
          return;
        }
        // Nomes repetidos são normais num plano de contas real (ex.: "SALÁRIOS E ORDENADOS" em
        // vários departamentos diferentes) — só bloqueia se já existir OUTRA conta com o mesmo
        // nome sob a MESMA conta pai (aí sim seria uma duplicata de verdade).
        var contaSendoRenomeada = contaContabilById(id);
        var paiDaRenomeada = contaSendoRenomeada ? codigoPaiDe(contaSendoRenomeada.codigo) : null;
        var duplicado = planoContas.some(function(c){ return c.id !== id && codigoPaiDe(c.codigo) === paiDaRenomeada && c.nome.toLowerCase() === novoNome.toLowerCase(); });
        if(duplicado){
          genericToast(elPlanoContasToast, "Já existe uma conta com esse nome na mesma conta pai.", true);
          renderPlanoContas();
          return;
        }
        var novo = planoContas.map(function(c){ return c.id === id ? Object.assign({}, c, { nome: novoNome }) : c; });
        await db.doc("listaConfig/planoContas").set({ contas: novo });
        genericToast(elPlanoContasToast, "Conta renomeada.", false);
      } else if(ev.target.classList.contains("plano-conta-ref-rfb-input")){
        var novoRef = ev.target.value.trim();
        if(novoRef && estadoVisRfb(novoRef)){
          genericToast(elPlanoContasToast, "A conta referencial " + novoRef + " está " + (estadoVisRfb(novoRef) === "oculta" ? "oculta" : "bloqueada") + " (Opções > Plano Referencial da Receita).", true);
          ev.target.value = ev.target.dataset.valorAntes || "";
          return;
        }
        var novo2 = planoContas.map(function(c){ return c.id === id ? Object.assign({}, c, { refRFB: novoRef || null }) : c; });
        await db.doc("listaConfig/planoContas").set({ contas: novo2 });
        genericToast(elPlanoContasToast, novoRef ? "Referência da Receita Federal salva." : "Referência da Receita Federal removida.", false);
      }
    });
    elPlanoContasLista.addEventListener("click", async function(ev){
      var btn = ev.target.closest(".plano-conta-remover");
      if(!btn || !db) return;
      var id = btn.dataset.id;
      var conta = contaContabilById(id);
      if(conta && conta.codigo && contaEhSintetica(conta) && planoContasFilhos(conta.codigo).length){
        genericToast(elPlanoContasToast, "Esta conta é Sintética e tem contas filhas — exclua ou mova as contas filhas antes.", true);
        return;
      }
      await Promise.all([garantirIndice("fornecedores"), garantirIndice("clientes")]);
      if(contaContabilEmUso(id)){
        genericToast(elPlanoContasToast, "Esta conta está em uso (vinculada a um fornecedor/cliente, banco, regra de tipo ou lançamento) e não pode ser excluída.", true);
        return;
      }
      var novo = planoContas.filter(function(c){ return c.id !== id; });
      await db.doc("listaConfig/planoContas").set({ contas: novo });
      genericToast(elPlanoContasToast, "Conta excluída.", false);
    });
  }

  if(elBtnPlanoContaAdd){
    elBtnPlanoContaAdd.addEventListener("click", async function(){
      if(!db){ genericToast(elPlanoContasToast, "Armazenamento indisponível nesta visualização.", true); return; }
      var paiCodigo = elPlanoContaPai.value;
      if(!paiCodigo){ genericToast(elPlanoContasToast, "Escolha a conta pai (uma conta Sintética já cadastrada).", true); return; }
      var pai = planoContaPorCodigo(paiCodigo);
      if(!pai){ genericToast(elPlanoContasToast, "Conta pai não encontrada — atualize a página e tente de novo.", true); return; }
      var nome = elPlanoContaNome.value.trim();
      if(!nome){ genericToast(elPlanoContasToast, "Digite o nome da conta.", true); return; }
      // Nomes repetidos são normais num plano de contas real (ex.: "SALÁRIOS E ORDENADOS" em
      // vários departamentos diferentes) — só bloqueia se já existir OUTRA conta com o mesmo
      // nome sob a MESMA conta pai (aí sim seria uma duplicata de verdade).
      var duplicado = planoContas.some(function(c){ return codigoPaiDe(c.codigo) === paiCodigo && c.nome.toLowerCase() === nome.toLowerCase(); });
      if(duplicado){ genericToast(elPlanoContasToast, "Já existe uma conta com esse nome na mesma conta pai.", true); return; }
      var tipo = (elPlanoContaTipo && elPlanoContaTipo.value === "sintetica") ? "sintetica" : "analitica";
      var codigo = proximoCodigoFilho(paiCodigo);
      var catPaiManual = catPorPaiContas(paiCodigo);
      if(catPaiManual && contasPartAtivas(catPaiManual)){
        try{ codigo = codigoContaPart(catPaiManual, await reservarSeqsPart(catPaiManual, 1, 0)); }
        catch(errSeq){ genericToast(elPlanoContasToast, (errSeq && errSeq.friendlyMessage) || "Não foi possível reservar o código agora.", true); return; }
      }
      var novaConta = {
        id: "conta_" + Date.now().toString(36) + "_" + Math.random().toString(36).slice(2, 8),
        codigo: codigo,
        nome: nome,
        tipo: tipo,
        natureza: naturezaDeConta(pai),
        grupo: grupoDeConta(pai),
        refRFB: null
      };
      var novo = planoContas.concat([novaConta]);
      elBtnPlanoContaAdd.disabled = true;
      try{
        await db.doc("listaConfig/planoContas").set({ contas: novo });
        elPlanoContaNome.value = "";
        genericToast(elPlanoContasToast, "Conta \"" + nome + "\" (código " + codigo + ") adicionada em \"" + pai.nome + "\".", false);
      }catch(err){
        genericToast(elPlanoContasToast, "Não foi possível salvar agora. Tente novamente.", true);
      }finally{
        elBtnPlanoContaAdd.disabled = false;
      }
    });
  }

  // ---- Importar/baixar modelo de Plano de Contas (planilha) ------------
  // Formato atual (com hierarquia/Sintética-Analítica): Código, Nome da conta, Tipo,
  // Natureza, Grupo, Referência Receita Federal (opcional). Formato antigo, ainda aceito na
  // importação por compatibilidade (planilhas baixadas antes desta versão): Nome da
  // conta + Categoria — vira uma conta "legada" (sem código/hierarquia).
  var PLANO_IMPORT_COL_CODIGO = "Código";
  var PLANO_IMPORT_COL_NOME = "Nome da conta";
  var PLANO_IMPORT_COL_TIPO = "Tipo";
  var PLANO_IMPORT_COL_NATUREZA = "Natureza";
  var PLANO_IMPORT_COL_GRUPO = "Grupo";
  var PLANO_IMPORT_COL_REF_RFB = "Referência Receita Federal";
  var PLANO_IMPORT_COLUNAS = [PLANO_IMPORT_COL_CODIGO, PLANO_IMPORT_COL_NOME, PLANO_IMPORT_COL_TIPO, PLANO_IMPORT_COL_NATUREZA, PLANO_IMPORT_COL_GRUPO, PLANO_IMPORT_COL_REF_RFB];
  var PLANO_IMPORT_COL_CATEGORIA_LEGADA = "Categoria";

  function linhaVaziaImportPlano(row){
    return valorTexto(row[PLANO_IMPORT_COL_NOME]) === "" && valorTexto(row[PLANO_IMPORT_COL_CODIGO]) === "";
  }
  function linhaVaziaImportPlanoLegado(row){
    return valorTexto(row[PLANO_IMPORT_COL_NOME]) === "" && valorTexto(row[PLANO_IMPORT_COL_CATEGORIA_LEGADA]) === "";
  }

  function resolverTipoContaTexto(texto){
    var n = normalizeTexto(texto).trim();
    if(n === "sintetica" || n === "s") return "sintetica";
    if(n === "analitica" || n === "a") return "analitica";
    return null;
  }
  function resolverNaturezaContaTexto(texto){
    var n = normalizeTexto(texto).trim();
    if(n === "debito" || n === "d") return "Débito";
    if(n === "credito" || n === "c") return "Crédito";
    return null;
  }
  function resolverGrupoContaTexto(texto){
    var n = normalizeTexto(texto).trim();
    var achado = GRUPOS_PLANO_CONTAS.filter(function(g){ return normalizeTexto(g) === n; })[0];
    return achado || null;
  }
  function resolverCategoriaPlanoConta(texto){
    var norm = normalizeTexto(texto).trim();
    var porChave = PLANO_CATEGORIAS.filter(function(c){ return c.key === norm; })[0];
    if(porChave) return porChave.key;
    var porLabel = PLANO_CATEGORIAS.filter(function(c){ return normalizeTexto(c.label) === norm; })[0];
    return porLabel ? porLabel.key : null;
  }

  function processarLinhaImportPlanoConta(row, codigosExistentes, nomesExistentesNorm){
    var codigo = valorTexto(row[PLANO_IMPORT_COL_CODIGO]);
    if(!codigo){ throw new Error("Informe o código (classificação) na coluna \"" + PLANO_IMPORT_COL_CODIGO + "\"."); }
    if(!/^\d+(\.\d+)*$/.test(codigo)){
      throw new Error("Código \"" + codigo + "\" inválido — use só números separados por ponto (ex.: 1.1.1.01.001).");
    }
    var nome = valorTexto(row[PLANO_IMPORT_COL_NOME]);
    if(!nome){ throw new Error("Informe o nome da conta na coluna \"" + PLANO_IMPORT_COL_NOME + "\"."); }
    var tipoTexto = valorTexto(row[PLANO_IMPORT_COL_TIPO]);
    var tipo = resolverTipoContaTexto(tipoTexto);
    if(!tipo){ throw new Error("Tipo \"" + tipoTexto + "\" inválido — use Sintética ou Analítica."); }
    var naturezaTexto = valorTexto(row[PLANO_IMPORT_COL_NATUREZA]);
    var natureza = resolverNaturezaContaTexto(naturezaTexto);
    if(!natureza){ throw new Error("Natureza \"" + naturezaTexto + "\" inválida — use Débito ou Crédito."); }
    var grupoTexto = valorTexto(row[PLANO_IMPORT_COL_GRUPO]);
    var grupo = resolverGrupoContaTexto(grupoTexto);
    if(!grupo){ throw new Error("Grupo \"" + grupoTexto + "\" não reconhecido. Use " + GRUPOS_PLANO_CONTAS.join(", ") + "."); }
    if(codigosExistentes[codigo]){
      var codErr = new Error("Já existe uma conta com o código \"" + codigo + "\" — linha ignorada.");
      codErr.jaExiste = true;
      throw codErr;
    }
    var normNome = normalizeTexto(nome);
    var paiCodigo = codigoPaiDe(codigo);
    // Nomes repetidos são normais num plano de contas real (ex.: "SALÁRIOS E ORDENADOS" em
    // vários departamentos diferentes, cada um com seu próprio código) — inclusive o próprio
    // padrão "Conta Azul" embutido no sistema tem isso. Só bloqueia se já existir OUTRA conta
    // com o mesmo nome sob a MESMA conta pai (aí sim seria uma duplicata de verdade).
    var nomeDuplicadoNoMesmoPai = Object.keys(codigosExistentes).some(function(cod){
      return codigoPaiDe(cod) === paiCodigo && normalizeTexto(codigosExistentes[cod].nome) === normNome;
    });
    if(nomeDuplicadoNoMesmoPai){
      var jaExisteErr = new Error("Já existe uma conta chamada \"" + nome + "\" na mesma conta pai — linha ignorada.");
      jaExisteErr.jaExiste = true;
      throw jaExisteErr;
    }
    if(paiCodigo){
      var pai = codigosExistentes[paiCodigo];
      if(!pai){
        throw new Error("Conta pai de código \"" + paiCodigo + "\" não encontrada — confira se a linha dessa conta vem antes desta na planilha, ou se o código \"" + codigo + "\" está correto.");
      }
      if(pai.tipo !== "sintetica"){
        throw new Error("A conta pai (código \"" + paiCodigo + "\") é Analítica — só contas Sintéticas podem ter contas filhas.");
      }
    }
    var refRFBTexto = valorTexto(row[PLANO_IMPORT_COL_REF_RFB]);
    return {
      id: "conta_" + Date.now().toString(36) + "_" + Math.random().toString(36).slice(2, 8) + Math.random().toString(36).slice(2, 5),
      codigo: codigo,
      nome: nome,
      tipo: tipo,
      natureza: natureza,
      grupo: grupo,
      refRFB: refRFBTexto || null
    };
  }

  function processarLinhaImportPlanoContaLegado(row, existentesNorm){
    var nome = valorTexto(row[PLANO_IMPORT_COL_NOME]);
    if(!nome){ throw new Error("Informe o nome da conta na coluna \"" + PLANO_IMPORT_COL_NOME + "\"."); }
    var categoriaTexto = valorTexto(row[PLANO_IMPORT_COL_CATEGORIA_LEGADA]);
    if(!categoriaTexto){ throw new Error("Informe a categoria na coluna \"" + PLANO_IMPORT_COL_CATEGORIA_LEGADA + "\"."); }
    var categoria = resolverCategoriaPlanoConta(categoriaTexto);
    if(!categoria){
      throw new Error("Categoria \"" + categoriaTexto + "\" não reconhecida. Use Ativo, Passivo, Patrimônio Líquido, Receita ou Despesa.");
    }
    var normNome = normalizeTexto(nome);
    if(existentesNorm.indexOf(normNome) !== -1){
      var jaExisteErr = new Error("Já existe uma conta chamada \"" + nome + "\" — linha ignorada.");
      jaExisteErr.jaExiste = true;
      throw jaExisteErr;
    }
    return {
      id: "conta_" + Date.now().toString(36) + "_" + Math.random().toString(36).slice(2, 8) + Math.random().toString(36).slice(2, 5),
      nome: nome,
      categoria: categoria
    };
  }

  function renderImportPlanoContasRelatorio(erros, jaExistentes, totalLinhas, importadosCount){
    if(!elImportPlanoContasRelatorio) return;
    elImportPlanoContasRelatorio.innerHTML = "";
    if(erros.length === 0 && jaExistentes.length === 0){
      elImportPlanoContasRelatorio.hidden = true;
      return;
    }
    elImportPlanoContasRelatorio.hidden = false;
    elImportPlanoContasRelatorio.className = "import-relatorio";
    var resumo = document.createElement("div");
    resumo.className = "import-relatorio-resumo";
    var partes = [importadosCount + " de " + totalLinhas + " linha(s) importada(s)."];
    if(jaExistentes.length){ partes.push(jaExistentes.length + " já existente(s) (ignorada(s))."); }
    if(erros.length){ partes.push(erros.length + " linha(s) com erro:"); }
    resumo.textContent = partes.join(" ");
    elImportPlanoContasRelatorio.appendChild(resumo);
    if(erros.length){
      var ul = document.createElement("ul");
      erros.forEach(function(e){
        var li = document.createElement("li");
        var span = document.createElement("span");
        span.className = "linha-num";
        span.textContent = "Linha " + e.linha + ":";
        li.appendChild(span);
        li.appendChild(document.createTextNode(" " + e.mensagem));
        ul.appendChild(li);
      });
      elImportPlanoContasRelatorio.appendChild(ul);
    }
  }

  async function importarPlanoContas(){
    var arquivo = elImportPlanoContasFile.files && elImportPlanoContasFile.files[0];
    if(!arquivo){
      genericToast(elImportPlanoContasToast, "Selecione um arquivo .xlsx ou .csv antes de importar.", true);
      return;
    }
    if(!db){ genericToast(elImportPlanoContasToast, "Armazenamento indisponível nesta visualização.", true); return; }
    if(typeof XLSX === "undefined"){
      genericToast(elImportPlanoContasToast, "Não foi possível carregar o leitor de planilhas nesta visualização.", true);
      return;
    }
    elBtnImportarPlanoContas.disabled = true;
    try{
      var buffer = await arquivo.arrayBuffer();
      var wb = XLSX.read(buffer, { type: "array" });
      if(!wb.SheetNames.length){
        genericToast(elImportPlanoContasToast, "A planilha está vazia.", true);
        return;
      }
      var sheet = wb.Sheets[wb.SheetNames[0]];
      var linhas = XLSX.utils.sheet_to_json(sheet, { defval: "" });
      if(linhas.length === 0){
        genericToast(elImportPlanoContasToast, "Nenhuma linha de dados encontrada na primeira planilha do arquivo.", true);
        return;
      }
      var novasContas = [];
      var erros = [];
      var jaExistentes = [];
      var totalConsideradas = 0;
      // Formato novo (com hierarquia) se a planilha tem a coluna "Código"; senão, formato
      // antigo (Nome da conta + Categoria), por compatibilidade com planilhas baixadas antes.
      var formatoNovo = Object.prototype.hasOwnProperty.call(linhas[0], PLANO_IMPORT_COL_CODIGO);
      if(formatoNovo){
        var codigosExistentes = {};
        planoContas.forEach(function(c){ if(c.codigo) codigosExistentes[c.codigo] = c; });
        for(var cc = 0; cc < CATS_CONTAS.length; cc++){
          var catImp = CATS_CONTAS[cc];
          if(!contasPartAtivas(catImp)) continue;
          await garantirIndice(catImp);
          Object.keys(indicePart[catImp].porId).forEach(function(k){
            var itc = indicePart[catImp].porId[k];
            if(itc.codigo) codigosExistentes[itc.codigo] = { codigo: itc.codigo, nome: itc.nome };
          });
        }
        var nomesExistentesNorm = planoContas.map(function(c){ return normalizeTexto(c.nome); });
        linhas.forEach(function(row, idx){
          if(linhaVaziaImportPlano(row)) return;
          totalConsideradas++;
          var numeroLinha = idx + 2; // +1 pelo cabeçalho, +1 porque idx é 0-based
          try{
            var conta = processarLinhaImportPlanoConta(row, codigosExistentes, nomesExistentesNorm);
            novasContas.push(conta);
            codigosExistentes[conta.codigo] = conta;
            nomesExistentesNorm.push(normalizeTexto(conta.nome));
          }catch(err){
            if(err.jaExiste){ jaExistentes.push({ linha: numeroLinha, mensagem: err.message }); }
            else{ erros.push({ linha: numeroLinha, mensagem: err.message }); }
          }
        });
      } else {
        var existentesNorm = planoContas.map(function(c){ return normalizeTexto(c.nome); });
        linhas.forEach(function(row, idx){
          if(linhaVaziaImportPlanoLegado(row)) return;
          totalConsideradas++;
          var numeroLinha2 = idx + 2;
          try{
            var contaLegada = processarLinhaImportPlanoContaLegado(row, existentesNorm);
            novasContas.push(contaLegada);
            existentesNorm.push(normalizeTexto(contaLegada.nome));
          }catch(err){
            if(err.jaExiste){ jaExistentes.push({ linha: numeroLinha2, mensagem: err.message }); }
            else{ erros.push({ linha: numeroLinha2, mensagem: err.message }); }
          }
        });
      }
      if(novasContas.length > 0){
        var novo = planoContas.concat(novasContas);
        await db.doc("listaConfig/planoContas").set({ contas: novo });
      }
      renderImportPlanoContasRelatorio(erros, jaExistentes, totalConsideradas, novasContas.length);
      if(novasContas.length > 0 && erros.length === 0 && jaExistentes.length === 0){
        genericToast(elImportPlanoContasToast, novasContas.length + " conta(s) importada(s) para o Plano de Contas.", false);
      } else if(novasContas.length > 0 && erros.length === 0){
        genericToast(elImportPlanoContasToast, novasContas.length + " conta(s) importada(s); " + jaExistentes.length + " já existente(s) (ignorada(s)).", false);
      } else if(novasContas.length > 0 && erros.length > 0){
        genericToast(elImportPlanoContasToast, novasContas.length + " conta(s) importada(s); " + erros.length + " linha(s) com erro — veja o relatório abaixo.", true);
      } else if(erros.length === 0 && jaExistentes.length > 0){
        genericToast(elImportPlanoContasToast, "Todas as contas da planilha já existiam no Plano de Contas — nada foi duplicado.", false);
      } else if(erros.length > 0 && jaExistentes.length > 0){
        genericToast(elImportPlanoContasToast, "Nenhuma conta nova: " + jaExistentes.length + " já existente(s) e " + erros.length + " linha(s) com erro — veja o relatório abaixo.", true);
      } else {
        genericToast(elImportPlanoContasToast, "Nenhuma conta pôde ser importada. Veja o relatório de erros abaixo.", true);
      }
    }catch(err){
      genericToast(elImportPlanoContasToast, "Não foi possível ler o arquivo. Verifique se é um .xlsx ou .csv válido.", true);
    } finally {
      elBtnImportarPlanoContas.disabled = false;
      elImportPlanoContasFile.value = "";
    }
  }
  if(elBtnImportarPlanoContas){
    elBtnImportarPlanoContas.addEventListener("click", importarPlanoContas);
  }

  async function baixarModeloPlanoContas(){
    if(typeof XLSX === "undefined" || !downloadsCap){
      genericToast(elImportPlanoContasToast, "O download de arquivos não está disponível aqui.", true);
      return;
    }
    var linhasModelo = PLANO_CONTAS_PADRAO.map(function(c){
      var linha = {};
      linha[PLANO_IMPORT_COL_CODIGO] = c.codigo;
      linha[PLANO_IMPORT_COL_NOME] = c.nome;
      linha[PLANO_IMPORT_COL_TIPO] = c.tipo === "sintetica" ? "Sintética" : "Analítica";
      linha[PLANO_IMPORT_COL_NATUREZA] = c.natureza;
      linha[PLANO_IMPORT_COL_GRUPO] = c.grupo;
      linha[PLANO_IMPORT_COL_REF_RFB] = "";
      return linha;
    });
    var ws = XLSX.utils.json_to_sheet(linhasModelo, { header: PLANO_IMPORT_COLUNAS });
    ws["!cols"] = [{ wch: 16 }, { wch: 55 }, { wch: 12 }, { wch: 10 }, { wch: 20 }, { wch: 34 }];
    var instrucoes = [
      ["Como preencher esta planilha"],
      [""],
      ["1. Uma linha = uma conta contábil. Não altere os nomes das colunas na aba \"Plano de Contas\"."],
      ["2. Código: a classificação hierárquica da conta (ex.: 1.1.1.01.001), só números separados por ponto — é o identificador único da conta (funciona também como \"código reduzido\", não existe um campo separado para isso). A conta pai é o próprio código sem o último segmento (a conta pai de 1.1.1.01.001 é 1.1.1.01) e precisa existir numa linha anterior a esta na planilha."],
      ["3. Tipo: Sintética (totalizador de grupo/subgrupo — não recebe lançamento) ou Analítica (recebe lançamento de Débito/Crédito diretamente). Só uma conta Sintética pode ser conta pai de outra conta."],
      ["4. Natureza: Débito (conta devedora) ou Crédito (conta credora) — define se a conta aparece no campo Débito ou no campo Crédito dos lançamentos."],
      ["5. Grupo: " + GRUPOS_PLANO_CONTAS.join(", ") + " — \"Outras\" é para contas de controle/apuração que não são propriamente Ativo, Passivo, Patrimônio Líquido, Receita ou Despesa."],
      ["6. Referência Receita Federal (opcional): código de classificação da conta equivalente no Plano de Contas Referencial do SPED (usado na ECD/ECF) — ex.: 1.01.01.01.01. Pode deixar em branco e preencher depois, conta por conta, direto no sistema."],
      ["7. Esta planilha já vem preenchida com o plano de contas padrão \"Conta Azul\" completo (752 contas) — edite, apague ou acrescente linhas como quiser antes de importar."],
      ["8. Uma linha é ignorada na importação se o código OU o nome já existir em uma conta já cadastrada no sistema — você pode reimportar a mesma planilha depois de atualizá-la, sem duplicar nada."]
    ];
    var wsInstr = XLSX.utils.aoa_to_sheet(instrucoes);
    wsInstr["!cols"] = [{ wch: 100 }];
    var wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Plano de Contas");
    XLSX.utils.book_append_sheet(wb, wsInstr, "Instruções");
    var arrayBuf = XLSX.write(wb, { bookType: "xlsx", type: "array" });
    var blob = new Blob([arrayBuf], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
    elBtnBaixarModeloPlanoContas.disabled = true;
    try{
      await downloadsCap.save({ filename: "modelo-plano-de-contas.xlsx", data: blob });
      genericToast(elImportPlanoContasToast, "Modelo baixado. Edite como quiser e importe aqui.", false);
    }catch(err){
      var code = err && err.code;
      if(code !== "declined"){
        genericToast(elImportPlanoContasToast, "Não foi possível baixar o modelo. Tente novamente.", true);
      }
    } finally {
      elBtnBaixarModeloPlanoContas.disabled = false;
    }
  }
  if(elBtnBaixarModeloPlanoContas){
    elBtnBaixarModeloPlanoContas.addEventListener("click", baixarModeloPlanoContas);
  }

  // ---- Contas por Tipo de lançamento (regrasContabeis) -------------------
  function renderRegrasContabeis(){
    if(!elRegrasContabeisLista) return;
    elRegrasContabeisLista.innerHTML = "";
    TIPOS.forEach(function(t){
      var regra = regrasContabeis[t.value] || { modo: "auto" };
      var row = document.createElement("div");
      row.className = "cad-row";
      row.dataset.tipo = t.value;
      var top = document.createElement("div");
      top.className = "cad-row-top";
      var titulo = document.createElement("strong"); titulo.textContent = t.label;
      top.appendChild(titulo);
      var selModo = document.createElement("select");
      selModo.className = "regra-modo"; selModo.style.width = "auto"; selModo.style.maxWidth = "240px";
      [["auto", "Automática"], ["fixa", "Fixa (mesma conta para todos)"]].forEach(function(o){
        var op = document.createElement("option"); op.value = o[0]; op.textContent = o[1];
        selModo.appendChild(op);
      });
      selModo.value = regra.modo || "auto";
      top.appendChild(selModo);
      row.appendChild(top);

      var fields = document.createElement("div");
      fields.className = "cad-fields";

      var wrapDeb = document.createElement("div"); wrapDeb.className = "cad-field regra-campo-fixa";
      wrapDeb.hidden = (selModo.value !== "fixa");
      var lblDeb = document.createElement("label"); lblDeb.textContent = "Conta Débito (fixa)";
      wrapDeb.appendChild(lblDeb);
      wrapDeb.appendChild(criarSelectContaContabil("regra-conta-debito", regra.contaDebito));
      fields.appendChild(wrapDeb);

      var wrapCred = document.createElement("div"); wrapCred.className = "cad-field regra-campo-fixa";
      wrapCred.hidden = (selModo.value !== "fixa");
      var lblCred = document.createElement("label"); lblCred.textContent = "Conta Crédito (fixa)";
      wrapCred.appendChild(lblCred);
      wrapCred.appendChild(criarSelectContaContabil("regra-conta-credito", regra.contaCredito));
      fields.appendChild(wrapCred);

      if(t.value === "deposito_nao_identificado" || tipoEhAdiantamento(t.value)){
        var wrapContra = document.createElement("div"); wrapContra.className = "cad-field regra-campo-contrapartida";
        wrapContra.hidden = (selModo.value !== "auto");
        var lblContra = document.createElement("label"); lblContra.textContent = "Conta de contrapartida (modo automático)";
        wrapContra.appendChild(lblContra);
        wrapContra.appendChild(criarSelectContaContabil("regra-conta-contrapartida", regra.contaContrapartida || (tipoEhAdiantamento(t.value) ? TIPOS_ADIANTAMENTO[t.value] : null)));
        fields.appendChild(wrapContra);
      }

      row.appendChild(fields);
      selModo.addEventListener("change", function(){
        var fixaAtiva = selModo.value === "fixa";
        row.querySelectorAll(".regra-campo-fixa").forEach(function(w){ w.hidden = !fixaAtiva; });
        row.querySelectorAll(".regra-campo-contrapartida").forEach(function(w){ w.hidden = fixaAtiva; });
      });
      elRegrasContabeisLista.appendChild(row);
    });
  }

  if(elBtnRegrasContabeisSave){
    elBtnRegrasContabeisSave.addEventListener("click", async function(){
      if(!db){ genericToast(elRegrasContabeisToast, "Armazenamento indisponível nesta visualização.", true); return; }
      var novo = {};
      var erros = [];
      elRegrasContabeisLista.querySelectorAll(".cad-row").forEach(function(row){
        var tipo = row.dataset.tipo;
        var modo = row.querySelector(".regra-modo").value;
        var entry = { modo: modo };
        if(modo === "fixa"){
          var cd = row.querySelector(".regra-conta-debito").value;
          var cc = row.querySelector(".regra-conta-credito").value;
          if(!cd || !cc){
            var labelTipo = (TIPOS.filter(function(tt){ return tt.value === tipo; })[0] || {}).label || tipo;
            erros.push(labelTipo);
          }
          entry.contaDebito = cd || null;
          entry.contaCredito = cc || null;
        } else {
          var contraSel = row.querySelector(".regra-conta-contrapartida");
          if(contraSel){ entry.contaContrapartida = contraSel.value || null; }
        }
        novo[tipo] = entry;
      });
      if(erros.length){
        genericToast(elRegrasContabeisToast, "Selecione as contas Débito e Crédito fixas para: " + erros.join(", ") + ".", true);
        return;
      }
      elBtnRegrasContabeisSave.disabled = true;
      try{
        await db.doc("listaConfig/regrasContabeis").set(novo);
        genericToast(elRegrasContabeisToast, "Contas por tipo de lançamento atualizadas.", false);
      }catch(err){
        genericToast(elRegrasContabeisToast, "Não foi possível salvar agora. Tente novamente.", true);
      }finally{
        elBtnRegrasContabeisSave.disabled = false;
      }
    });
  }

  // ---- Fechamento diário / mensal ---------------------------------------
  function initFechamentoSelects(){
    if(!elFechEmpresa.value){ fillSelect(elFechEmpresa, fullList("empresas")); }
    else{ var v = elFechEmpresa.value; fillSelect(elFechEmpresa, fullList("empresas")); elFechEmpresa.value = v; }
    if(!elFechMesEmpresa.value){ fillSelect(elFechMesEmpresa, fullList("empresas")); }
    else{ var v2 = elFechMesEmpresa.value; fillSelect(elFechMesEmpresa, fullList("empresas")); elFechMesEmpresa.value = v2; }
    if(!elFechData.value){ elFechData.value = todayISO(); }
    if(!elFechMes.value){ elFechMes.value = todayISO().slice(0, 7); }
  }

  function renderFechDiaStatus(){
    var empresa = elFechEmpresa.value, data = elFechData.value;
    elFechDiaStatus.innerHTML = "";
    if(!empresa || !data){ return; }
    var mesFechado = !!(fechamentosMensais[chaveFechMes(empresa, mesDe(data))] || {}).fechado;
    var d = fechamentosDiarios[chaveFechDia(empresa, data)];
    var fechado = diaFechado(empresa, data);
    var badge = document.createElement("span");
    badge.className = "status-badge " + (fechado ? "blocked" : "ok");
    badge.textContent = fechado ? "Fechado" : "Aberto";
    elFechDiaStatus.appendChild(badge);
    if(mesFechado){
      var nota = document.createElement("span");
      nota.className = "footnote"; nota.style.margin = "0 0 0 10px"; nota.style.display = "inline";
      nota.textContent = "(o mês " + mesDe(data) + " está fechado; reabra o mês para editar dias individuais dele)";
      elFechDiaStatus.appendChild(nota);
    } else if(d && d.fechadoPor){
      var nota2 = document.createElement("span");
      nota2.className = "footnote"; nota2.style.margin = "0 0 0 10px"; nota2.style.display = "inline";
      nota2.textContent = "(" + (d.fechado ? "fechado" : "reaberto") + " por " + d.fechadoPor + (d.automatico ? " — automático" : "") + ")";
      elFechDiaStatus.appendChild(nota2);
    }
    elBtnFecharDia.disabled = fechado;
    elBtnReabrirDia.disabled = !d || !d.fechado || mesFechado;
  }
  function renderFechMesStatus(){
    var empresa = elFechMesEmpresa.value, mes = elFechMes.value;
    elFechMesStatus.innerHTML = "";
    if(!empresa || !mes) return;
    var m = fechamentosMensais[chaveFechMes(empresa, mes)];
    var fechado = !!(m && m.fechado);
    var badge = document.createElement("span");
    badge.className = "status-badge " + (fechado ? "blocked" : "ok");
    badge.textContent = fechado ? "Fechado" : "Aberto";
    elFechMesStatus.appendChild(badge);
    if(m && m.fechadoPor){
      var nota = document.createElement("span");
      nota.className = "footnote"; nota.style.margin = "0 0 0 10px"; nota.style.display = "inline";
      nota.textContent = "(" + (fechado ? "fechado" : "reaberto") + " por " + m.fechadoPor + ")";
      elFechMesStatus.appendChild(nota);
    }
    elBtnFecharMes.disabled = fechado;
    elBtnReabrirMes.disabled = !fechado;
  }
  function renderFechamentosHistorico(){
    if(!elTblFechamentosBody) return;
    elTblFechamentosBody.innerHTML = "";
    var linhas = [];
    Object.keys(fechamentosDiarios).forEach(function(k){
      var d = fechamentosDiarios[k];
      if(d) linhas.push({ empresa: d.empresa, periodo: fmtDate(d.data), tipo: "Diário", fechado: d.fechado, por: d.fechadoPor, quando: d.fechadoEm, automatico: d.automatico });
    });
    Object.keys(fechamentosMensais).forEach(function(k){
      var m = fechamentosMensais[k];
      if(m) linhas.push({ empresa: m.empresa, periodo: m.mes, tipo: "Mensal", fechado: m.fechado, por: m.fechadoPor, quando: m.fechadoEm, automatico: false });
    });
    linhas.sort(function(a, b){ return (b.quando || "").localeCompare(a.quando || ""); });
    if(linhas.length === 0){
      var tr = document.createElement("tr");
      var td = document.createElement("td");
      td.colSpan = 6; td.className = "empty"; td.textContent = "Nenhum fechamento registrado ainda.";
      tr.appendChild(td); elTblFechamentosBody.appendChild(tr);
      return;
    }
    linhas.slice(0, 200).forEach(function(l){
      var tr = document.createElement("tr");
      var cells = [l.empresa, l.periodo, l.tipo];
      cells.forEach(function(v){ var td = document.createElement("td"); td.textContent = v; tr.appendChild(td); });
      var tdStatus = document.createElement("td");
      var badge = document.createElement("span");
      badge.className = "status-badge " + (l.fechado ? "blocked" : "ok");
      badge.textContent = l.fechado ? "Fechado" : "Reaberto";
      tdStatus.appendChild(badge); tr.appendChild(tdStatus);
      var tdPor = document.createElement("td"); tdPor.textContent = (l.por || "—") + (l.automatico ? " (automático)" : ""); tr.appendChild(tdPor);
      var tdQuando = document.createElement("td"); tdQuando.textContent = l.quando ? new Date(l.quando).toLocaleString("pt-BR") : "—"; tr.appendChild(tdQuando);
      elTblFechamentosBody.appendChild(tr);
    });
  }

