  // Fechamento automático: ao logar como admin/supervisor, fecha dias úteis já vencidos (prazo:
  // 10h da manhã do dia útil seguinte) que ainda estejam em aberto. Roda apenas quando alguém com
  // permissão de fechamento abre o sistema — não há um servidor rodando em segundo plano aqui.
  async function verificarFechamentosAutomaticos(){
    if(!db || !canEditLancamentos()) return;
    var hojeISO = todayISO();
    var agora = new Date();
    var empresasTodas = fullList("empresas");
    for(var e = 0; e < empresasTodas.length; e++){
      var empresa = empresasTodas[e];
      for(var i = 1; i <= 45; i++){
        var dt = new Date(hojeISO + "T00:00:00");
        dt.setDate(dt.getDate() - i);
        var dataISO = dataISOFromDate(dt);
        if(dataISO >= hojeISO) continue;
        if(diaFechado(empresa, dataISO)) continue;
        var prazo = prazoFechamentoAutomatico(dataISO);
        if(agora >= prazo){
          try{
            await db.doc("fechamentosDiarios/" + chaveFechDia(empresa, dataISO)).set({
              empresa: empresa, data: dataISO, fechado: true, automatico: true,
              fechadoPor: "sistema", fechadoEm: new Date().toISOString()
            });
          }catch(err){ /* tenta de novo na próxima abertura do sistema */ }
        }
      }
    }
  }

  // ---- Usuários ---------------------------------------------------------
  elBtnUserSave.addEventListener("click", async function(){
    if(!db){ genericToast(elUserToast, "Armazenamento indisponível nesta visualização.", true); return; }
    var usuario = elUUsuario.value.trim();
    var senha = elUSenha.value;
    var papel = elUPapel.value;
    var email = elUEmail.value.trim();
    if(!usuario){ genericToast(elUserToast, "Informe o nome de usuário.", true); return; }
    if(senha.length < 4){ genericToast(elUserToast, "A senha deve ter pelo menos 4 caracteres.", true); return; }
    if(!papel){ genericToast(elUserToast, "Selecione o papel do usuário.", true); return; }
    if(findUserDoc(usuario)){ genericToast(elUserToast, "Já existe um usuário com esse nome.", true); return; }
    var areasSel = [];
    elUAreaList.querySelectorAll("input[type=checkbox]").forEach(function(cb){ if(cb.checked) areasSel.push(cb.value); });
    if(areasSel.length === 0){ genericToast(elUserToast, "Marque ao menos uma área.", true); return; }
    var todas = elUTodasEmpresas.checked;
    var empresasSel = [];
    if(!todas){
      elUEmpresasList.querySelectorAll("input[type=checkbox]").forEach(function(cb){ if(cb.checked) empresasSel.push(cb.value); });
      if(empresasSel.length === 0){ genericToast(elUserToast, "Marque ao menos uma empresa, ou selecione acesso a todas.", true); return; }
    }
    elBtnUserSave.disabled = true;
    try{
      var recoveryKey = genRecoveryKey();
      await db.doc("usuarios/" + usuarioKey(usuario)).set({
        usuario: usuario, senha: senha, email: email, papel: papel, areas: areasSel, todasEmpresas: todas, empresas: empresasSel,
        recoveryKey: recoveryKey, failedAttempts: 0, locked: false, createdAt: new Date().toISOString()
      });
      genericToast(elUserToast, "Usuário " + usuario + " criado.", false);
      elUserKeyRevealBox.hidden = false;
      elUserKeyRevealBox.textContent = "Chave de recuperação de " + usuario + ": " + recoveryKey;
      elUUsuario.value = ""; elUSenha.value = ""; elUPapel.value = ""; elUEmail.value = ""; elUTodasEmpresas.checked = false; elUEmpresasWrap.hidden = false;
      elUAreaList.querySelectorAll("input[type=checkbox]").forEach(function(cb){ cb.checked = false; });
      elUEmpresasList.querySelectorAll("input[type=checkbox]").forEach(function(cb){ cb.checked = false; });
    }catch(err){
      genericToast(elUserToast, "Não foi possível salvar agora. Tente novamente.", true);
    }finally{
      elBtnUserSave.disabled = false;
    }
  });

