      var tr = document.createElement("tr");
      var td = document.createElement("td"); td.colSpan = 7; td.className = "empty"; td.textContent = "Nenhum usuário cadastrado.";
      tr.appendChild(td); elTblUsuariosBody.appendChild(tr);
      return;
